function getCatalogProductText(product: ProductItem) {
  return [
    product.productName,
    product.productType,
    product.industryType,
    product.category,
    product.productFolder,
    product.stockRestockStatus,
    product.refillCycle,
    product.recommendedProductAction,
    product.productTags.join(" "),
  ].join(" ").toLowerCase();
}

function isServiceCatalogVariant(variant: OverviewVariant) {
  return variant === "fashion-service" || variant === "beauty-services" || variant === "aesthetic-clinic";
}

function getCatalogOfferRecords(baseItems: ProductItem[], variant: OverviewVariant) {
  if (isServiceCatalogVariant(variant)) {
    return serviceCatalogOfferItems.filter((item) => isWorkspaceCompatibleItem(item, variant));
  }

  if (variant === "hybrid") {
    return uniqueById([...baseItems, ...serviceCatalogOfferItems], (item) => item.id);
  }

  return baseItems;
}

function getCatalogOfferType(product: ProductItem) {
  const text = getCatalogProductText(product);

  if (text.includes("appointment") || text.includes("booking") || text.includes("fitting") || text.includes("treatment")) {
    return "Appointment-led offer";
  }

  if (text.includes("service") || text.includes("consultation") || text.includes("tailoring") || text.includes("measurement")) {
    return "Service";
  }

  if (text.includes("package") || text.includes("bundle") || text.includes("kit") || text.includes("set")) {
    return "Package / Bundle";
  }

  if (product.refillCycle !== "Not refill-led" && product.refillCycle !== "N/A") return "Refill";
  if (text.includes("restock")) return "Restock";

  return "Product";
}

function getCatalogDemandSource(product: ProductItem) {
  const offerType = getCatalogOfferType(product);

  if (offerType === "Appointment-led offer" || offerType === "Service") {
    return product.industryType === "Beauty / Skincare"
      ? "Instagram DM, WhatsApp, booking form"
      : "Website form, Instagram DM, WhatsApp";
  }

  if (product.productTags.some((tag) => tag.toLowerCase().includes("event"))) return "Event / pop-up, CSV import, manual entry";
  if (product.productTags.some((tag) => tag.toLowerCase().includes("restock"))) return "Instagram DM, restock form, website form";
  if (product.industryType === "Beauty / Skincare") return "Shopify / ecommerce, WhatsApp, Instagram DM";

  return "Instagram DM, website form, Shopify / ecommerce";
}

function getCatalogSkuInventoryImpact(product: ProductItem) {
  const offerType = getCatalogOfferType(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") {
    return product.stockRestockStatus.includes("deposit")
      ? "Deposit or appointment capacity is blocking recovery."
      : "Service capacity, available slots, or follow-up timing affects recovery.";
  }

  const text = getCatalogProductText(product);

  if (text.includes("shade")) return "Shade-level demand needs stock clarity before follow-up.";
  if (text.includes("size") || text.includes("fit") || text.includes("bridal")) return "Size, fit, or appointment context affects the next buyer reply.";
  if (text.includes("restock")) return "Restock demand is open and should trigger buyer notifications.";
  if (product.refillCycle !== "Not refill-led" && product.refillCycle !== "N/A") return `${product.refillCycle} refill timing can create repeat revenue follow-up.`;

  return `${product.skuCount} SKUs can affect availability, order recovery, and buyer guidance.`;
}

function getCatalogImpactLabel(product: ProductItem, variant?: OverviewVariant) {
  const offerType = getCatalogOfferType(product);

  if (variant === "hybrid" && (offerType === "Service" || offerType === "Appointment-led offer" || offerType === "Package / Bundle")) {
    return "SKU / Booking Impact";
  }

  if (offerType === "Service" || offerType === "Appointment-led offer") return "Booking / Capacity Impact";

  return "SKU / Inventory Impact";
}

function getCatalogFollowUpTiming(product: ProductItem) {
  const offerType = getCatalogOfferType(product);
  const text = getCatalogProductText(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") {
    if (text.includes("deposit")) return "Deposit reminder due";
    if (text.includes("renewal") || text.includes("next-session")) return "Next-session follow-up active";
    if (text.includes("consultation")) return "Consultation follow-up active";
    if (text.includes("measurement") || text.includes("fitting")) return "Appointment follow-up needed";

    return "Booking follow-up active";
  }

  if (product.refillCycle === "Not refill-led") return "Product follow-up timing active";

  return product.refillCycle;
}

function getCatalogSignalSourceRows(product: ProductItem) {
  const sources = getCatalogDemandSource(product)
    .split(",")
    .map((source) => source.trim())
    .filter(Boolean);
  const buyerTotal = Math.max(product.linkedDemandCount, sources.length);
  const valueTotal = moneyToNumber(product.openRecoveryValue);

  return sources.map((source, index) => {
    const assignedBefore = sources
      .slice(0, index)
      .reduce((total, _, sourceIndex) => total + Math.max(1, Math.round(buyerTotal / sources.length) + (sourceIndex === 0 ? 1 : 0)), 0);
    const buyers = index === sources.length - 1
      ? Math.max(1, buyerTotal - assignedBefore)
      : Math.max(1, Math.round(buyerTotal / sources.length) + (index === 0 ? 1 : 0));
    const value = index === sources.length - 1
      ? Math.max(0, valueTotal - Math.round(valueTotal / sources.length) * index)
      : Math.round(valueTotal / sources.length);
    const lower = source.toLowerCase();
    const status = lower.includes("instagram")
      ? "First reply needed"
      : lower.includes("whatsapp")
        ? "Booking reminder due"
        : lower.includes("website") || lower.includes("form")
          ? "Follow-up needed"
          : lower.includes("shopify") || lower.includes("ecommerce")
            ? "Checkout or reorder follow-up"
            : lower.includes("event") || lower.includes("csv")
              ? "Manual review needed"
              : "Recovery action open";

    return { source, buyers, recoveryValue: formatCurrencyFromNumber(value), status };
  });
}

function getCatalogBuyerSignalRows(product: ProductItem) {
  const sourceRows = getCatalogSignalSourceRows(product);
  const offerType = getCatalogOfferType(product);
  const names = ["Sophia Bennett", "Maya Ford", "Clara West", "Nadia Cole", "Ariana Hale", "Leah Moore"];
  const contexts = offerType === "Service" || offerType === "Appointment-led offer"
    ? ["Booking request", "Deposit question", "Appointment timing", "Package renewal", "Consultation follow-up", "Client rebooking"]
    : ["Size / shade question", "Restock request", "Product guidance", "Bundle interest", "Refill timing", "New drop interest"];
  const value = Math.max(250, Math.round(moneyToNumber(product.openRecoveryValue) / Math.max(1, Math.min(product.linkedDemandCount, 6))));

  return Array.from({ length: Math.min(6, Math.max(3, sourceRows.length + 2)) }, (_, index) => {
    const source = sourceRows[index % sourceRows.length]?.source ?? "Manual Entry";
    return {
      buyerName: names[index % names.length],
      source,
      interestType: contexts[index % contexts.length],
      context: product.productName,
      intent: index < 2 ? "High" : index < 4 ? "Medium" : "Low",
      revenueAtRisk: formatCurrencyFromNumber(value + index * 90),
      lastAction: index % 2 === 0 ? "Captured, no final recovery step yet" : "Follow-up drafted",
      nextAction: product.recommendedProductAction,
    };
  });
}

function getCatalogSignalStage(product: ProductItem) {
  const offerType = getCatalogOfferType(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") {
    return [
      { label: "Booking requests", value: `${product.linkedDemandCount}`, note: "Clients asking for slots, consultation, fitting, or package timing." },
      { label: "Available slots / capacity", value: product.stockRestockStatus, note: "Capacity decides whether the recovery action can convert quickly." },
      { label: "Deposit status", value: product.productTags.some((tag) => tag.toLowerCase().includes("deposit")) ? "Deposit follow-up open" : "Deposit not required yet", note: "Deposit reminders should only show when payment or booking confirmation is needed." },
      { label: "Follow-up timing", value: getCatalogFollowUpTiming(product), note: "Service timing should never use product-only refill wording." },
    ];
  }

  return [
    { label: "SKU count", value: `${product.skuCount}`, note: "Active SKUs, variants, sizes, shades, or package items linked to the offer." },
    { label: "Stock / restock status", value: product.stockRestockStatus, note: "Inventory context affects buyer replies and recovery timing." },
    { label: "Refill / drop timing", value: getCatalogFollowUpTiming(product), note: "Used for refill, restock, new drop, and repeat revenue follow-up." },
    { label: "Package / bundle signal", value: getCatalogPackageOpportunity(product) ? "Package opportunity open" : "No package signal attached", note: getCatalogPackageOpportunity(product) || "This record is currently product-led." },
  ];
}

function getCatalogPackageOpportunity(product: ProductItem) {
  const offerType = getCatalogOfferType(product);
  const text = getCatalogProductText(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") {
    return `Package opportunity: ${product.productName} can recover ${product.openRecoveryValue} through booking, deposit, and follow-up actions.`;
  }

  if (offerType === "Package / Bundle" || text.includes("bundle") || text.includes("kit") || text.includes("set")) {
    return `Package opportunity: ${product.productName} has ${product.linkedDemandCount} interested buyers and ${product.openRecoveryValue} open value.`;
  }

  if (text.includes("bridal") || text.includes("appointment")) {
    return "Package opportunity: product interest can connect to fitting, styling, appointment, or deposit follow-up.";
  }

  return "";
}

function getCatalogRecoveryType(product: ProductItem) {
  const offerType = getCatalogOfferType(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") return "Booking / deposit recovery";
  if (offerType === "Package / Bundle") return "Bundle / package recovery";
  if (offerType === "Refill") return "Refill / reorder recovery";
  if (offerType === "Restock") return "Restock recovery";

  return product.industryType === "Beauty / Skincare" ? "Product reorder recovery" : "Product demand recovery";
}

function getCatalogProductSignal(product: ProductItem) {
  const offerType = getCatalogOfferType(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") return "Service / booking signal";
  if (offerType === "Package / Bundle") return "Product + package signal";
  if (offerType === "Refill") return "Product refill signal";
  if (offerType === "Restock") return "Product restock signal";

  return "Product / SKU signal";
}

function getCatalogProductSignalDetail(product: ProductItem) {
  const offerType = getCatalogOfferType(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") {
    return "Interested clients are tied to booking demand, deposit timing, and appointment follow-up.";
  }

  if (offerType === "Package / Bundle") {
    return "Buyer intent is connected to product combinations, package value, and follow-up timing.";
  }

  if (offerType === "Refill") {
    return "Repeat purchase intent is tied to refill timing, routine stage, and reorder follow-up.";
  }

  if (offerType === "Restock") {
    return "Demand is waiting on stock clarity, restock timing, and buyer notification.";
  }

  return "Buyer interest is connected to SKU availability, size or shade clarity, and product guidance.";
}

function getCatalogNextActionTitle(product: ProductItem) {
  const offerType = getCatalogOfferType(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") return "Booking / deposit follow-up";
  if (offerType === "Package / Bundle") return "Package recovery follow-up";
  if (offerType === "Refill") return "Refill recovery follow-up";
  if (offerType === "Restock") return "Restock notification action";

  return "Product recovery follow-up";
}

function getCatalogPackageSignalTitle(product: ProductItem) {
  const packageOpportunity = getCatalogPackageOpportunity(product);

  return packageOpportunity ? "Package opportunity open" : "No package signal attached";
}

function getCatalogPackageSignalDetail(product: ProductItem) {
  const packageOpportunity = getCatalogPackageOpportunity(product);

  if (packageOpportunity) return packageOpportunity;

  const offerType = getCatalogOfferType(product);

  if (offerType === "Service" || offerType === "Appointment-led offer") {
    return "Keep the service record ready for booking, deposit, and package follow-up if client intent expands.";
  }

  return "Use linked demand, SKU availability, and recovery value before attaching a bundle opportunity.";
}

function getCatalogCopyForVariant(variant: OverviewVariant) {
  if (isServiceCatalogVariant(variant)) {
    return {
      title: "Product & Service Catalog",
      listTitle: "Service & Package Offers",
      description: "Service, appointment, package, booking, deposit, and recovery value records that guide daily follow-up.",
      countLabel: "services",
      primaryKpi: "Services Tracked",
      activeKpi: "Active Services",
      valueLabel: "Open Booking Value",
      recoveredLabel: "Recovered Booking Value",
    };
  }

  if (variant === "hybrid") {
    return {
      title: "Product & Service Catalog",
      listTitle: "Offer Intelligence",
      description: "Products, services, packages, SKUs, bookings, inventory signals, demand sources, and recovery value in one place.",
      countLabel: "offers",
      primaryKpi: "Offers Tracked",
      activeKpi: "Active Offers",
      valueLabel: "Open Recovery Value",
      recoveredLabel: "Recovered Value",
    };
  }

  return {
    title: "Product Catalog",
    listTitle: "Product Catalog",
    description: "Products connected to demand, restock interest, refill timing, inventory context, recovery value, and recovered revenue.",
    countLabel: "products",
    primaryKpi: "Products Tracked",
    activeKpi: "Active SKUs",
    valueLabel: "Open Recovery Value",
    recoveredLabel: "Recovered Value",
  };
}

