function getCaptureSourceIconName(source: string): CaptureIconName {
  const lower = source.toLowerCase();
  if (lower.includes("instagram") || lower.includes("meta")) return "instagram";
  if (lower.includes("whatsapp")) return "whatsapp";
  if (lower.includes("email")) return "email";
  if (lower.includes("website") || lower.includes("form")) return "globe";
  if (lower.includes("shopify") || lower.includes("ecommerce") || lower.includes("online store")) return "shop";
  if (lower.includes("event") || lower.includes("pop")) return "calendar";
  if (lower.includes("campaign")) return "megaphone";
  if (lower.includes("referral")) return "users";
  if (lower.includes("manual")) return "pencil";
  return "message";
}

function getDemandTypeIconName(value: string): CaptureIconName {
  const lower = value.toLowerCase();
  if (lower.includes("size") || lower.includes("fit")) return "ruler";
  if (lower.includes("restock") || lower.includes("reorder") || lower.includes("refill") || lower.includes("drop")) return "refresh";
  if (lower.includes("payment") || lower.includes("deposit")) return "payment";
  if (lower.includes("appointment") || lower.includes("booking") || lower.includes("calendar") || lower.includes("consultation")) return "calendar";
  if (lower.includes("owner") || lower.includes("route")) return "owner";
  if (lower.includes("risk") || lower.includes("issue")) return "alert";
  return "package";
}

function isCaptureServiceContext(record: { recordKind?: string; serviceContext?: string; serviceType?: string; appointmentDate?: string; appointmentStatus?: string; calendarRisk?: string; demandType?: string; productInterest?: string; productContext?: string; productOrderContext?: string }) {
  const combined = [record.recordKind, record.serviceContext, record.serviceType, record.appointmentDate, record.appointmentStatus, record.calendarRisk, record.demandType, record.productInterest, record.productContext, record.productOrderContext]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  return Boolean(
    record.recordKind === "service" ||
    combined.includes("appointment") ||
    combined.includes("booking") ||
    combined.includes("consultation") ||
    combined.includes("fitting") ||
    combined.includes("alteration") ||
    combined.includes("treatment") ||
    combined.includes("deposit") ||
    combined.includes("rebooking"),
  );
}

function captureFallbackText(value: unknown, fallback: string) {
  return typeof value === "string" && value.trim() ? value : fallback;
}

function buildCaptureProductDetail(record: Record<string, unknown>): CaptureDetailRecord {
  const title = captureFallbackText(record.productInterest ?? record.productContext ?? record.productOrderContext ?? record.demandName ?? record.productName, "Product recovery context");
  const category = captureFallbackText(record.industryType ?? record.productCategory ?? record.category ?? record.demandType, "Fashion / Apparel");
  const value = captureFallbackText(record.estimatedValue ?? record.estimatedDemandValue ?? record.recoverableValue ?? record.paymentPendingValue ?? record.value, "Open value");
  const owner = captureFallbackText(record.owner ?? record.assignedOwner ?? record.sourceOwner, "Needs owner review");
  const source = captureFallbackText(record.inquirySource ?? record.source ?? record.sourceName, "Captured source");
  const status = captureFallbackText(record.firstReplyStatus ?? record.stockStatus ?? record.sourceHealthStatus ?? record.status, "Needs review");
  const recommendedAction = captureFallbackText(record.recommendedAction ?? record.recommendedNextAction ?? record.recommendedFix ?? record.nextAction, "Review and prepare the next recovery action.");
  const demandType = captureFallbackText(record.demandType ?? record.leakType ?? record.entryType, "Product demand");
  return {
    kind: "product",
    title,
    subtitle: captureFallbackText(record.skuVariant ?? record.sizeShadeColor ?? record.productContext ?? record.productOrderContext ?? record.originalProductInterest, demandType),
    category,
    value,
    status,
    owner,
    source,
    recommendedAction,
    badges: [demandType, source, status].filter(Boolean).slice(0, 4),
    metrics: [
      { label: "Money still open", value },
      { label: "Owner", value: owner },
      { label: "Source", value: source },
      { label: "Status", value: status },
      { label: "Open signals", value: String(record.totalSignals ?? record.actionableSignalCount ?? record.openRecoveryActions ?? "Review") },
      { label: "Recovered proof", value: captureFallbackText(record.recoveredValue, "Not logged") },
    ],
    notes: [
      captureFallbackText(record.recommendedAction ?? record.recommendedNextAction ?? record.nextAction ?? record.recommendedFix, "Prepare a recovery follow-up from this product context."),
      "This is recovery context only — no inventory, logistics, or backend action is created automatically.",
    ],
  };
}

function buildCaptureServiceDetail(record: Record<string, unknown>): CaptureDetailRecord {
  const title = captureFallbackText(record.serviceContext ?? record.serviceType ?? record.productInterest ?? record.demandName ?? record.productContext, "Service recovery context");
  const value = captureFallbackText(record.estimatedServiceValue ?? record.estimatedValue ?? record.estimatedDemandValue ?? record.recoverableValue ?? record.paymentPendingValue ?? record.value, "Open value");
  const owner = captureFallbackText(record.owner ?? record.serviceProvider ?? record.sourceOwner, "Needs owner review");
  const source = captureFallbackText(record.inquirySource ?? record.source ?? record.sourceName, "Captured source");
  const status = captureFallbackText(record.appointmentStatus ?? record.depositStatus ?? record.status, "Follow-up due");
  const recommendedAction = captureFallbackText(record.nextCalendarAction ?? record.recommendedAction ?? record.recommendedNextAction ?? record.nextAction ?? record.recommendedFix, "Review and prepare the service follow-up.");
  return {
    kind: "service",
    title,
    subtitle: captureFallbackText(record.appointmentDate ?? record.appointmentTime ?? record.duration ?? record.calendarRisk, "Appointment / booking context"),
    category: captureFallbackText(record.serviceType ?? record.category, "Service / appointment"),
    value,
    status,
    owner,
    source,
    recommendedAction,
    badges: ["Service", status, source].filter(Boolean).slice(0, 4),
    metrics: [
      { label: "Money still open", value },
      { label: "Owner / provider", value: owner },
      { label: "Booking status", value: status },
      { label: "Deposit", value: captureFallbackText(record.depositStatus, "Not required") },
      { label: "Duration / slot", value: captureFallbackText(record.duration ?? record.nextAvailableSlot, "To confirm") },
      { label: "Recovered proof", value: captureFallbackText(record.recoveredValue, "Not logged") },
    ],
    notes: [
      recommendedAction,
      "This is service recovery context only — no booking calendar or staff scheduling system is added.",
    ],
  };
}

function captureSvgDataUri(svg: string) {
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg.trim())}`;
}

