function normalizeProductImageKey(value: string) {
  return value
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/\+/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function getFallbackProductImage(industryType?: string, recordKind?: string) {
  const combined = `${industryType ?? ""} ${recordKind ?? ""}`.toLowerCase();

  if (
    combined.includes("service") ||
    combined.includes("appointment") ||
    combined.includes("booking") ||
    combined.includes("consultation") ||
    combined.includes("treatment") ||
    combined.includes("fitting") ||
    combined.includes("package")
  ) {
    return "/assets/products/service-fallback-visual.jpg";
  }

  if (
    combined.includes("beauty") ||
    combined.includes("skincare") ||
    combined.includes("skin") ||
    combined.includes("serum") ||
    combined.includes("routine") ||
    combined.includes("shade")
  ) {
    return "/assets/products/beauty-fallback-product.jpg";
  }

  return "/assets/products/fashion-fallback-product.jpg";
}

function getProductImageUrl(productName: string, industryType?: string, recordKind?: string) {
  const combined = normalizeProductImageKey(`${productName} ${industryType ?? ""} ${recordKind ?? ""}`);

  if (
    recordKind === "service" ||
    combined.includes("service") ||
    combined.includes("appointment") ||
    combined.includes("booking") ||
    combined.includes("consultation") ||
    combined.includes("treatment") ||
    combined.includes("fitting") ||
    combined.includes("deposit") ||
    combined.includes("tailoring") ||
    combined.includes("measurement") ||
    combined.includes("renewal")
  ) {
    if (combined.includes("bridal") || combined.includes("fitting") || combined.includes("deposit")) return productImageMap["Bridal fitting + deposit package"];
    if (combined.includes("tailoring") || combined.includes("measurement") || combined.includes("custom")) return productImageMap["Custom tailoring measurement request"];
    if (combined.includes("skin") || combined.includes("consultation") || combined.includes("routine")) return productImageMap["Skin consultation + routine package"];
    if (combined.includes("aesthetic") || combined.includes("treatment") || combined.includes("renewal")) return productImageMap["Aesthetic treatment package renewal"];
    return getFallbackProductImage(industryType, "service");
  }

  const directEntry = Object.entries(productImageMap).find(([name]) => normalizeProductImageKey(name) === normalizeProductImageKey(productName));
  if (directEntry) return directEntry[1];

  const fuzzyEntry = Object.entries(productImageMap).find(([name]) => {
    const key = normalizeProductImageKey(name);
    return key.length > 4 && (combined.includes(key) || key.split(" ").filter((part) => part.length > 2).every((part) => combined.includes(part)));
  });
  if (fuzzyEntry) return fuzzyEntry[1];

  if (combined.includes("atelier") || combined.includes("bridal") || combined.includes("dress") || combined.includes("capsule")) return productImageMap["Atelier Luma bridal capsule dress"];
  if (combined.includes("harper") || (combined.includes("denim") && combined.includes("row"))) return productImageMap["Harper Row denim"];
  if (combined.includes("cropped") || combined.includes("jacket")) return productImageMap["Denim cropped jacket"];
  if (combined.includes("rue") || combined.includes("muse") || combined.includes("knitwear") || combined.includes("new drop")) return productImageMap["Rue Muse knitwear new drop"];
  if (combined.includes("velvet") || combined.includes("lane") || combined.includes("reserved") || combined.includes("order pieces")) return productImageMap["Velvet Lane order pieces"];
  if (combined.includes("limited") || combined.includes("restock") || combined.includes("waitlist")) return productImageMap["Limited restock pieces"];

  if (combined.includes("vitamin") || combined.includes("serum")) return productImageMap["Vitamin C serum"];
  if (combined.includes("sensitive") || combined.includes("starter")) return productImageMap["Sensitive skin starter kit"];
  if (combined.includes("saffron") || combined.includes("cleanser")) return productImageMap["Saffron Skin cleanser set"];
  if (combined.includes("coco") || combined.includes("lip oil") || combined.includes("shade")) return productImageMap["Coco Bloom lip oil shade"];
  if (combined.includes("routine") || combined.includes("bundle")) return productImageMap["Routine bundle"];
  if (combined.includes("night") || combined.includes("repair") || combined.includes("cream")) return productImageMap["Night repair cream"];

  return getFallbackProductImage(industryType, recordKind);
}

function getProductImageAlt(productName: string, industryType?: string) {
  const label = productName.trim() || "Product recovery context";
  const industry = industryType?.trim();
  return industry ? `${label} — ${industry} recovery visual` : `${label} recovery visual`;
}

function ProductImageFrame({
  productName,
  industryType,
  recordKind,
  className = "",
}: {
  productName: string;
  industryType?: string;
  recordKind?: string;
  className?: string;
}) {
  const [imageFailed, setImageFailed] = useState(false);
  const imageUrl = getProductImageUrl(productName, industryType, recordKind);
  const iconName: CaptureIconName = recordKind === "service" ? "calendar" : "package";

  if (imageFailed) {
    return (
      <span className={`product-image-fallback ${className}`.trim()} aria-label={getProductImageAlt(productName, industryType)}>
        <CaptureIcon name={iconName} />
      </span>
    );
  }

  return (
    <img
      className={`product-image-frame ${className}`.trim()}
      src={imageUrl}
      alt={getProductImageAlt(productName, industryType)}
      loading="lazy"
      onError={() => setImageFailed(true)}
    />
  );
}

