type WebsiteSyncStatus = "not-synced" | "sync-pending" | "synced" | "sync-failed";
type MediaPickerTarget = { targetType: "product" | "sku"; targetId: string };

type ProductImageState = {
  imageUrl: string;
  imageAlt: string;
  imageFileName: string;
  imageSource: ProductImageSource;
  imageStatus: ProductImageStatus;
  websiteSyncStatus: WebsiteSyncStatus;
  lastImageUpdated: string;
  syncLog: string[];
};

type MediaAsset = {
  id: string;
  imageUrl: string;
  fileName: string;
  name: string;
  categoryTag: string;
  source: "media-library" | "uploaded";
};

