function getMediaAssetAlt(asset: MediaAsset) {
  return `${asset.name} product recovery image`;
}

function getProductImageStatus(image?: ProductImageState) {
  if (!image) return "missing" as ProductImageStatus;
  return image.imageStatus;
}

function getImageStatusLabel(status: ProductImageStatus) {
  const labels: Record<ProductImageStatus, string> = {
    missing: "Image missing",
    ready: "Image ready",
    "sync-pending": "Sync pending",
    synced: "Synced to website",
    "sync-failed": "Sync failed",
  };
  return labels[status];
}

function getWebsiteSyncLabel(status: WebsiteSyncStatus) {
  const labels: Record<WebsiteSyncStatus, string> = {
    "not-synced": "Not synced",
    "sync-pending": "Sync pending",
    synced: "Synced",
    "sync-failed": "Sync failed",
  };
  return labels[status];
}

function buildProductImageState(asset: MediaAsset, status: ProductImageStatus = "ready"): ProductImageState {
  const syncStatus: WebsiteSyncStatus = status === "synced" ? "synced" : status === "sync-failed" ? "sync-failed" : status === "sync-pending" ? "sync-pending" : "not-synced";
  return {
    imageUrl: asset.imageUrl,
    imageAlt: getMediaAssetAlt(asset),
    imageFileName: asset.fileName,
    imageSource: asset.source,
    imageStatus: status,
    websiteSyncStatus: syncStatus,
    lastImageUpdated: "Selected now",
    syncLog: ["Image selected", "Product row updated", syncStatus === "synced" ? "Website sync completed" : "Waiting for website sync"],
  };
}

function ProductManagedImage({
  image,
  productName,
  industryType,
  recordKind,
  size = "card",
  onOpenPicker,
  onRemove,
  onSync,
}: {
  image?: ProductImageState;
  productName: string;
  industryType?: string;
  recordKind?: string;
  size?: "card" | "detail" | "sheet";
  onOpenPicker: () => void;
  onRemove?: () => void;
  onSync?: () => void;
}) {
  const [failed, setFailed] = useState(false);
  const fallbackUrl = getFallbackProductImage(industryType, recordKind);
  const hasImage = Boolean(image?.imageUrl);
  const src = hasImage && !failed ? image?.imageUrl : fallbackUrl;
  const status = getProductImageStatus(image);

  return (
    <div className={`product-image-card ${size === "detail" ? "is-detail" : ""} ${size === "sheet" ? "is-sheet" : ""}`}>
      <button type="button" className="product-image-clickable" onClick={onOpenPicker}>
        <span className={`product-image-frame ${!hasImage ? "product-image-fallback" : ""}`}>
          <img
            src={src}
            alt={hasImage ? image?.imageAlt ?? getProductImageAlt(productName, industryType) : getProductImageAlt(productName, industryType)}
            loading="lazy"
            onError={() => setFailed(true)}
          />
          {!hasImage ? <span className="product-image-empty-label">Add image</span> : null}
        </span>
      </button>

      {size !== "sheet" ? (
        <div className="product-image-meta">
          <span className={`image-status-chip ${status}`}>{getImageStatusLabel(status)}</span>
          <strong>{hasImage ? image?.imageFileName : "No image selected"}</strong>
          {size === "detail" && image ? <small>Last updated: {image.lastImageUpdated}</small> : null}
        </div>
      ) : null}

      <div className="product-image-actions">
        <button type="button" onClick={onOpenPicker}>{hasImage ? "Replace image" : "Add image"}</button>
        {hasImage && onRemove ? <button type="button" onClick={onRemove}>Remove</button> : null}
        {hasImage && onSync && size === "detail" ? <button type="button" onClick={onSync}>Push update to website</button> : null}
      </div>
    </div>
  );
}

function MediaLibraryModal({
  assets,
  targetLabel,
  onClose,
  onApply,
  onAddUploadedAsset,
}: {
  assets: MediaAsset[];
  targetLabel: string;
  onClose: () => void;
  onApply: (asset: MediaAsset) => void;
  onAddUploadedAsset: (asset: MediaAsset) => void;
}) {
  const [activeTab, setActiveTab] = useState<"assets" | "upload">("assets");
  const [selectedAssetId, setSelectedAssetId] = useState(assets[0]?.id ?? "");
  const [uploadPreview, setUploadPreview] = useState("");
  const [uploadFileName, setUploadFileName] = useState("");
  const [uploadName, setUploadName] = useState("");
  const [uploadTag, setUploadTag] = useState("Product image");

  const selectedAsset = assets.find((asset) => asset.id === selectedAssetId) ?? assets[0];

  function handleFiles(files: FileList | null) {
    const file = files?.[0];
    if (!file) return;

    const validTypes = ["image/jpeg", "image/png", "image/webp"];
    if (!validTypes.includes(file.type)) return;

    setUploadPreview(URL.createObjectURL(file));
    setUploadFileName(file.name);
    setUploadName(file.name.replace(/\.[^.]+$/, "").replace(/[-_]+/g, " "));
  }

  function addUploadedAsset(useImmediately = false) {
    if (!uploadPreview || !uploadFileName) return;

    const nextAsset: MediaAsset = {
      id: `uploaded-${Date.now()}`,
      imageUrl: uploadPreview,
      fileName: uploadFileName,
      name: uploadName.trim() || uploadFileName,
      categoryTag: uploadTag.trim() || "Uploaded asset",
      source: "uploaded",
    };

    onAddUploadedAsset(nextAsset);
    setSelectedAssetId(nextAsset.id);
    setActiveTab("assets");

    if (useImmediately) onApply(nextAsset);
  }

  return (
    <ModalShell title="Media Library / Product Image Picker" onClose={onClose} wide>
      <div className="media-picker-modal">
        <div className="media-picker-header-note">
          <div>
            <span>Apply image to</span>
            <strong>{targetLabel}</strong>
          </div>
          <p>Permanent upload and website sync require backend storage/API. This screen stores image previews in frontend state for now.</p>
        </div>

        <div className="media-picker-tabs">
          <button type="button" className={activeTab === "assets" ? "is-active" : ""} onClick={() => setActiveTab("assets")}>Uploaded Assets</button>
          <button type="button" className={activeTab === "upload" ? "is-active" : ""} onClick={() => setActiveTab("upload")}>Upload New</button>
        </div>

        {activeTab === "assets" ? (
          <>
            <div className="media-picker-grid">
              {assets.map((asset) => (
                <article className={`media-picker-card ${selectedAssetId === asset.id ? "is-selected" : ""}`} key={asset.id}>
                  <button type="button" onClick={() => setSelectedAssetId(asset.id)}>
                    <img src={asset.imageUrl} alt={getMediaAssetAlt(asset)} loading="lazy" />
                    <span>{asset.categoryTag}</span>
                    <strong>{asset.fileName}</strong>
                  </button>
                  <button type="button" className="secondary-btn" onClick={() => onApply(asset)}>
                    Select image
                  </button>
                </article>
              ))}
            </div>

            <div className="media-picker-footer">
              <button type="button" className="secondary-btn" onClick={onClose}>Cancel</button>
              <button type="button" className="primary-btn" disabled={!selectedAsset} onClick={() => selectedAsset && onApply(selectedAsset)}>
                Use selected image
              </button>
            </div>
          </>
        ) : (
          <div className="media-upload-panel">
            <label
              className="media-upload-zone"
              onDrop={(event) => {
                event.preventDefault();
                handleFiles(event.dataTransfer.files);
              }}
              onDragOver={(event) => event.preventDefault()}
            >
              <CaptureIcon name="package" />
              <strong>Drop product image here</strong>
              <span>JPG, PNG, or WEBP only</span>
              <input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => handleFiles(event.target.files)} />
            </label>

            <div className="media-preview-card">
              {uploadPreview ? <img src={uploadPreview} alt="Selected upload preview" /> : <span>No upload selected yet</span>}
              <label>
                <span>Image name</span>
                <input value={uploadName} onChange={(event) => setUploadName(event.target.value)} placeholder="Image display name" />
              </label>
              <label>
                <span>Category / tag</span>
                <input value={uploadTag} onChange={(event) => setUploadTag(event.target.value)} placeholder="Fashion / Beauty / Service" />
              </label>
              <div className="media-picker-footer">
                <button type="button" className="secondary-btn" disabled={!uploadPreview} onClick={() => addUploadedAsset(false)}>Add to media library</button>
                <button type="button" className="primary-btn" disabled={!uploadPreview} onClick={() => addUploadedAsset(true)}>Use this image</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </ModalShell>
  );
}


function getCaptureProductImageSrc(detail: CaptureDetailRecord) {
  return getProductImageUrl(detail.title, detail.category, detail.kind);
}


