function getWorkspaceProfile(): WorkspaceOnboardingProfile {
  return loadWorkspaceProfileFromStorage() ?? normalizeWorkspaceProfile(defaultWorkspaceProfile);
}

function overviewProfileLabels(profile: WorkspaceOnboardingProfile) {
  return [
    profile.businessType,
    profile.nicheDetail,
    ...(profile.nicheDetails ?? []),
    profile.productNiche,
    ...(profile.productNiches ?? []),
    profile.serviceNiche,
    ...(profile.serviceNiches ?? []),
    profile.otherNicheDetail,
    profile.otherProductNiche,
    profile.otherServiceNiche,
  ]
    .filter(Boolean)
    .map((item) => String(item).toLowerCase());
}

function overviewPrimaryNicheLabels(profile: WorkspaceOnboardingProfile) {
  return [profile.nicheDetail, ...(profile.nicheDetails ?? []), profile.otherNicheDetail]
    .filter(Boolean)
    .map((item) => String(item).toLowerCase());
}

function overviewHybridProductLabels(profile: WorkspaceOnboardingProfile) {
  return [profile.productNiche, ...(profile.productNiches ?? []), profile.otherProductNiche]
    .filter(Boolean)
    .map((item) => String(item).toLowerCase());
}

function overviewHybridServiceLabels(profile: WorkspaceOnboardingProfile) {
  return [profile.serviceNiche, ...(profile.serviceNiches ?? []), profile.otherServiceNiche]
    .filter(Boolean)
    .map((item) => String(item).toLowerCase());
}

function overviewLabelsHave(labels: string[], values: string[]) {
  return values.some((value) => labels.some((label) => label.includes(value.toLowerCase())));
}

type WorkspaceIndustryFamily = "fashion" | "beauty" | "retail" | "mixed";

function getWorkspaceIndustryFamily(profile: WorkspaceOnboardingProfile): WorkspaceIndustryFamily {
  const businessType = normalizeBusinessTypeValue(profile.businessType);
  const businessCategory = String(profile.businessCategory ?? "").toLowerCase();

  if (businessType === "fashion-apparel" || businessCategory.includes("fashion")) return "fashion";
  if (businessType === "beauty-products" || businessType === "beauty-services" || businessCategory.includes("beauty")) return "beauty";
  if (businessType === "retail-products" || businessCategory.includes("retail")) return "retail";

  const productLabels = overviewHybridProductLabels(profile);
  const serviceLabels = overviewHybridServiceLabels(profile);
  const allLabels = [...productLabels, ...serviceLabels, ...overviewPrimaryNicheLabels(profile)];

  const hasFashion = overviewLabelsHave(allLabels, [
    "fashion",
    "apparel",
    "clothing",
    "boutique",
    "bridalwear",
    "bridal fitting",
    "tailoring",
    "stitching",
    "alterations",
    "fittings",
    "formalwear",
    "streetwear",
    "modest",
    "accessories",
    "styling",
  ]);
  const hasBeauty = overviewLabelsHave(allLabels, [
    "beauty",
    "cosmetic",
    "skincare",
    "makeup",
    "haircare",
    "hair",
    "salon",
    "nail",
    "lash",
    "brow",
    "spa",
    "facial",
    "aesthetic",
    "clinic",
    "treatment",
    "fragrance",
    "body care",
  ]);
  const hasRetail = overviewLabelsHave(allLabels, [
    "retail",
    "store",
    "marketplace",
    "commerce",
    "online",
    "whatsapp",
    "pop-up",
    "event seller",
    "manual order",
  ]);

  if (hasFashion && !hasBeauty) return "fashion";
  if (hasBeauty && !hasFashion) return "beauty";
  if (hasRetail && !hasFashion && !hasBeauty) return "retail";
  return "mixed";
}

function overviewHasAny(profile: WorkspaceOnboardingProfile, values: string[]) {
  return overviewLabelsHave(overviewProfileLabels(profile), values);
}

function getOverviewVariant(profile: WorkspaceOnboardingProfile): OverviewVariant {
  const businessType = normalizeBusinessTypeValue(profile.businessType);

  if (businessType === "retail-products") return "retail";
  if (businessType === "beauty-products") return "beauty-products";

  if (businessType === "beauty-services") {
    return overviewLabelsHave(overviewPrimaryNicheLabels(profile), ["aesthetic clinic"]) ? "aesthetic-clinic" : "beauty-services";
  }

  if (businessType === "fashion-apparel") {
    return overviewLabelsHave(overviewPrimaryNicheLabels(profile), ["custom tailoring", "stitching", "bridal", "formalwear", "alterations", "fittings"])
      ? "fashion-service"
      : "fashion";
  }

  if (businessType === "hybrid") {
    const productLabels = overviewHybridProductLabels(profile);
    const serviceLabels = overviewHybridServiceLabels(profile);
    const hasProduct = productLabels.length > 0;
    const hasService = serviceLabels.length > 0;

    if (hasProduct && !hasService) {
      if (overviewLabelsHave(productLabels, ["fashion", "accessories"])) return "fashion";
      if (overviewLabelsHave(productLabels, ["beauty", "skincare", "makeup", "haircare"])) return "beauty-products";
      return "retail";
    }

    if (hasService && !hasProduct) {
      if (overviewLabelsHave(serviceLabels, ["aesthetic clinic"])) return "aesthetic-clinic";
      if (overviewLabelsHave(serviceLabels, ["tailoring", "fittings", "bridal styling"])) return "fashion-service";
      return "beauty-services";
    }

    return "hybrid";
  }

  return "fashion";
}

