function getWorkspaceItemText(item: unknown) {
  try {
    return JSON.stringify(item).toLowerCase();
  } catch {
    return String(item ?? "").toLowerCase();
  }
}

function isWorkspaceCompatibleItem(item: unknown, variant: OverviewVariant) {
  const text = getWorkspaceItemText(item);
  return !(workspaceVariantBannedTerms[variant] ?? []).some((term) => text.includes(term));
}

function filterWorkspaceItems<T>(items: T[], variant: OverviewVariant) {
  if (variant === "hybrid") return items;
  return items.filter((item) => isWorkspaceCompatibleItem(item, variant));
}

