function mapSeedToRecoveryTask(seed: WorkspaceQueueSeed, variant: OverviewVariant, index: number): RecoveryTask {
  const paymentLike = /payment|deposit|checkout/i.test(seed.issue + seed.context);
  const repeatLike = /reorder|restock|repeat|rebooking|package|next-session|next session/i.test(seed.issue + seed.context);
  const postLike = /review|referral|ugc|post/i.test(seed.issue + seed.context);
  const orderRiskLike = /delivery|order risk|return|exchange|address|no-show|appointment/i.test(seed.issue + seed.context);

  const category: RecoveryCategory = paymentLike
    ? "Payment Recovery"
    : postLike
      ? "Post-Purchase"
      : orderRiskLike && seed.kind === "product"
        ? "Order Risk"
        : repeatLike
          ? "Refill/Restock"
          : "Inquiry Follow-up";

  const leakType: LeakType = paymentLike
    ? "Payment pending leak"
    : repeatLike
      ? "Repeat purchase leak"
      : postLike
        ? "Post-purchase leak"
        : "Inquiry leak";

  return {
    id: `TQ-${variant}-${index + 1}`,
    customer: seed.customer,
    brandContext: seed.kind === "service" ? seed.context : seed.context,
    productInterest: seed.issue,
    leakType,
    category,
    estimatedRevenueAtRisk: seed.value,
    source: seed.source,
    assignedOwner: seed.owner,
    dueStatus: seed.dueStatus,
    priority: seed.priority,
    recommendedNextAction: seed.nextAction,
    messageTemplate: seed.template,
    internalRecoveryThread: [
      {
        id: `TQ-${variant}-${index + 1}-thread-1`,
        author: "Altynx",
        role: "System",
        message: `Recovery signal captured from ${seed.source}. Next action recommended: ${seed.nextAction}`,
        time: "Now",
      },
    ],
    automationStatus: "Prepared for dashboard review. Nothing is sent until reviewed or approved.",
    sourceStatus: `${seed.source} signal ready`,
    lastEvent: seed.issue,
    lastContact: index % 2 === 0 ? "No clear follow-up yet" : "Follow-up window active",
    attemptCount: index % 3,
    tone: index % 5 === 0 ? "rose" : index % 5 === 1 ? "amber" : index % 5 === 2 ? "cyan" : index % 5 === 3 ? "emerald" : "indigo",
    workspaceVariant: variant,
    allowedVariants: [variant],
    recordKind: seed.kind,
    queueBadges: seed.badges,
    templateStatus: "Needs review",
    reviewStatus: "Unreviewed",
    queueReady: false,
    relatedCase: `${seed.kind === "service" ? "APPT" : "CASE"}-${variant.toUpperCase()}-${index + 1}`,
    productOrderContext: seed.kind === "product" ? seed.context : undefined,
    serviceContext: seed.kind === "service" ? seed.context : undefined,
    auditTrail: [`Signal captured from ${seed.source}.`],
    ...seed.calendar,
  };
}

function makeWorkspaceRecoveryTasks(profile: WorkspaceOnboardingProfile): RecoveryTask[] {
  const variant = getWorkspaceVariant(profile);
  return getWorkspaceQueueSeeds(variant, profile).map((seed, index) => mapSeedToRecoveryTask(seed, variant, index));
}

function makeWorkspaceInquiries(profile: WorkspaceOnboardingProfile): Inquiry[] {
  const variant = getWorkspaceVariant(profile);
  const risks = getOverviewRiskItems(profile);
  const generated = risks.map((risk, index): Inquiry => ({
    id: `INQ-${risk.id}`,
    customer: risk.buyerName,
    inquirySource: risk.source,
    timeSinceInquiry: index === 0 ? "2 hours" : `${index + 3} hours`,
    firstReplyStatus: index < 2 ? "Not replied" : "Reply drafted",
    productInterest: risk.context,
    intentLevel: index < 3 ? "High" : "Medium",
    estimatedValue: risk.valueAtRisk,
    owner: risk.owner,
    automationStatus: "Captured for recovery review",
    recommendedAction: risk.nextAction,
    templatePreview: risk.messageTemplate,
    sourceStatus: `${risk.source} signal`,
    internalNotes: index,
    tone: risk.tone,
    workspaceVariant: variant,
    allowedVariants: [variant],
    recordKind: risk.recoveryType === "Service" ? "service" : risk.recoveryType === "Hybrid" ? "hybrid" : "product",
    inquiryBadges: [risk.recoveryType, risk.priority, risk.status].filter(Boolean),
    reviewed: false,
    queueReady: false,
    relatedCase: `INQ-${risk.id}-CASE`,
    auditTrail: [`Inquiry captured from ${risk.source}.`, `Template matched for ${risk.context}.`],
    recoveryLog: [`${risk.source} signal captured.`, `Recommended action prepared: ${risk.nextAction}`],
    templateStatus: "Needs review",
    productContext: risk.recoveryType === "Service" ? undefined : risk.context,
    serviceContext: risk.recoveryType === "Service" ? risk.context : undefined,
    appointmentDate: risk.recoveryType === "Service" ? "Next available" : undefined,
    appointmentTime: risk.recoveryType === "Service" ? "To confirm" : undefined,
    appointmentStatus: risk.recoveryType === "Service" ? "Needs confirmation" : undefined,
    depositStatus: /deposit/i.test(risk.context + risk.nextAction) ? "Pending" : risk.recoveryType === "Service" ? "Not required" : undefined,
    serviceProvider: risk.recoveryType === "Service" ? risk.owner : undefined,
    serviceType: risk.recoveryType === "Service" ? risk.context : undefined,
    duration: risk.recoveryType === "Service" ? "45–60 min" : undefined,
    nextAvailableSlot: risk.recoveryType === "Service" ? "Today 4:30 PM or tomorrow 11:00 AM" : undefined,
    calendarRisk: risk.recoveryType === "Service" ? (/deposit/i.test(risk.context + risk.nextAction) ? "Deposit missing" : "Appointment not confirmed") : undefined,
  }));

  const filtered = filterWorkspaceItems(inquiries, variant);
  return uniqueById([...generated, ...filtered], (item) => item.id).slice(0, 25);
}

type DemandWorkspaceMode = "product" | "service" | "hybrid";

type DemandPageConfig = {
  variant: OverviewVariant;
  mode: DemandWorkspaceMode;
  title: string;
  subtitle: string;
  badge: string;
  countLabel: string;
  filters: string[];
  primaryActionLabel: string;
  queueActionLabel: string;
  taskTargetPage: string;
};

function getDemandPageConfig(profile: WorkspaceOnboardingProfile): DemandPageConfig {
  const variant = getWorkspaceVariant(profile);
  const family = getWorkspaceIndustryFamily(profile);

  const serviceOnly =
    variant === "fashion-service" ||
    variant === "beauty-services" ||
    variant === "aesthetic-clinic";

  const hybrid = variant === "hybrid";

  const sharedHybridFilters = [
    "All",
    "Product Demand",
    "Service Demand",
    "Calendar Demand",
    "Restock/Reorder",
    "Appointment/Deposit",
    "High Value",
    "Unassigned",
    "Reviewed",
  ];

  if (hybrid) {
    return {
      variant,
      mode: "hybrid",
      title: "Product & Service Demand",
      subtitle:
        family === "retail"
          ? "Track item, order, payment, service, and channel demand across configured sources."
          : "Track product demand, service demand, appointment/deposit risk, and repeat revenue without mixing workflows.",
      badge: "Demand Intelligence",
      countLabel: "demand groups",
      filters: sharedHybridFilters,
      primaryActionLabel: "Create follow-up drafts",
      queueActionLabel: "Add to queue",
      taskTargetPage: "Today's Recovery Queue",
    };
  }

  if (serviceOnly) {
    const clinic = variant === "aesthetic-clinic";
    const fashionService = variant === "fashion-service";

    return {
      variant,
      mode: "service",
      title: clinic ? "Appointment & Package Demand" : fashionService ? "Custom Order Demand" : "Service Demand",
      subtitle: clinic
        ? "Track consultation requests, deposits, package interest, rebooking, no-show risk, and next-session follow-up."
        : fashionService
          ? "Track custom order inquiries, fittings, bridal consultations, deposits, appointment follow-up, and repeat client demand."
          : "Track appointment requests, deposits, rebooking demand, package renewal, and client follow-up.",
      badge: "Service Demand",
      countLabel: "service demand groups",
      filters: [
        "All",
        "Service Demand",
        "Calendar Demand",
        "Appointment/Deposit",
        "High Value",
        "Unassigned",
        "Reviewed",
      ],
      primaryActionLabel: "Create follow-up drafts",
      queueActionLabel: "Add to calendar follow-up",
      taskTargetPage: "Today's Recovery Queue",
    };
  }

  if (variant === "retail") {
    return {
      variant,
      mode: "product",
      title: "Channel Demand",
      subtitle: "Track item, category, order, payment, and customer follow-up demand across active channels.",
      badge: "Demand Intelligence",
      countLabel: "channel demand groups",
      filters: [
        "All",
        "Product Demand",
        "Restock/Reorder",
        "High Value",
        "Unassigned",
        "Reviewed",
      ],
      primaryActionLabel: "Create follow-up drafts",
      queueActionLabel: "Add to queue",
      taskTargetPage: "Today's Recovery Queue",
    };
  }

  return {
    variant,
    mode: "product",
    title: "Product Demand",
    subtitle:
      variant === "beauty-products"
        ? "Track shade questions, routine questions, refill/reorder demand, restock demand, bundle interest, and product follow-up."
        : "Track size/fit questions, drop demand, restock interest, waitlists, product availability, and order follow-up.",
    badge: "Product Demand",
    countLabel: "demand groups",
    filters: [
      "All",
      "Product Demand",
      "Restock/Reorder",
      "High Value",
      "Unassigned",
      "Reviewed",
    ],
    primaryActionLabel: "Create follow-up drafts",
    queueActionLabel: "Add to restock/reorder queue",
    taskTargetPage: "Today's Recovery Queue",
  };
}

function demandRecord(
  variant: OverviewVariant,
  item: Omit<ProductDemandSignal, "workspaceVariant" | "allowedVariants" | "auditTrail"> & {
    auditTrail?: string[];
  },
): ProductDemandSignal {
  return {
    ...item,
    workspaceVariant: variant,
    allowedVariants: [variant],
    auditTrail: item.auditTrail ?? [`${item.demandName} captured as demand recovery signal.`],
  };
}

