function getWorkspacePageData(profile: WorkspaceOnboardingProfile, _pageName: string) {
  return getWorkspaceDemoData(profile);
}

function useWorkspaceDemoData() {
  const [profile, setProfile] = useState<WorkspaceOnboardingProfile>(() => getWorkspaceProfile());

  useEffect(() => {
    setProfile(getWorkspaceProfile());
  }, []);

  return useMemo(() => getWorkspaceDemoData(profile), [profile]);
}

