function RecoveryOverview({ activities, onActivity, onNavigate, onOpenRunQueue }: RecoveryOverviewProps) {
  const [workspaceProfile, setWorkspaceProfile] = useState<WorkspaceOnboardingProfile>(() => getWorkspaceProfile());
  const [activeTab, setActiveTab] = useState<OverviewTab>("risks");
  const [selectedRisk, setSelectedRisk] = useState<OverviewRiskItem | null>(null);
  const [manualRisks, setManualRisks] = useState<OverviewRiskItem[]>([]);
  const [activePopup, setActivePopup] = useState<OverviewPopup>(null);
  const [toastMessage, setToastMessage] = useState("");
  const [captureForm, setCaptureForm] = useState({
    recoveryType: "Product",
    personName: "",
    source: "Instagram / Meta",
    context: "",
    status: "",
    value: "",
    owner: "Jordan Lee",
    note: "",
  });
  const [selectedQuickFixChoice, setSelectedQuickFixChoice] = useState<OverviewQuickFixChoiceId>("highest-value");
  const [approvedQuickFixIssueIds, setApprovedQuickFixIssueIds] = useState<string[]>([]);
  const [quickFixPreparedCount, setQuickFixPreparedCount] = useState<number | null>(null);

  useEffect(() => {
    setWorkspaceProfile(getWorkspaceProfile());
  }, []);

  const overviewCopy = useMemo(() => getOverviewCopy(workspaceProfile), [workspaceProfile]);
  const overviewKpis = useMemo(() => getOverviewKpis(workspaceProfile), [workspaceProfile]);
  const baseRiskItems = useMemo(() => getOverviewRiskItems(workspaceProfile), [workspaceProfile]);
  const riskItems = useMemo(() => [...manualRisks, ...baseRiskItems].slice(0, 5), [manualRisks, baseRiskItems]);
  const teamItems = useMemo(() => getOverviewTeamItems(workspaceProfile), [workspaceProfile]);
  const sourceSignals = useMemo(() => getOverviewSourceAlerts(workspaceProfile).slice(0, 5), [workspaceProfile]);
  const overviewActivity = useMemo(() => getOverviewActivity(workspaceProfile, activities), [workspaceProfile, activities]);
  const variant = getWorkspaceVariant(workspaceProfile);
  const quickFixConfig = useMemo(() => getQuickFixConfig(variant), [variant]);
  const quickFixIssues = quickFixConfig.issues;
  const quickFixTotalValue = useMemo(
    () => quickFixIssues.reduce((total, issue) => total + moneyToNumber(issue.valueAtRisk), 0),
    [quickFixIssues],
  );
  const captureCopy = useMemo(() => getOverviewCaptureCopy(workspaceProfile), [workspaceProfile]);

  useEffect(() => {
    setSelectedQuickFixChoice("highest-value");
    setApprovedQuickFixIssueIds([]);
    setQuickFixPreparedCount(null);
  }, [variant]);

  useEffect(() => {
    if (typeof window === "undefined") return;

    function closeOverviewPopups() {
      setActivePopup(null);
      setSelectedRisk(null);
    }

    function openRunQueue() { onOpenRunQueue("Recovery Overview"); }
    function openCapture() { setActivePopup("capture"); }
    function openQuickFix() { setActivePopup("quickfix"); }
    function prepareQuickFixFromGuide() {
      if (activePopup !== "quickfix") setActivePopup("quickfix");
      setApprovedQuickFixIssueIds(quickFixIssues.map((issue) => issue.id));
      setQuickFixPreparedCount(quickFixIssues.length);
    }
    function openFirstRisk() {
      const first = riskItems[0];
      if (first) {
        setSelectedRisk(first);
        setActivePopup("risk");
      }
    }
    function showRisks() { setActiveTab("risks"); closeOverviewPopups(); }
    function showSources() { setActiveTab("sources"); closeOverviewPopups(); }
    function showTeam() { setActiveTab("team"); closeOverviewPopups(); }
    function showActivity() { setActiveTab("activity"); closeOverviewPopups(); }

    window.addEventListener("altynx:overview-guide-close-modal", closeOverviewPopups);
    window.addEventListener("altynx:overview-open-run-queue", openRunQueue);
    window.addEventListener("altynx:overview-open-capture", openCapture);
    window.addEventListener("altynx:overview-open-quickfix", openQuickFix);
    window.addEventListener("altynx:overview-guide-prepare-quickfix", prepareQuickFixFromGuide);
    window.addEventListener("altynx:overview-open-first-risk", openFirstRisk);
    window.addEventListener("altynx:overview-show-risks", showRisks);
    window.addEventListener("altynx:overview-show-sources", showSources);
    window.addEventListener("altynx:overview-show-team", showTeam);
    window.addEventListener("altynx:overview-show-activity", showActivity);

    return () => {
      window.removeEventListener("altynx:overview-guide-close-modal", closeOverviewPopups);
      window.removeEventListener("altynx:overview-open-run-queue", openRunQueue);
      window.removeEventListener("altynx:overview-open-capture", openCapture);
      window.removeEventListener("altynx:overview-open-quickfix", openQuickFix);
      window.removeEventListener("altynx:overview-guide-prepare-quickfix", prepareQuickFixFromGuide);
      window.removeEventListener("altynx:overview-open-first-risk", openFirstRisk);
      window.removeEventListener("altynx:overview-show-risks", showRisks);
      window.removeEventListener("altynx:overview-show-sources", showSources);
      window.removeEventListener("altynx:overview-show-team", showTeam);
      window.removeEventListener("altynx:overview-show-activity", showActivity);
    };
  }, [riskItems, onOpenRunQueue, activePopup, quickFixIssues]);

  function addOverviewActivity(activity: NewRecoveryActivity, message: string) {
    onActivity(activity);
    setToastMessage(message);
  }

  function openRisk(risk: OverviewRiskItem) {
    setSelectedRisk(risk);
    setActivePopup("risk");
  }

  function closePopup() {
    setActivePopup(null);
    setSelectedRisk(null);
    setQuickFixPreparedCount(null);
  }

  function handleKpiClick(label: string) {
    if (label.includes("Recovered")) return onNavigate("Recovered Revenue");
    if (label.includes("Payment") || label.includes("Deposit")) return onNavigate("Payment Recovery");
    if (label.includes("Booking") || label.includes("Rebooking") || label.includes("Client") || label.includes("Consultation") || label.includes("Package")) return onNavigate("Follow-up Recovery");
    if (label.includes("Demand") || label.includes("Shade") || label.includes("Size") || label.includes("Restock") || label.includes("Drop")) return onNavigate("Product Demand");
    if (label.includes("Open")) return onNavigate("Assigned Recovery Actions");
    return onNavigate("Revenue Pipeline");
  }

  function toggleQuickFixApproval(issueId: string) {
    setApprovedQuickFixIssueIds((current) =>
      current.includes(issueId) ? current.filter((id) => id !== issueId) : [...current, issueId],
    );
  }

  function openQuickFixCase(issue: OverviewQuickFixIssue) {
    const recoveryType: OverviewRiskItem["recoveryType"] = issue.recoveryType === "Shared" ? "Hybrid" : issue.recoveryType;
    const detailFields = recoveryType === "Service"
      ? [
          { label: "Service interest", value: issue.problemTitle },
          { label: "Appointment / deposit status", value: "Needs review" },
          { label: "Booking / rebooking context", value: issue.whyItMatters },
        ]
      : recoveryType === "Product"
        ? [
            { label: "Product interest", value: issue.problemTitle },
            { label: "Order / payment status", value: "Needs review" },
            { label: "Reorder / restock timing", value: issue.whyItMatters },
          ]
        : [
            { label: "Recovery type", value: "Product + Service" },
            { label: "Product / service context", value: issue.problemTitle },
            { label: "Repeat timing", value: issue.whyItMatters },
          ];

    setSelectedRisk({
      id: issue.id,
      recoveryType,
      buyerName: issue.personName,
      context: issue.problemTitle,
      priority: "High",
      valueAtRisk: issue.valueAtRisk,
      owner: "Jordan Lee",
      nextAction: issue.recommendedNextAction,
      status: "Needs review",
      source: issue.source,
      tone: "amber",
      messageTemplate: `Hi ${issue.personName.split(" ")[0]}, I wanted to follow up on ${issue.problemTitle.toLowerCase()} while this is still active.`,
      detailFields,
    });
    setActivePopup("risk");
  }

  function prepareQuickFixActions() {
    const preparedIds = approvedQuickFixIssueIds.length > 0
      ? approvedQuickFixIssueIds
      : selectedQuickFixChoice === "highest-value"
        ? quickFixIssues.map((issue) => issue.id)
        : quickFixIssues.slice(0, 1).map((issue) => issue.id);
    const preparedCount = preparedIds.length;
    setQuickFixPreparedCount(preparedCount);
    addOverviewActivity(
      {
        category: "Team Actions",
        title: `Quick Fix prepared ${preparedCount} action${preparedCount === 1 ? "" : "s"} for review`,
        description: "Altynx prioritized the strongest recoverable signals and prepared them for review before queue execution.",
        impactBadge: formatCurrencyFromNumber(
          quickFixIssues
            .filter((issue) => preparedIds.includes(issue.id))
            .reduce((total, issue) => total + moneyToNumber(issue.valueAtRisk), 0),
        ),
        relatedRecord: "Recovery Overview",
        owner: "Recovery Lead",
        status: "Prepared",
        nextAction: "Review the prepared actions, then run the queue when approved.",
        tone: "emerald",
      },
      `Quick Fix prepared ${preparedCount} action${preparedCount === 1 ? "" : "s"} for review.`,
    );
  }

  function handleCaptureOpportunity() {
    const personName = captureForm.personName.trim() || (variant === "fashion-service" || variant === "beauty-services" || variant === "aesthetic-clinic" ? "New Client" : "New Buyer");
    const context = captureForm.context.trim() || (variant === "beauty-services" || variant === "aesthetic-clinic" ? "Missed booking inquiry" : "Missed revenue inquiry");
    const status = captureForm.status.trim() || "Needs review";
    const value = captureForm.value.trim() || "$0";
    const owner = captureForm.owner.trim() || "Jordan Lee";
    const recoveryType: OverviewRiskItem["recoveryType"] = variant === "hybrid" ? (captureForm.recoveryType === "Service" ? "Service" : "Product") : variant === "fashion-service" || variant === "beauty-services" || variant === "aesthetic-clinic" ? "Service" : "Product";
    const newRisk = makeOverviewRisk(
      `MANUAL-${Date.now()}`,
      recoveryType,
      personName,
      context,
      "High",
      value,
      owner,
      captureForm.note.trim() || "Review the signal, confirm the owner, and create the next recovery action.",
      status,
      captureForm.source.trim() || "Manual entry",
      "amber",
      `Hi ${personName.split(" ")[0]}, I wanted to follow up so we can help with the next step while this is still active.`,
      recoveryType === "Service"
        ? [
            { label: "Service interest", value: context },
            { label: "Appointment / deposit status", value: status },
            { label: "Booking / rebooking context", value: captureForm.note.trim() || "Manual opportunity captured from Overview." },
          ]
        : [
            { label: "Product interest", value: context },
            { label: "Order / payment status", value: status },
            { label: "Reorder / restock timing", value: captureForm.note.trim() || "Manual opportunity captured from Overview." },
          ],
    );

    setManualRisks((current) => [newRisk, ...current].slice(0, 5));
    setActiveTab("risks");
    addOverviewActivity(
      {
        category: "Inquiries",
        title: "Manual recovery opportunity captured",
        description: `${personName} was added to Revenue Risks from Recovery Overview.`,
        impactBadge: value,
        relatedRecord: "Recovery Overview",
        owner,
        status: "Captured",
        nextAction: "Sync or run the recovery queue when this action is reviewed.",
        tone: "amber",
      },
      "Opportunity captured. It will be included when you sync or run the recovery queue.",
    );
    setCaptureForm({ recoveryType: "Product", personName: "", source: "Instagram / Meta", context: "", status: "", value: "", owner: "Jordan Lee", note: "" });
    setActivePopup(null);
  }

  function handleExportOverview() {
    addOverviewActivity(
      {
        category: "Reports",
        title: "Niche overview report prepared",
        description: "A niche-personalized Recovery Overview summary was prepared for the owner.",
        impactBadge: overviewKpis[0]?.value ?? "Prepared",
        relatedRecord: overviewCopy.badge,
        owner: "Operations",
        status: "Prepared",
        nextAction: "Share the recovery summary with the business owner.",
        tone: "emerald",
      },
      "Niche recovery overview report prepared.",
    );
  }

  const tabItems: { id: OverviewTab; label: string; count: string }[] = [
    { id: "risks", label: "Revenue Risks", count: `${riskItems.length}` },
    { id: "sources", label: "Source Signals", count: `${sourceSignals.length}` },
    { id: "team", label: "Team Load", count: `${teamItems.length}` },
    { id: "activity", label: "Recent Activity", count: `${overviewActivity.length}` },
  ];

  const activeTabCta = activeTab === "risks" ? "View all recovery risks" : activeTab === "sources" ? "Review source signals" : activeTab === "team" ? "Open Team Workload" : "Open activity feed";
  const activeTabTarget = activeTab === "sources" ? "Source Leak Tracking" : activeTab === "team" ? "Team Load" : activeTab === "activity" ? "Recovery Activity" : "Revenue Pipeline";


  const overviewMetricValue = (keywords: string[], fallback: string) => {
    const found = overviewKpis.find((item) => keywords.some((keyword) => item.label.toLowerCase().includes(keyword.toLowerCase())));
    return found?.value ?? fallback;
  };

  const serviceFocused = variant === "fashion-service" || variant === "beauty-services" || variant === "aesthetic-clinic";
  const beautyFocused = variant === "beauty-products" || variant === "beauty-services" || variant === "aesthetic-clinic";
  const hybridFocused = variant === "hybrid";
  const productContextName = beautyFocused
    ? "Vitamin C serum routine bundle"
    : serviceFocused && !hybridFocused
      ? "Bridal fitting + deposit package"
      : "Atelier Luma bridal capsule dress";
  const serviceContextName = beautyFocused
    ? "Skin consultation + routine package"
    : "Bridal fitting + deposit package";
  const dashboardLabel = hybridFocused
    ? "Hybrid recovery workspace"
    : serviceFocused
      ? "Service recovery workspace"
      : beautyFocused
        ? "Beauty / cosmetics recovery workspace"
        : "Fashion / apparel recovery workspace";

  const overviewDashboardKpis = [
    {
      label: "Recovery in progress",
      value: `${riskItems.length + sourceSignals.length + teamItems.length}`,
      caption: "Open actions ready for review",
      trend: "Daily command center",
      tone: "amber" as Tone,
      icon: "activity",
      target: "Today's Recovery Queue",
    },
    {
      label: "Money still open",
      value: overviewMetricValue(["money", "open", "deposit", "payment"], "$18.4K"),
      caption: "Potential revenue to protect",
      trend: "Across active recovery signals",
      tone: "rose" as Tone,
      icon: "money",
      target: "Revenue Pipeline",
    },
    {
      label: "Recovered revenue",
      value: overviewMetricValue(["recovered"], "$42.7K"),
      caption: "Proof-ready value this month",
      trend: "Recovered from follow-ups",
      tone: "emerald" as Tone,
      icon: "check",
      target: "Recovered Revenue",
    },
    {
      label: "Recovery rate",
      value: "74%",
      caption: "Reviewed actions converting",
      trend: "Run the Queue ready",
      tone: "cyan" as Tone,
      icon: "spark",
      target: "Revenue Pipeline",
    },
  ];

  const overviewModuleTiles = [
    {
      title: "Recovery Queue",
      value: `${riskItems.length} high-priority`,
      caption: "At-risk, overdue, and follow-up actions are grouped for daily review.",
      meta: ["At risk", "Follow-up", "Run queue"],
      icon: "queue",
      tone: "rose" as Tone,
      cta: "View queue",
      target: "Today's Recovery Queue",
      visual: "queue" as const,
    },
    {
      title: hybridFocused ? "Buyer & Client Profiles" : serviceFocused ? "Client Profiles" : "Buyer Profiles",
      value: hybridFocused ? "Unified context" : serviceFocused ? "Client recovery" : "Buyer recovery",
      caption: "See who matters, what they wanted, owner status, and next safe action.",
      meta: ["Profiles", "Owner", "Drafts"],
      icon: "team",
      tone: "cyan" as Tone,
      cta: "View profiles",
      target: "Buyer Profiles",
      visual: "profiles" as const,
    },
    {
      title: "Appointments / Deposits",
      value: serviceFocused || hybridFocused ? "$4.6K open" : "$2.1K open",
      caption: serviceFocused || hybridFocused ? "Deposits, booking intent, and rebooking risks stay visible." : "Deposit and payment signals tied to product/order recovery.",
      meta: ["Deposits", "Partial", "Overdue"],
      icon: "payment",
      tone: "amber" as Tone,
      cta: "View appointments",
      target: "Payment Recovery",
      visual: "service" as const,
    },
    {
      title: serviceFocused ? "Rebooking & Repeat Visits" : "Repeat Purchase",
      value: serviceFocused ? "8 due soon" : "12 repeat signals",
      caption: serviceFocused ? "Client follow-up and repeat visit opportunities stay separate from product demand." : "Refill, restock, and second purchase prompts stay ready for manual review.",
      meta: ["Repeat", "Refill", "Review"],
      icon: "repeat",
      tone: "emerald" as Tone,
      cta: serviceFocused ? "View rebooking" : "View repeat signals",
      target: serviceFocused ? "Follow-up Recovery" : "Refill Opportunities",
      visual: "trend" as const,
    },
    {
      title: "Product Demand",
      value: beautyFocused ? "Routine bundle" : "Bridal capsule",
      caption: beautyFocused ? "Shade, refill, and skincare routine demand are ready for recovery review." : "Size/fit, new drop, restock, and exchange demand are grouped for action.",
      meta: ["Demand", "Restock", "High intent"],
      icon: "order",
      tone: "cyan" as Tone,
      cta: "View product insights",
      target: "Product Demand",
      visual: "product" as const,
    },
    {
      title: "Revenue / Payment Recovery",
      value: overviewMetricValue(["payment", "deposit"], "$6.8K"),
      caption: "Pending payment, deposit, and invoice reminders stay proof-ready.",
      meta: ["Payment", "Proof", "Pipeline"],
      icon: "money",
      tone: "rose" as Tone,
      cta: "View recovery pipeline",
      target: "Revenue Pipeline",
      visual: "money" as const,
    },
  ];

  return (
    <div className="recovery-page overview-command-page overview-command-center-final command-center-scope command-overview-page">
      {toastMessage ? (
        <div className="altynx-local-toast overview-toast" role="status">
          <p>{toastMessage}</p>
          <button aria-label="Dismiss notification" className="altynx-local-toast-close" onClick={() => setToastMessage("")} type="button">
            ×
          </button>
        </div>
      ) : null}

      <section className="recovery-overview-dashboard">
        <div className="overview-hero-grid">
          <div className="overview-hero-copy-card">
            <span className="overview-dashboard-eyebrow"><CommandIcon name="activity" /> Recovery Overview</span>
            <h2>{overviewCopy.audienceName} recovery command center</h2>
            <p>{overviewCopy.subtitle}</p>
            <div className="overview-hero-chip-row">
              <span>{dashboardLabel}</span>
              <span>{overviewCopy.badge}</span>
              <span>Manual review before send</span>
            </div>
          </div>

          <div className="overview-hero-proof-card">
            <div className="overview-ring-chart" aria-label="Recovery rate 74 percent">
              <span>74%</span>
            </div>
            <div>
              <span>Proof-ready recovery</span>
              <strong>{overviewMetricValue(["recovered"], "$42.7K")}</strong>
              <p>Recovered revenue, open proof, and related actions stay visible from this dashboard.</p>
            </div>
            <button className="secondary-btn command-icon-button" onClick={handleExportOverview} type="button">
              <CommandIcon name="report" />
              Prepare proof report
            </button>
          </div>
        </div>

        <section className="overview-kpi-card-grid" aria-label="Recovery overview metrics">
          {overviewDashboardKpis.map((item) => (
            <article className={`overview-kpi-card overview-kpi-card-${item.tone}`} key={item.label} onClick={() => onNavigate(item.target)} role="button" tabIndex={0} onKeyDown={(event) => {
              if (event.key !== "Enter" && event.key !== " ") return;
              event.preventDefault();
              onNavigate(item.target);
            }}>
              <div className="overview-kpi-card-top">
                <span className={`overview-module-icon ${item.tone}`}><CommandIcon name={item.icon} /></span>
                <span>{item.label}</span>
              </div>
              <strong>{item.value}</strong>
              <p>{item.trend}</p>
              <em className={`overview-kpi-chip ${item.tone}`}>{item.caption}</em>
            </article>
          ))}
        </section>

        <section className="overview-module-grid" aria-label="Recovery modules">
          {overviewModuleTiles.map((tile) => (
            <article className={`overview-module-card overview-module-card-${tile.tone}`} key={tile.title}>
              <div className="overview-module-card-head">
                <span className={`overview-module-icon ${tile.tone}`}><CommandIcon name={tile.icon} /></span>
                <button type="button" onClick={() => onNavigate(tile.target)}>{tile.cta}</button>
              </div>

              {tile.visual === "product" ? (
                <div className="overview-module-visual overview-product-visual" role="button" tabIndex={0} onClick={() => onNavigate("Product Demand")} onKeyDown={(event) => {
                  if (event.key !== "Enter" && event.key !== " ") return;
                  event.preventDefault();
                  onNavigate("Product Demand");
                }}>
                  <ProductImageFrame productName={productContextName} industryType={beautyFocused ? "Beauty / Skincare" : "Fashion / Apparel"} recordKind="product" />
                  <span>
                    <small>Product signal</small>
                    <strong>{productContextName}</strong>
                  </span>
                </div>
              ) : tile.visual === "service" ? (
                <div className="overview-module-visual overview-service-visual" role="button" tabIndex={0} onClick={() => onNavigate("Payment Recovery")} onKeyDown={(event) => {
                  if (event.key !== "Enter" && event.key !== " ") return;
                  event.preventDefault();
                  onNavigate("Payment Recovery");
                }}>
                  <ProductImageFrame productName={serviceContextName} industryType={beautyFocused ? "Beauty / Skincare" : "Fashion / Apparel"} recordKind="service" />
                  <span>
                    <small>Service / deposit signal</small>
                    <strong>{serviceContextName}</strong>
                  </span>
                </div>
              ) : tile.visual === "profiles" ? (
                <div className="overview-profile-stack" aria-label="Profile summary">
                  {["Jordan Lee", "Alex Morgan", "Mina Cole"].map((name) => <CommandAvatar key={name} name={name} />)}
                  <span>Profiles need clear ownership</span>
                </div>
              ) : tile.visual === "trend" ? (
                <div className="overview-mini-trend" aria-hidden="true">
                  <svg viewBox="0 0 180 64">
                    <path d="M8 48 C35 42 44 28 70 34 C96 40 106 20 132 24 C152 27 162 16 174 12" />
                    <circle cx="8" cy="48" r="4" />
                    <circle cx="70" cy="34" r="4" />
                    <circle cx="132" cy="24" r="4" />
                    <circle cx="174" cy="12" r="4" />
                  </svg>
                </div>
              ) : tile.visual === "money" ? (
                <div className="overview-module-amount-visual">
                  <strong>{overviewMetricValue(["payment", "deposit"], "$6.8K")}</strong>
                  <span>pending review</span>
                </div>
              ) : (
                <div className="overview-module-mini-bars">
                  <span style={{ "--progress": "78%" } as CSSProperties}><i /></span>
                  <span style={{ "--progress": "54%" } as CSSProperties}><i /></span>
                  <span style={{ "--progress": "64%" } as CSSProperties}><i /></span>
                </div>
              )}

              <div className="overview-module-copy">
                <span>{tile.value}</span>
                <h3>{tile.title}</h3>
                <p>{tile.caption}</p>
              </div>

              <div className="overview-module-meta-row">
                {tile.meta.map((meta) => <em key={`${tile.title}-${meta}`}>{meta}</em>)}
              </div>
            </article>
          ))}
        </section>

        <section className="overview-quick-fix-card overview-quick-fix-strip overview-quick-fix-single command-split-quick-fix-strip">
          <div className="command-split-quick-fix-content">
            <div className="overview-quick-fix-copy command-split-quick-fix-copy">
              <span>Quick fix</span>
              <h2>{quickFixConfig.heading}</h2>
              <p>{quickFixConfig.supportText}</p>
            </div>

            <button
              className="overview-quick-fix-main-button command-split-quick-fix-button"
              onClick={() => setActivePopup("quickfix")}
              type="button"
            >
              <span className="command-split-quick-fix-button-inner">
                <CommandIcon name="spark" />
                Quick Fix
              </span>
            </button>
          </div>

          <aside className="command-quick-fix-graph-card command-quick-fix-graph-card-animated" aria-label="Quick Fix recovery snapshot">
            <div className="command-quick-fix-graph-head">
              <span>Recovery snapshot</span>
              <strong>Ready to review</strong>
            </div>

            <div className="command-quick-fix-line-graph command-quick-fix-line-graph-animated" aria-hidden="true">
              <svg viewBox="0 0 320 120" role="img">
                <defs>
                  <linearGradient id="overviewQuickFixGraphFill" x1="0" x2="0" y1="0" y2="1">
                    <stop offset="0%" stopColor="rgba(255, 69, 0, 0.20)" />
                    <stop offset="100%" stopColor="rgba(255, 69, 0, 0)" />
                  </linearGradient>
                  <linearGradient id="overviewQuickFixGraphStroke" x1="0" x2="1" y1="0" y2="0">
                    <stop offset="0%" stopColor="#ff4500" />
                    <stop offset="55%" stopColor="#ff6a1a" />
                    <stop offset="100%" stopColor="#ff9f0a" />
                  </linearGradient>
                </defs>

                <path className="cqf-graph-base-line" d="M18 88 C52 80 72 64 104 68 C142 72 158 42 196 48 C235 54 258 28 302 22" fill="none" stroke="rgba(255, 69, 0, 0.18)" strokeWidth="3" strokeLinecap="round" />
                <path className="cqf-graph-area" d="M18 88 C52 80 72 64 104 68 C142 72 158 42 196 48 C235 54 258 28 302 22 L302 108 L18 108 Z" fill="url(#overviewQuickFixGraphFill)" />
                <path className="cqf-graph-line" d="M18 88 C52 80 72 64 104 68 C142 72 158 42 196 48 C235 54 258 28 302 22" fill="none" stroke="url(#overviewQuickFixGraphStroke)" strokeWidth="4" strokeLinecap="round" />
                <g className="cqf-graph-points">
                  <circle cx="18" cy="88" r="4" />
                  <circle cx="104" cy="68" r="4" />
                  <circle cx="196" cy="48" r="4" />
                  <circle cx="302" cy="22" r="4" />
                </g>
              </svg>
            </div>

            <div className="command-quick-fix-mini-bars command-quick-fix-mini-bars-animated">
              <div className="command-quick-fix-mini-bar" style={{ "--barTarget": "78%" } as CSSProperties}>
                <span>High-intent recovery</span>
                <em><i /></em>
              </div>
              <div className="command-quick-fix-mini-bar" style={{ "--barTarget": "58%" } as CSSProperties}>
                <span>Payment follow-up</span>
                <em><i /></em>
              </div>
              <div className="command-quick-fix-mini-bar" style={{ "--barTarget": "66%" } as CSSProperties}>
                <span>Restock / repeat signal</span>
                <em><i /></em>
              </div>
            </div>
          </aside>
        </section>
      </section>

      <section className="overview-tabs-card glass-card">
        <div className="overview-tabs-header">
          <div>
            <span>Daily command center</span>
            <h2>What needs recovery attention today?</h2>
          </div>
          <button className="secondary-btn" onClick={() => onNavigate(activeTabTarget)} type="button">
            {activeTabCta}
          </button>
        </div>

        <div className="overview-tabs overview-tabs-with-dividers" role="tablist" aria-label="Recovery Overview sections">
          {tabItems.map((tab) => (
            <button
              key={tab.id}
              className={`overview-tab-button ${activeTab === tab.id ? "is-active" : ""}`}

              onClick={() => setActiveTab(tab.id)}
              role="tab"
              type="button"
              aria-selected={activeTab === tab.id}
            >
              <span className="overview-tab-label"><CommandIcon name={getOverviewTabIcon(tab.id)} /> {tab.label}</span>
              <span className="overview-tab-count">{tab.count} items</span>
            </button>
          ))}
        </div>

        {activeTab === "risks" ? (
          <div className="overview-tab-panel overview-risk-table">
            {riskItems.map((risk, index) => (
              <article className="overview-risk-row" key={risk.id}>
                <div className="overview-risk-name">
                  <h3><CommandAvatar name={risk.buyerName} /> {risk.buyerName}</h3>
                  {variant === "hybrid" ? <span>{risk.recoveryType} recovery</span> : null}
                </div>
                <div className="overview-risk-source">
                  <span>Source/channel</span>
                  <strong>{risk.source}</strong>
                </div>
                <div className="overview-risk-problem">
                  <span>Problem</span>
                  <strong>{risk.context}</strong>
                  <small>{risk.nextAction}</small>
                </div>
                <div className="overview-risk-value">
                  <span>Value at risk</span>
                  <strong>{risk.valueAtRisk}</strong>
                </div>
                <div className="overview-risk-owner">
                  <span>Owner</span>
                  <strong>{risk.owner}</strong>
                  <Badge tone={risk.tone}>{risk.priority}</Badge>
                </div>
                <button className="row-action overview-risk-open command-icon-button" onClick={() => openRisk(risk)} type="button">
                  <CommandIcon name="queue" />
                  Open recovery action
                </button>
              </article>
            ))}
          </div>
        ) : null}

        {activeTab === "sources" ? (
          <div className="overview-source-grid overview-tab-panel">
            {sourceSignals.map((signal) => (
              <article className="overview-source-signal" key={signal.id}>
                <div className="overview-source-topline">
                  <span className={`command-source-icon ${signal.tone}`}><CommandIcon name="source" /></span>
                  <h3>{signal.source}</h3>
                  <strong>{signal.value}</strong>
                </div>
                <p>{signal.title}</p>
                <small>{signal.description}</small>
                <div className="overview-source-foot">
                  <span>Owner: {signal.owner}</span>
                  <button className="row-action command-icon-button" onClick={() => onNavigate("Source Leak Tracking")} type="button"><CommandIcon name="source" /> Review source signals</button>
                </div>
                <em>{signal.nextAction}</em>
              </article>
            ))}
          </div>
        ) : null}

        {activeTab === "team" ? (
          <div className="overview-team-summary-grid overview-tab-panel">
            {teamItems.map((item) => (
              <article className="overview-summary-card" key={item.id}>
                <span className={`command-source-icon ${item.tone}`}><CommandIcon name="team" /></span>
                <div>
                  <h3>{item.label}</h3>
                  <strong>{item.value}</strong>
                  <p>{item.note}</p>
                </div>
              </article>
            ))}
          </div>
        ) : null}

        {activeTab === "activity" ? (
          <div className="overview-activity-feed overview-tab-panel">
            {overviewActivity.map((activity) => (
              <article className="overview-activity-item" key={activity.id}>
                <span className={`activity-node ${activity.tone} command-activity-node`}><CommandIcon name={getCommandIconForLabel(activity.title)} /></span>
                <div>
                  <div className="overview-activity-topline">
                    <h3>{activity.title}</h3>
                    <span>{activity.time}</span>
                  </div>
                  <p>{activity.description}</p>
                  <div className="recovery-meta">
                    <span>{activity.value}</span>
                    <span>{activity.owner}</span>
                    <span>{activity.status}</span>
                  </div>
                </div>
              </article>
            ))}
          </div>
        ) : null}
      </section>

      {activePopup === "risk" && selectedRisk ? (
        <ModalShell
          title={`${selectedRisk.buyerName} · ${selectedRisk.recoveryType} recovery`}
          onClose={closePopup}
          wide
          footer={
            <>
              <button className="primary-btn" onClick={() => onNavigate("Revenue Pipeline")} type="button">Open recovery action</button>
              <button className="secondary-btn" onClick={() => onOpenRunQueue("Recovery Overview")} type="button">Run the Queue</button>
              <button className="secondary-btn" onClick={closePopup} type="button">Close</button>
            </>
          }
        >
          <div className="overview-modal-intro command-modal-intro">
            <span className={`command-source-icon ${selectedRisk.tone}`}><CommandIcon name={getCommandIconForLabel(selectedRisk.context)} /></span>
            <div>
              <Badge tone={selectedRisk.tone}>{selectedRisk.priority}</Badge>
              <p>{selectedRisk.context}</p>
            </div>
          </div>
          <div className="command-modal-summary-grid">
            <article><span>Value at risk</span><strong>{selectedRisk.valueAtRisk}</strong></article>
            <article><span>Owner</span><strong>{selectedRisk.owner}</strong></article>
            <article><span>Source</span><strong>{selectedRisk.source}</strong></article>
          </div>
          <div className="detail-grid">
            {selectedRisk.detailFields.map((field) => (
              <DetailField key={field.label} label={field.label} value={field.value} />
            ))}
            <DetailField label="Value at risk" value={selectedRisk.valueAtRisk} />
            <DetailField label="Owner" value={selectedRisk.owner} />
            <DetailField label="Source/channel" value={selectedRisk.source} />
            <DetailField label="Recommended next action" value={selectedRisk.nextAction} />
          </div>
          <div className="message-preview-card overview-message-preview">
            <span>Message template</span>
            <p>{selectedRisk.messageTemplate}</p>
          </div>
        </ModalShell>
      ) : null}

      {activePopup === "quickfix" ? (
        <ModalShell
          title="Quick Fix"
          onClose={closePopup}
          wide
          footer={
            quickFixPreparedCount === null ? (
              <>
                <button className="primary-btn" onClick={prepareQuickFixActions} type="button">Prepare selected fixes</button>
                <button className="secondary-btn" onClick={closePopup} type="button">Close</button>
              </>
            ) : (
              <>
                <button className="primary-btn" onClick={() => { setActivePopup(null); onNavigate("Assigned Recovery Actions"); }} type="button">Review prepared actions</button>
                <button className="secondary-btn" onClick={() => { setQuickFixPreparedCount(null); onOpenRunQueue("Recovery Overview"); }} type="button">Run the Queue</button>
                <button className="secondary-btn" onClick={closePopup} type="button">Close</button>
              </>
            )
          }
        >
          <div className="overview-command-modal overview-quickfix-workspace">
            {quickFixPreparedCount === null ? (
              <>
                <div className="overview-quickfix-summary command-quickfix-modal-summary">
                  <span className="command-hero-icon" aria-hidden="true"><CommandIcon name="spark" /></span>
                  <div>
                    <strong>{quickFixIssues.length} recovery issues need attention now.</strong>
                    <p>{formatCurrencyFromNumber(quickFixTotalValue)} can still be recovered from these signals.</p>
                  </div>
                </div>
                <ol className="overview-quickfix-steps">
                  <li>Altynx finds the strongest recoverable signals.</li>
                  <li>You approve the suggested next steps.</li>
                  <li>Approved work becomes ready for the queue.</li>
                </ol>
                <div className="overview-quickfix-issue-list">
                  {quickFixIssues.map((issue) => {
                    const approved = approvedQuickFixIssueIds.includes(issue.id);
                    return (
                      <article className={`overview-quickfix-issue ${approved ? "is-approved" : ""}`} key={issue.id}>
                        <div className="overview-quickfix-issue-head">
                          <div className="command-issue-title">
                            <span className="command-source-icon amber"><CommandIcon name={getCommandIconForLabel(issue.problemTitle)} /></span>
                            <div>
                              {variant === "hybrid" ? <span>{issue.recoveryType} recovery</span> : null}
                              <h3>{issue.problemTitle}</h3>
                            </div>
                          </div>
                          <strong>{issue.valueAtRisk}</strong>
                        </div>
                        <div className="overview-quickfix-issue-meta">
                          <span>{issue.source}</span>
                          <span>{issue.personName}</span>
                        </div>
                        <p>{issue.recommendedNextAction}</p>
                        <small>{issue.whyItMatters}</small>
                        <div className="overview-quickfix-issue-actions">
                          <button className={approved ? "secondary-btn" : "primary-btn"} onClick={() => toggleQuickFixApproval(issue.id)} type="button">
                            {approved ? "Action approved" : "Approve action"}
                          </button>
                          <button className="secondary-btn" onClick={() => openQuickFixCase(issue)} type="button">Open case</button>
                        </div>
                      </article>
                    );
                  })}
                </div>
                <section className="overview-quickfix-choice-section">
                  <h3>What should Altynx prepare?</h3>
                  <div className="overview-quickfix-choice-grid">
                    {quickFixConfig.choices.map((choice) => (
                      <button
                        className={`overview-quickfix-choice ${selectedQuickFixChoice === choice.id ? "is-selected" : ""}`}
                        key={choice.id}
                        onClick={() => setSelectedQuickFixChoice(choice.id)}
                        type="button"
                      >
                        <strong>{choice.title}</strong>
                        <span>{choice.helper}</span>
                      </button>
                    ))}
                  </div>
                </section>
              </>
            ) : (
              <div className="overview-quickfix-success">
                <strong>Quick Fix prepared {quickFixPreparedCount} action{quickFixPreparedCount === 1 ? "" : "s"} for review.</strong>
                <p>Nothing has been sent yet. Review the prepared work or run the approved queue when ready.</p>
              </div>
            )}
          </div>
        </ModalShell>
      ) : null}

      {activePopup === "capture" ? (
        <ModalShell
          title={captureCopy.title}
          onClose={closePopup}
          wide
          footer={
            <>
              <button className="primary-btn" onClick={handleCaptureOpportunity} type="button">Capture Opportunity</button>
              <button className="secondary-btn" onClick={closePopup} type="button">Close</button>
            </>
          }
        >
          <div className="command-capture-intro">
            <span className="command-hero-icon" aria-hidden="true"><CommandIcon name="message" /></span>
            <div>
              <strong>Capture a recoverable signal</strong>
              <p>Log the source, owner, value, and next action without changing the rest of the workspace.</p>
            </div>
          </div>
          <div className="overview-capture-form command-capture-form">
            {captureCopy.typeOptions.length > 0 ? (
              <label>
                <span>Recovery type</span>
                <select value={captureForm.recoveryType} onChange={(event) => setCaptureForm((current) => ({ ...current, recoveryType: event.target.value }))}>
                  {captureCopy.typeOptions.map((option) => <option key={option}>{option}</option>)}
                </select>
              </label>
            ) : null}
            <label>
              <span>{captureCopy.personLabel}</span>
              <input value={captureForm.personName} onChange={(event) => setCaptureForm((current) => ({ ...current, personName: event.target.value }))} placeholder="Example: Jordan Lee" />
            </label>
            <label>
              <span>Source/channel</span>
              <input value={captureForm.source} onChange={(event) => setCaptureForm((current) => ({ ...current, source: event.target.value }))} placeholder="Instagram / Meta, WhatsApp, Website form" />
            </label>
            <label>
              <span>{captureCopy.contextLabel}</span>
              <input value={captureForm.context} onChange={(event) => setCaptureForm((current) => ({ ...current, context: event.target.value }))} placeholder="What did they ask for?" />
            </label>
            <label>
              <span>{captureCopy.statusLabel}</span>
              <input value={captureForm.status} onChange={(event) => setCaptureForm((current) => ({ ...current, status: event.target.value }))} placeholder="Pending payment, deposit waiting, needs reply" />
            </label>
            <label>
              <span>{captureCopy.valueLabel}</span>
              <input value={captureForm.value} onChange={(event) => setCaptureForm((current) => ({ ...current, value: event.target.value }))} placeholder="$920" />
            </label>
            <label>
              <span>{captureCopy.ownerLabel}</span>
              <input value={captureForm.owner} onChange={(event) => setCaptureForm((current) => ({ ...current, owner: event.target.value }))} placeholder="Jordan Lee" />
            </label>
            <label className="overview-capture-full">
              <span>{captureCopy.noteLabel}</span>
              <textarea value={captureForm.note} onChange={(event) => setCaptureForm((current) => ({ ...current, note: event.target.value }))} placeholder="Add the recovery note the owner should see." rows={4} />
            </label>
          </div>
        </ModalShell>
      ) : null}
    </div>
  );
}

type RecommendedRecoveryTemplate = {
  name: string;
  type: string;
  status: "Approved template available" | "General template available";
  matchReason: string;
  body: string;
};

function getRecommendedTemplateForTask(task: RecoveryTask): RecommendedRecoveryTemplate {
  const category = task.category.toLowerCase();
  const leakType = task.leakType.toLowerCase();
  const context = `${task.productInterest} ${task.brandContext} ${task.serviceContext ?? ""} ${task.productOrderContext ?? ""}`.toLowerCase();
  const firstName = task.customer.split(" ")[0];

  if (task.recordKind === "service" || task.appointmentDate || context.includes("appointment") || context.includes("booking")) {
    if (context.includes("deposit") || task.depositStatus === "Pending" || task.depositStatus === "Overdue") {
      return {
        name: "Deposit Recovery Reminder",
        type: "Deposit reminder",
        status: "Approved template available",
        matchReason: "Matched because this service recovery case has a pending deposit or appointment hold risk.",
        body: `Hi ${firstName}, your booking is almost confirmed. I’m sending the deposit reminder so we can keep your appointment window secure.`,
      };
    }

    if (context.includes("no-show") || task.appointmentStatus === "Missed" || task.appointmentStatus === "Needs rebooking") {
      return {
        name: "No-show / Rebooking Follow-up",
        type: "Rebooking",
        status: "Approved template available",
        matchReason: "Matched because this client needs a rebooking or missed-appointment recovery follow-up.",
        body: `Hi ${firstName}, we missed you for the appointment. I can help rebook the next available slot if you still want to come in.`,
      };
    }

    return {
      name: "Appointment Follow-up Template",
      type: "Appointment / service follow-up",
      status: "Approved template available",
      matchReason: "Matched because this is a service or appointment recovery action.",
      body:
        task.messageTemplate ||
        `Hi ${firstName}, I wanted to follow up on your ${task.serviceType ?? task.productInterest.toLowerCase()}. I can help with the next available time and keep the booking moving.`,
    };
  }

  if (leakType.includes("payment") || category.includes("payment")) {
    return {
      name: "Payment Recovery Reminder",
      type: "Payment reminder",
      status: "Approved template available",
      matchReason: "Matched because this case has pending payment value and needs a payment recovery reminder.",
      body:
        `Hi ${firstName}, your ${task.productInterest.toLowerCase()} is still reserved. ` +
        `Here is the payment reminder again. Let me know if anything is blocking the payment and I can help.`,
    };
  }

  if (category.includes("refill") || category.includes("restock") || context.includes("reorder") || context.includes("restock") || context.includes("waitlist")) {
    return {
      name: "Reorder / Restock Follow-up",
      type: "Reorder / restock",
      status: "Approved template available",
      matchReason: "Matched because this buyer has repeat-purchase, reorder, restock, or waitlist intent.",
      body:
        `Hi ${firstName}, I wanted to follow up on your ${task.productInterest.toLowerCase()}. ` +
        `We can help while the right option is still available or track it for the next restock.`,
    };
  }

  if (category.includes("post") || leakType.includes("post") || context.includes("review") || context.includes("referral")) {
    return {
      name: "Review / Referral Prompt",
      type: "Review / referral",
      status: "Approved template available",
      matchReason: "Matched because this case is tied to reviews, referrals, or post-experience recovery.",
      body: `Hi ${firstName}, checking in after your experience. If everything went well, we would love your feedback or a quick referral.`,
    };
  }

  return {
    name: "High-Intent Recovery Follow-up",
    type: "Follow-up",
    status: "Approved template available",
    matchReason: "Matched because this is a high-intent recovery case that needs a clear next action.",
    body:
      task.messageTemplate ||
      `Hi ${firstName}, I wanted to follow up on your ${task.productInterest.toLowerCase()}. Let me know if you would like help with the next step today.`,
  };
}

function buildRiskReason(task: RecoveryTask) {
  if (task.recordKind === "service" || task.appointmentDate) {
    const appointmentPart = task.appointmentDate
      ? ` Appointment: ${task.appointmentDate} at ${task.appointmentTime ?? "time not set"}.`
      : "";
    const depositPart = task.depositStatus ? ` Deposit status: ${task.depositStatus}.` : "";
    return `${task.estimatedRevenueAtRisk} is at risk because this client recovery action is ${task.dueStatus.toLowerCase()} and owned by ${task.assignedOwner}.${appointmentPart}${depositPart} Next action: ${task.recommendedNextAction}`;
  }

  if (task.priority === "Critical") {
    return `${task.estimatedRevenueAtRisk} is at risk because this ${task.leakType.toLowerCase()} is ${task.dueStatus.toLowerCase()}, owned by ${task.assignedOwner}, and the last event says: ${task.lastEvent}.`;
  }

  if (task.dueStatus === "Overdue") {
    return `This opportunity is overdue and may go cold without a recovery action. Last contact: ${task.lastContact}.`;
  }

  if (task.category === "Payment Recovery") {
    return `The buyer has shown payment intent, but payment completion still needs follow-up.`;
  }

  if (task.category === "Refill/Restock") {
    return `This buyer is inside a repeat, reorder, or restock window, so timing matters before the opportunity is lost.`;
  }

  return `This buyer has an open recovery opportunity that needs ownership, a clear next action, and follow-up tracking.`;
}

function buildAiResponseDraft(task: RecoveryTask) {
  return (
    `Hi ${task.customer.split(" ")[0]}, I wanted to follow up on your ${task.productInterest.toLowerCase()}. ` +
    `${task.recommendedNextAction} ` +
    `Would you like me to help with this today?`
  );
}

function TodaysRecoveryQueue({ onNavigate }: { onNavigate: (page: string) => void }) {
  const workspaceProfile = getWorkspaceProfile();
  const workspaceConfig = getWorkspaceConfig(workspaceProfile);
  const variant = getWorkspaceVariant(workspaceProfile);
  const workspaceData = useWorkspaceDemoData();
  const recoveryTasks = workspaceData.recoveryTasks;

  const [activeTab, setActiveTab] = useState<QueueTab>("All");
  const [selectedTaskId, setSelectedTaskId] = useState<string>(recoveryTasks[0]?.id ?? "");
  const [queueMode, setQueueMode] = useState<"list" | "detail">("list");
  const [detailNotice, setDetailNotice] = useState("Ready for recovery action.");
  const [showAllQueueItems, setShowAllQueueItems] = useState(false);

  const [taskMessageDrafts, setTaskMessageDrafts] = useState<Record<string, string>>({});
  const [templateUsedTaskIds, setTemplateUsedTaskIds] = useState<Record<string, boolean>>({});
  const [copiedTaskIds, setCopiedTaskIds] = useState<Record<string, boolean>>({});
  const [followUpTaskIds, setFollowUpTaskIds] = useState<Record<string, boolean>>({});
  const [reviewedTaskIds, setReviewedTaskIds] = useState<Record<string, boolean>>({});
  const [queueReadyTaskIds, setQueueReadyTaskIds] = useState<Record<string, boolean>>({});
  const [calendarReadyTaskIds, setCalendarReadyTaskIds] = useState<Record<string, boolean>>({});
  const [localThreadMessages, setLocalThreadMessages] = useState<Record<string, RecoveryThreadMessage[]>>({});
  const [localAuditTrail, setLocalAuditTrail] = useState<Record<string, string[]>>({});
  const [createdQueueTemplates, setCreatedQueueTemplates] = useState<Record<string, RecommendedRecoveryTemplate[]>>({});

  const [isTemplateEditorOpen, setIsTemplateEditorOpen] = useState(false);
  const [isTemplateSaveChoiceOpen, setIsTemplateSaveChoiceOpen] = useState(false);
  const [isCreateTemplateOpen, setIsCreateTemplateOpen] = useState(false);
  const [templateEditorName, setTemplateEditorName] = useState("");
  const [templateEditorChannel, setTemplateEditorChannel] = useState("Manual Copy");
  const [templateEditorType, setTemplateEditorType] = useState("Follow-up");
  const [templateEditorBody, setTemplateEditorBody] = useState("");
  const [templateEditorNote, setTemplateEditorNote] = useState("");

  const [newTemplateName, setNewTemplateName] = useState("");
  const [newTemplateType, setNewTemplateType] = useState("Follow-up");
  const [newTemplateChannel, setNewTemplateChannel] = useState("Manual Copy");
  const [newTemplateBody, setNewTemplateBody] = useState("");
  const [newTemplateUseCase, setNewTemplateUseCase] = useState("");
  const [newTemplateVisibility, setNewTemplateVisibility] = useState("Owner + recovery team");

  useEffect(() => {
    if (!selectedTaskId && recoveryTasks[0]) setSelectedTaskId(recoveryTasks[0].id);
  }, [recoveryTasks, selectedTaskId]);

  const queueTabCounts = useMemo(() => {
    return queueTabs.reduce((counts, tab) => {
      counts[tab] = recoveryTasks.filter((task) => matchesQueueTab(task, tab)).length;
      return counts;
    }, {} as Record<QueueTab, number>);
  }, [recoveryTasks]);

  const filteredTasks = useMemo(() => {
    return recoveryTasks.filter((task) => matchesQueueTab(task, activeTab));
  }, [activeTab, recoveryTasks]);

  const selectedTask =
    recoveryTasks.find((task) => task.id === selectedTaskId) ??
    filteredTasks[0] ??
    recoveryTasks[0];

  const visibleQueueTasks = showAllQueueItems ? filteredTasks : filteredTasks.slice(0, 25);
  const hiddenQueueCount = Math.max(filteredTasks.length - visibleQueueTasks.length, 0);

  const recommendedTemplate = selectedTask ? getRecommendedTemplateForTask(selectedTask) : null;
  const riskReason = selectedTask ? buildRiskReason(selectedTask) : "";
  const currentMessageBody = selectedTask && recommendedTemplate ? taskMessageDrafts[selectedTask.id] ?? recommendedTemplate.body : "";
  const isServiceRecord = Boolean(selectedTask?.recordKind === "service" || selectedTask?.appointmentDate);
  const isHybridRecord = variant === "hybrid";
  const personLabel = isServiceRecord ? "Client" : workspaceConfig.language.buyer;
  const contextLabel = isServiceRecord ? "Service / appointment context" : "Product / order context";
  const valueLabel = isServiceRecord ? "Client Money still open" : "Money still open";

  const queueSummary = useMemo(() => {
    const reviewed = recoveryTasks.filter((task) => reviewedTaskIds[task.id]).length;
    const templateReady = recoveryTasks.filter((task) => templateUsedTaskIds[task.id] || taskMessageDrafts[task.id]).length;
    const calendarReady = recoveryTasks.filter((task) => calendarReadyTaskIds[task.id]).length;
    const ready = recoveryTasks.filter((task) => reviewedTaskIds[task.id] || templateUsedTaskIds[task.id] || queueReadyTaskIds[task.id] || calendarReadyTaskIds[task.id]).length;
    return { reviewed, templateReady, calendarReady, ready };
  }, [calendarReadyTaskIds, queueReadyTaskIds, recoveryTasks, reviewedTaskIds, taskMessageDrafts, templateUsedTaskIds]);

  function recordTaskEvent(task: RecoveryTask, message: string, notice?: string) {
    const time = "Now";

    setLocalThreadMessages((current) => ({
      ...current,
      [task.id]: [
        {
          id: `${task.id}-local-${Date.now()}-${Math.random().toString(16).slice(2)}`,
          author: "User",
          role: "Owner",
          message,
          time,
        },
        ...(current[task.id] ?? []),
      ],
    }));

    setLocalAuditTrail((current) => ({
      ...current,
      [task.id]: [`${message} — ${time}`, ...(current[task.id] ?? [])],
    }));

    if (notice) setDetailNotice(notice);
  }

  function openTaskDetails(taskId: string) {
    const task = recoveryTasks.find((record) => record.id === taskId) ?? selectedTask;
    if (!task) return;
    setSelectedTaskId(taskId);
    setQueueMode("detail");
    setDetailNotice("Detail page opened. Review the recommended action, template, thread, and audit trail.");
    recordTaskEvent(task, "Detail page opened for recovery review.");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function backToQueueList() {
    setQueueMode("list");
    setDetailNotice("Ready for recovery action.");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function markSelectedTaskReviewed() {
    if (!selectedTask) return;

    if (reviewedTaskIds[selectedTask.id]) {
      setReviewedTaskIds((current) => ({ ...current, [selectedTask.id]: false }));
      setQueueReadyTaskIds((current) => ({ ...current, [selectedTask.id]: false }));
      recordTaskEvent(selectedTask, "Reviewed status reopened by user.", `${selectedTask.customer} reopened for review.`);
      return;
    }

    setReviewedTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    setQueueReadyTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    recordTaskEvent(selectedTask, "Action marked reviewed and ready for Run the Queue.", `${selectedTask.customer} marked reviewed and ready for Run the Queue.`);
  }

  function createFollowUpForSelectedTask() {
    if (!selectedTask) return;

    setFollowUpTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    setQueueReadyTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    recordTaskEvent(selectedTask, "Follow-up recovery action created and prepared for Run the Queue.", `Follow-up created for ${selectedTask.customer}.`);
  }

  function viewCreatedFollowUp() {
    if (!selectedTask) return;
    recordTaskEvent(selectedTask, "Related follow-up case opened from Today’s Recovery Queue.", `Opening Follow-up Recovery for ${selectedTask.customer}.`);
    onNavigate("Follow-up Recovery");
  }

  async function copyCurrentRecoveryMessage() {
    if (!selectedTask) return;

    try {
      await navigator.clipboard.writeText(currentMessageBody);
      setCopiedTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
      recordTaskEvent(selectedTask, "Message copied for manual follow-up.", `Copied message for ${selectedTask.customer}.`);
    } catch {
      setDetailNotice("Copy failed. Please copy the message manually.");
    }
  }

  function useApprovedTemplate() {
    if (!selectedTask || !recommendedTemplate) return;

    setTaskMessageDrafts((current) => ({ ...current, [selectedTask.id]: recommendedTemplate.body }));
    setTemplateUsedTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    setQueueReadyTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    recordTaskEvent(selectedTask, "Approved template applied and message marked ready.", `Approved template used for ${selectedTask.customer}.`);
  }

  function openTemplateSetup() {
    if (!selectedTask || !recommendedTemplate) return;
    setTemplateEditorName(recommendedTemplate.name);
    setTemplateEditorChannel(isServiceRecord ? "WhatsApp" : "Instagram DM");
    setTemplateEditorType(recommendedTemplate.type);
    setTemplateEditorBody(currentMessageBody);
    setTemplateEditorNote("Use this where the buyer/client needs a reviewed recovery message.");
    setIsTemplateEditorOpen(true);
    recordTaskEvent(selectedTask, "Template editor opened.", `Editing template for ${selectedTask.customer}.`);
  }

  function closeTemplateEditor() {
    setIsTemplateEditorOpen(false);
    setIsTemplateSaveChoiceOpen(false);
  }

  function requestTemplateSaveChoice() {
    if (!templateEditorBody.trim()) {
      setDetailNotice("Template message cannot be empty.");
      return;
    }
    setIsTemplateSaveChoiceOpen(true);
  }

  function applyTemplateEdit(mode: "permanent" | "action") {
    if (!selectedTask || !recommendedTemplate) return;
    const cleanedBody = templateEditorBody.trim();
    if (!cleanedBody) {
      setDetailNotice("Template message cannot be empty.");
      return;
    }

    setTaskMessageDrafts((current) => ({ ...current, [selectedTask.id]: cleanedBody }));
    setTemplateUsedTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    setQueueReadyTaskIds((current) => ({ ...current, [selectedTask.id]: true }));

    if (mode === "permanent") {
      const savedTemplate: RecommendedRecoveryTemplate = {
        name: templateEditorName || recommendedTemplate.name,
        type: templateEditorType || recommendedTemplate.type,
        status: "Approved template available",
        matchReason: templateEditorNote || "Saved from Today’s Recovery Queue template edit.",
        body: cleanedBody,
      };

      setCreatedQueueTemplates((current) => ({
        ...current,
        [selectedTask.id]: [savedTemplate, ...(current[selectedTask.id] ?? [])],
      }));

      try {
        const existing = JSON.parse(window.localStorage.getItem("altynx-custom-message-templates") ?? "[]") as RecommendedRecoveryTemplate[];
        window.localStorage.setItem("altynx-custom-message-templates", JSON.stringify([savedTemplate, ...existing]));
      } catch {
        // local template persistence is best-effort for the MVP demo.
      }

      recordTaskEvent(selectedTask, "Saved template updated permanently and applied to this recovery action.", "Template saved permanently and applied to this action.");
    } else {
      recordTaskEvent(selectedTask, "Template edited for this recovery action only.", "Edited message applied to this recovery action only.");
    }

    setIsTemplateEditorOpen(false);
    setIsTemplateSaveChoiceOpen(false);
  }

  function openCreateTemplate() {
    if (!selectedTask || !recommendedTemplate) return;
    setNewTemplateName(`${isServiceRecord ? "Service" : "Product"} recovery follow-up`);
    setNewTemplateType(recommendedTemplate.type);
    setNewTemplateChannel(isServiceRecord ? "WhatsApp" : "Instagram DM");
    setNewTemplateBody(currentMessageBody);
    setNewTemplateUseCase(`${selectedTask.productInterest} — ${selectedTask.source}`);
    setNewTemplateVisibility("Owner + recovery team");
    setIsCreateTemplateOpen(true);
    recordTaskEvent(selectedTask, "Create new template popup opened.", "Create new template opened.");
  }

  function closeCreateTemplate() {
    setIsCreateTemplateOpen(false);
  }

  function persistNewTemplate(attachToAction: boolean) {
    if (!selectedTask) return;
    const cleanedBody = newTemplateBody.trim();
    const cleanedName = newTemplateName.trim();

    if (!cleanedName || !cleanedBody) {
      setDetailNotice("Template name and message body are required.");
      return;
    }

    const savedTemplate: RecommendedRecoveryTemplate = {
      name: cleanedName,
      type: newTemplateType || "Follow-up",
      status: "Approved template available",
      matchReason: newTemplateUseCase || "Created from Today’s Recovery Queue.",
      body: cleanedBody,
    };

    setCreatedQueueTemplates((current) => ({
      ...current,
      [selectedTask.id]: [savedTemplate, ...(current[selectedTask.id] ?? [])],
    }));

    try {
      const existing = JSON.parse(window.localStorage.getItem("altynx-custom-message-templates") ?? "[]") as RecommendedRecoveryTemplate[];
      window.localStorage.setItem("altynx-custom-message-templates", JSON.stringify([savedTemplate, ...existing]));
    } catch {
      // local template persistence is best-effort for the MVP demo.
    }

    if (attachToAction) {
      setTaskMessageDrafts((current) => ({ ...current, [selectedTask.id]: cleanedBody }));
      setTemplateUsedTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
      setQueueReadyTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
      recordTaskEvent(selectedTask, "New template created, saved, and attached to this recovery action.", "New template created and used for this action.");
    } else {
      recordTaskEvent(selectedTask, "New template saved to Templates library.", "New template saved to Templates library.");
    }

    setIsCreateTemplateOpen(false);
  }

  function openTemplatesLibrary() {
    if (selectedTask) recordTaskEvent(selectedTask, "Templates library opened from recovery action.");
    onNavigate("Templates");
  }

  function runCalendarAction(action: string) {
    if (!selectedTask) return;
    setCalendarReadyTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    setQueueReadyTaskIds((current) => ({ ...current, [selectedTask.id]: true }));
    recordTaskEvent(selectedTask, `${action} added as a calendar recovery action.`, `${action} added for ${selectedTask.customer}.`);
  }

  function openRelatedCase() {
    if (!selectedTask) return;
    recordTaskEvent(selectedTask, "Original follow-up opened from Today’s Recovery Queue.", `Opening Original follow-up ${selectedTask.relatedCase ?? selectedTask.id}.`);
    onNavigate(selectedTask.recordKind === "service" ? "Revenue Pipeline" : "Revenue Pipeline");
  }

  if (!selectedTask) {
    return (
      <section className="glass-card panel-card">
        <h2>Today’s Recovery Queue</h2>
        <p>No recovery actions are currently available for this workspace.</p>
      </section>
    );
  }

  const localThread = localThreadMessages[selectedTask.id] ?? [];
  const auditTrail = [
    ...(localAuditTrail[selectedTask.id] ?? []),
    ...(selectedTask.auditTrail ?? []),
    `Record created from ${selectedTask.source}.`,
  ];
  const systemThreadMessages: RecoveryThreadMessage[] = [
    {
      id: `${selectedTask.id}-system-template`,
      author: "Altynx",
      role: "System",
      message: `Matched "${recommendedTemplate?.name ?? "Recovery template"}" because ${recommendedTemplate?.matchReason ?? "this case needs a reviewed message."}`,
      time: "Now",
    },
    ...(selectedTask.dueStatus === "Overdue"
      ? [
          {
            id: `${selectedTask.id}-system-overdue`,
            author: "Altynx",
            role: "System" as const,
            message: `This recovery case is overdue. Last event: ${selectedTask.lastEvent}`,
            time: "Now",
          },
        ]
      : []),
  ];

  if (queueMode === "detail") {
    return (
      <div className="recovery-page todays-queue-workspace-page command-center-scope command-queue-page">
        <section className="queue-detail-page">
          <div className="queue-detail-topbar">
            <button className="secondary-btn" onClick={backToQueueList} type="button">
              ← Back to Today’s Recovery Queue
            </button>

            <div className="queue-detail-status">
              <span className="queue-status-pill">{selectedTask.recordKind === "service" ? "Service recovery" : "Product recovery"}</span>
              {isHybridRecord ? <span className="queue-status-pill">Hybrid workspace</span> : null}
              {reviewedTaskIds[selectedTask.id] ? <span className="queue-status-pill reviewed">✓ Reviewed</span> : null}
              {queueReadyTaskIds[selectedTask.id] ? <span className="queue-status-pill queue-ready">Ready for Run the Queue</span> : null}
              {templateUsedTaskIds[selectedTask.id] ? <span className="queue-status-pill">Template applied</span> : null}
              {calendarReadyTaskIds[selectedTask.id] ? <span className="queue-status-pill">Calendar action ready</span> : null}
              {copiedTaskIds[selectedTask.id] ? <span className="queue-status-pill">Copied</span> : null}
            </div>
          </div>

          <article className="glass-card panel-card queue-detail-card todays-detail-card">
            <div className="detail-heading">
              <div className="detail-person detail-person-no-avatar command-detail-person">
                <CommandAvatar name={selectedTask.customer} />
                <div>
                  <span className="detail-eyebrow">{personLabel} recovery detail</span>
                  <h2>{selectedTask.customer}</h2>
                  <p>{selectedTask.recordKind === "service" ? selectedTask.serviceContext ?? selectedTask.brandContext : selectedTask.productOrderContext ?? selectedTask.brandContext}</p>
                </div>
              </div>
              <strong>{selectedTask.estimatedRevenueAtRisk}</strong>
            </div>

            <div className="customer-summary-box">
              <span>{personLabel} recovery summary</span>
              <p>
                {selectedTask.customer} has {selectedTask.estimatedRevenueAtRisk} at risk from {selectedTask.source}. Owner: {selectedTask.assignedOwner}. Needs action: {selectedTask.dueStatus}. This action becomes available for Run the Queue after review or template approval.
              </p>
            </div>

            <div className="customer-summary-box">
              <span>Risk reason</span>
              <p>{riskReason}</p>
            </div>

            <div className="detail-grid workspace-detail-grid">
              <DetailField label={valueLabel} value={selectedTask.estimatedRevenueAtRisk} />
              <DetailField label="Priority" value={selectedTask.priority} />
              <DetailField label="Needs action" value={selectedTask.dueStatus} />
              <DetailField label="Owner" value={selectedTask.assignedOwner} />
              <DetailField label="Source / channel" value={selectedTask.source} />
              <DetailField label="Recommended action" value={selectedTask.recommendedNextAction} />
              {selectedTask.recordKind === "service" ? (
                <>
                  <DetailField label="Service type" value={selectedTask.serviceType ?? selectedTask.productInterest} />
                  <DetailField label="Appointment date" value={selectedTask.appointmentDate} />
                  <DetailField label="Appointment time" value={selectedTask.appointmentTime} />
                  <DetailField label="Appointment status" value={selectedTask.appointmentStatus} />
                  <DetailField label="Deposit status" value={selectedTask.depositStatus} />
                  <DetailField label="Service provider" value={selectedTask.serviceProvider} />
                  <DetailField label="Duration" value={selectedTask.duration} />
                  <DetailField label="Next available slot" value={selectedTask.nextAvailableSlot} />
                  <DetailField label="Calendar risk" value={selectedTask.calendarRisk} />
                </>
              ) : (
                <>
                  <DetailField label="Product/order interest" value={selectedTask.productInterest} />
                  <DetailField label="Product/order context" value={selectedTask.productOrderContext ?? selectedTask.brandContext} />
                  <DetailField label="Payment/order status" value={selectedTask.category} />
                  <DetailField label="Original follow-up/action" value={selectedTask.relatedCase} />
                </>
              )}
            </div>

            <div className="detail-callout">
              <span>Recommended next action</span>
              <p>{selectedTask.recommendedNextAction}</p>
            </div>

            <div className="template-box message-recommendation-box template-workflow-box">
              <div className="template-box-header">
                <div>
                  <span>Message / template recommendation</span>
                  <strong>{templateUsedTaskIds[selectedTask.id] ? "Approved template used" : recommendedTemplate?.status}</strong>
                </div>
                {templateUsedTaskIds[selectedTask.id] ? <span className="queue-status-pill reviewed">Template applied</span> : null}
              </div>

              <div className="template-match-grid">
                <DetailField label="Template match" value={recommendedTemplate?.name} />
                <DetailField label="Template type" value={recommendedTemplate?.type} />
                <div className="template-match-full">
                  <span>Match reason</span>
                  <p>{recommendedTemplate?.matchReason}</p>
                </div>
              </div>

              <div className="recommended-message-preview">
                <span>Selected message</span>
                <p>{currentMessageBody}</p>
              </div>

              <div className="template-action-row template-action-row-upgraded">
                <div className="template-left-actions">
                  <button type="button" className="template-action-primary" onClick={useApprovedTemplate}>Use Approved Template</button>
                  <button type="button" className="template-action-secondary" onClick={openTemplateSetup}>Edit Template</button>
                  <button type="button" className="template-action-secondary" onClick={copyCurrentRecoveryMessage}>{copiedTaskIds[selectedTask.id] ? "Copied ✓" : "Copy"}</button>
                </div>
                <div className="template-right-actions">
                  <button type="button" className="template-action-secondary" onClick={openCreateTemplate}>Create new template</button>
                  <button type="button" className="template-view-button" onClick={openTemplatesLibrary}>View Templates</button>
                </div>
              </div>
            </div>

            {selectedTask.recordKind === "service" ? (
              <div className="calendar-recovery-panel">
                <div className="panel-header compact-panel-header">
                  <div>
                    <h3>Calendar / appointment recovery</h3>
                    <p>Use these actions when revenue is at risk because an appointment, deposit, rebooking, or client follow-up needs attention.</p>
                  </div>
                  <Badge tone="amber">Calendar recovery</Badge>
                </div>
                <div className="calendar-action-grid">
                  {["Send appointment options", "Confirm appointment", "Request deposit", "Mark deposit paid", "Mark no-show", "Rebook appointment", "Create next-session reminder", "Add calendar note"].map((action) => (
                    <button key={action} type="button" className="secondary-btn" onClick={() => runCalendarAction(action)}>
                      {action}
                    </button>
                  ))}
                </div>
              </div>
            ) : null}

            <div className="thread-panel">
              <div className="thread-header">
                <div>
                  <h3>Internal Recovery Thread</h3>
                  <p>Short owner notes, template decisions, calendar actions, and queue readiness updates.</p>
                </div>
                <span>{selectedTask.internalRecoveryThread.length + systemThreadMessages.length + localThread.length} updates</span>
              </div>

              {[...localThread, ...systemThreadMessages, ...selectedTask.internalRecoveryThread].map((message) => (
                <div className="thread-message" key={message.id}>
                  <div>
                    <strong>{message.author}</strong>
                    <span>{message.role} - {message.time}</span>
                  </div>
                  <p>{message.message}</p>
                </div>
              ))}
            </div>

            <div className="audit-trail-panel">
              <div className="thread-header">
                <div>
                  <h3>Audit trail</h3>
                  <p>Proof of recovery decisions, message actions, reviewed status, and queue readiness.</p>
                </div>
                <span>{auditTrail.length} entries</span>
              </div>
              <div className="audit-trail-list">
                {auditTrail.slice(0, 8).map((entry, index) => (
                  <div className="audit-trail-row" key={`${selectedTask.id}-audit-${index}`}>{entry}</div>
                ))}
              </div>
            </div>

            <p className="detail-notice">{detailNotice}</p>

            <div className="detail-actions">
              <button type="button" className="primary-btn" onClick={useApprovedTemplate}>Use Template</button>
              <button type="button" className="secondary-btn" onClick={copyCurrentRecoveryMessage}>Copy Message</button>
              {followUpTaskIds[selectedTask.id] ? (
                <button type="button" className="secondary-btn" onClick={viewCreatedFollowUp}>View Follow-up</button>
              ) : (
                <button type="button" className="secondary-btn" onClick={createFollowUpForSelectedTask}>Create Follow-up</button>
              )}
              <button type="button" className="secondary-btn" onClick={openRelatedCase}>Open Original follow-up</button>
              <button type="button" className="secondary-btn" onClick={markSelectedTaskReviewed}>{reviewedTaskIds[selectedTask.id] ? "Reopen Review" : "Mark Reviewed"}</button>
            </div>
          </article>
        </section>

        {isTemplateEditorOpen ? (
          <ModalShell
            title="Edit recovery template"
            wide
            onClose={closeTemplateEditor}
            footer={
              <>
                <button className="secondary-btn" type="button" onClick={closeTemplateEditor}>Cancel</button>
                <button className="primary-btn" type="button" onClick={requestTemplateSaveChoice}>Save Template Change</button>
              </>
            }
          >
            <div className="template-editor-meta">
              <DetailField label={personLabel} value={selectedTask.customer} />
              <DetailField label="Template type" value={templateEditorType} />
              <DetailField label="Money still open" value={selectedTask.estimatedRevenueAtRisk} />
            </div>
            <div className="template-editor-field"><label>Template name</label><input value={templateEditorName} onChange={(event) => setTemplateEditorName(event.target.value)} /></div>
            <div className="template-editor-field"><label>Channel</label><select value={templateEditorChannel} onChange={(event) => setTemplateEditorChannel(event.target.value)}><option>Manual Copy</option><option>WhatsApp</option><option>Instagram DM</option><option>Email</option><option>SMS</option><option>Team note</option></select></div>
            <div className="template-editor-field"><label>Template type</label><input value={templateEditorType} onChange={(event) => setTemplateEditorType(event.target.value)} /></div>
            <div className="template-editor-field"><label>Message body</label><textarea rows={7} value={templateEditorBody} onChange={(event) => setTemplateEditorBody(event.target.value)} /></div>
            <div className="template-editor-field"><label>Team note / usage note</label><textarea rows={3} value={templateEditorNote} onChange={(event) => setTemplateEditorNote(event.target.value)} /></div>
          </ModalShell>
        ) : null}

        {isTemplateSaveChoiceOpen ? (
          <ModalShell
            title="Save template change"
            onClose={() => setIsTemplateSaveChoiceOpen(false)}
            footer={
              <>
                <button className="secondary-btn" type="button" onClick={() => setIsTemplateSaveChoiceOpen(false)}>Cancel</button>
                <button className="secondary-btn" type="button" onClick={() => applyTemplateEdit("action")}>Use Only For This Action</button>
                <button className="primary-btn" type="button" onClick={() => applyTemplateEdit("permanent")}>Save Permanently</button>
              </>
            }
          >
            <p>Do you want to update the saved template, or use this edited message only for this recovery action?</p>
            <div className="choice-card-stack">
              <div className="choice-card"><strong>Save permanently</strong><p>This updates the saved template in Setup &gt; Templates so future recovery actions can use the new version.</p></div>
              <div className="choice-card"><strong>Use only for this action</strong><p>This keeps the saved template unchanged and only updates the message for this current recovery case.</p></div>
            </div>
          </ModalShell>
        ) : null}

        {isCreateTemplateOpen ? (
          <ModalShell
            title="Create new template"
            wide
            onClose={closeCreateTemplate}
            footer={
              <>
                <button className="secondary-btn" type="button" onClick={closeCreateTemplate}>Cancel</button>
                <button className="secondary-btn" type="button" onClick={() => persistNewTemplate(false)}>Save to Templates</button>
                <button className="primary-btn" type="button" onClick={() => persistNewTemplate(true)}>Create and Use Template</button>
              </>
            }
          >
            <div className="template-editor-field"><label>Template name</label><input value={newTemplateName} onChange={(event) => setNewTemplateName(event.target.value)} /></div>
            <div className="template-editor-field"><label>Template type</label><input value={newTemplateType} onChange={(event) => setNewTemplateType(event.target.value)} /></div>
            <div className="template-editor-field"><label>Channel</label><select value={newTemplateChannel} onChange={(event) => setNewTemplateChannel(event.target.value)}><option>Manual Copy</option><option>WhatsApp</option><option>Instagram DM</option><option>Email</option><option>SMS</option><option>Team note</option></select></div>
            <div className="template-editor-field"><label>Message body</label><textarea rows={7} value={newTemplateBody} onChange={(event) => setNewTemplateBody(event.target.value)} /></div>
            <div className="template-editor-field"><label>Use case</label><input value={newTemplateUseCase} onChange={(event) => setNewTemplateUseCase(event.target.value)} /></div>
            <div className="template-editor-field"><label>Optional owner/team visibility</label><input value={newTemplateVisibility} onChange={(event) => setNewTemplateVisibility(event.target.value)} /></div>
          </ModalShell>
        ) : null}
      </div>
    );
  }

  return (
    <div className="recovery-page todays-queue-workspace-page command-center-scope command-queue-page">
      <section className="glass-card panel-card queue-list-page">
        <div className="panel-header queue-list-header">
          <div className="command-heading-with-icon">
            <span className="command-hero-icon" aria-hidden="true"><CommandIcon name="queue" /></span>
            <div>
              <span className="section-eyebrow">Daily execution screen</span>
              <h2>Today’s Recovery Queue</h2>
            <p>
              Review who needs attention, what value is at risk, why it matters today, who owns it, and which action can become ready for Run the Queue.
            </p>
            </div>
          </div>
          <div className="queue-summary-strip">
            <span>{filteredTasks.length} visible actions</span>
            <span>{queueSummary.reviewed} reviewed</span>
            <span>{queueSummary.ready} queue-ready</span>
          </div>
        </div>

        <UnifiedFilterBar<QueueTab>
          options={queueTabs.map((tab) => ({
            label: tab,
            count: queueTabCounts[tab] ?? 0,
            icon: getUnifiedFilterIconName(tab),
          }))}
          activeValue={activeTab}
          onChange={setActiveTab}
          ariaLabel="Today’s Recovery Queue filters"
          totalLabel={`${filteredTasks.length} visible actions`}
          className="command-center-unified-filter queue-unified-filter"
        />

        <div className="queue-table-heading">
          <span>{workspaceConfig.language.buyer}</span>
          <span>Value / priority</span>
          <span>Source / owner</span>
          <span>Risk reason</span>
          <span>Recommended next action</span>
          <span>Status</span>
          <span />
        </div>

        <div className="queue-record-list">
          {visibleQueueTasks.map((task) => {
            const rowReviewed = Boolean(reviewedTaskIds[task.id]);
            const rowReady = Boolean(queueReadyTaskIds[task.id] || templateUsedTaskIds[task.id] || calendarReadyTaskIds[task.id]);
            return (
              <article className="queue-record-row" key={task.id}>
                <div>
                  <div className="command-row-identity">
                    <CommandAvatar name={task.customer} />
                    <strong>{task.customer}</strong>
                  </div>
                  <div className="queue-badge-row">
                    {(task.queueBadges ?? []).slice(0, 3).map((badge) => <span key={`${task.id}-${badge}`} className="queue-mini-badge">{badge}</span>)}
                  </div>
                </div>
                <div>
                  <strong>{task.estimatedRevenueAtRisk}</strong>
                  <span className={`priority-badge ${task.priority.toLowerCase()}`}>{task.priority}</span>
                </div>
                <div className="command-source-owner-cell">
                  <span><CommandIcon name={getCommandIconForLabel(task.source)} /> {task.source}</span>
                  <strong><CommandAvatar name={task.assignedOwner} label={`Owner ${task.assignedOwner}`} /> {task.assignedOwner}</strong>
                </div>
                <div>
                  <strong>{task.productInterest}</strong>
                  <p>{task.dueStatus} · {task.recordKind === "service" ? task.calendarRisk ?? "client follow-up" : task.lastEvent}</p>
                </div>
                <div>
                  <p>{task.recommendedNextAction}</p>
                </div>
                <div className="queue-status-stack">
                  <span className="queue-status-pill">{task.dueStatus}</span>
                  {rowReviewed ? <span className="queue-status-pill reviewed">Reviewed</span> : <span className="queue-status-pill muted">Unreviewed</span>}
                  {rowReady ? <span className="queue-status-pill queue-ready">Ready</span> : null}
                </div>
                <div className="queue-row-actions">
                  <button type="button" className="secondary-btn command-icon-button" onClick={() => openTaskDetails(task.id)}><CommandIcon name="queue" /> Show Details</button>
                </div>
              </article>
            );
          })}
        </div>

        {hiddenQueueCount > 0 ? (
          <div className="pagination-row">
            <span>Showing 25 of {filteredTasks.length} actions.</span>
            <button type="button" className="secondary-btn" onClick={() => setShowAllQueueItems(true)}>Show remaining {hiddenQueueCount}</button>
          </div>
        ) : showAllQueueItems && filteredTasks.length > 25 ? (
          <div className="pagination-row">
            <span>Showing all {filteredTasks.length} actions.</span>
            <button type="button" className="secondary-btn" onClick={() => setShowAllQueueItems(false)}>Show first 25</button>
          </div>
        ) : null}
      </section>
    </div>
  );
}

function InquiryInbox({
  onActivity,
  onNavigate,
}: {
  onActivity: (activity: NewRecoveryActivity) => void;
  onNavigate: (page: string) => void;
}) {
  const workspaceProfile = getWorkspaceProfile();
  const workspaceConfig = getWorkspaceConfig(workspaceProfile);
  const variant = getWorkspaceVariant(workspaceProfile);
  const workspaceData = useWorkspaceDemoData();
  const inquiries = workspaceData.inquiries;
  const isServiceWorkspace = variant === "fashion-service" || variant === "beauty-services" || variant === "aesthetic-clinic";
  const isHybridWorkspace = variant === "hybrid";
  const personLabel = isServiceWorkspace ? "Client" : workspaceConfig.language.buyer;
  const contextLabel = isServiceWorkspace
    ? "Service / appointment context"
    : isHybridWorkspace
      ? "Product / service context"
      : variant === "retail"
        ? "Item / order context"
        : "Product / order context";
  const pageSubtitle = "Captured buyer/client inquiries from source channels before they become missed revenue.";

  type InquirySourceReadiness = {
    id: string;
    displayName: string;
    channelType: string;
    active: boolean;
    sourceStatus: "Ready" | "Needs review" | "Manual source" | "Required fields missing";
    defaultOwnerName: string;
    defaultOwnerRole: string;
    fallbackOwnerRole: string;
    firstReplyTarget: string;
    requiredFieldsReadiness: string;
    defaultRecoveryRule: string;
    defaultTemplate: string;
    queueReadyRule: string;
    lastCapturedInquiry: string;
    sourceHealthNote: string;
    tone: Tone;
  };

  function uniqueLocalStrings(values: string[]) {
    return Array.from(new Set(values.map((value) => value.trim()).filter(Boolean)));
  }

  function normalizeInquirySourceName(source: string) {
    const value = source.trim();
    const lower = value.toLowerCase();
    if (!value) return "Other";
    if (lower.includes("facebook") || lower.includes("meta inbox")) return "Facebook / Meta";
    if (lower.includes("instagram")) return "Instagram DM";
    if (lower.includes("whatsapp")) return "WhatsApp";
    if (lower.includes("website") || lower.includes("form") || lower.includes("chat")) return "Website Form";
    if (lower.includes("shopify") || lower.includes("ecommerce") || lower.includes("online store") || lower.includes("back-in-stock")) return "Shopify / Ecommerce";
    if (lower.includes("email")) return "Email";
    if (lower.includes("campaign") || lower.includes("waitlist")) return "Campaign";
    if (lower.includes("event") || lower.includes("pop-up") || lower.includes("pop up")) return "Event / Pop-up";
    if (lower.includes("referral")) return "Referral";
    if (lower.includes("csv")) return "CSV Import";
    if (lower.includes("manual")) return "Manual Entry";
    return value;
  }

  function sourceKey(value: string) {
    return normalizeInquirySourceName(value)
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
  }

  function getSourceTone(index: number, status?: string): Tone {
    if (status === "Configured") return "emerald";
    if (status === "Missing Fields") return "amber";
    if (status === "Needs Review") return "rose";
    const tones: Tone[] = ["cyan", "amber", "emerald", "indigo", "rose"];
    return tones[index % tones.length];
  }

  function getChannelType(sourceName: string) {
    const lower = sourceName.toLowerCase();
    if (lower.includes("instagram") || lower.includes("facebook") || lower.includes("meta")) return "Social inbox";
    if (lower.includes("whatsapp")) return "Messaging channel";
    if (lower.includes("website") || lower.includes("form")) return "Website capture";
    if (lower.includes("shopify") || lower.includes("ecommerce")) return "Commerce source";
    if (lower.includes("email")) return "Email source";
    if (lower.includes("campaign")) return "Campaign source";
    if (lower.includes("event")) return "Event capture";
    if (lower.includes("referral")) return "Referral source";
    if (lower.includes("csv") || lower.includes("manual")) return "Manual capture";
    return "Custom source";
  }

  function getTeamRoleForOwner(ownerName: string) {
    const setupUser = setupTeamUsers.find((member) => member.name === ownerName);
    if (setupUser) return setupUser.role;
    const teamUser = teamUsers.find((member) => member.name === ownerName);
    if (teamUser) return teamUser.role;
    if (ownerName === "Unassigned Queue") return "Unassigned";
    if (ownerName === "Operations") return "Operations";
    return ownerName || "Recovery Lead";
  }

  function mapSetupStatus(status: SourceSetupRecord["sourceStatus"]): InquirySourceReadiness["sourceStatus"] {
    if (status === "Configured") return "Ready";
    if (status === "Missing Fields") return "Required fields missing";
    return "Needs review";
  }

  function getDefaultTemplateForSource(sourceName: string) {
    const lower = sourceName.toLowerCase();
    if (lower.includes("whatsapp")) return "WhatsApp first reply / payment nudge";
    if (lower.includes("instagram") || lower.includes("facebook") || lower.includes("meta")) return "Social inbox first reply";
    if (lower.includes("website") || lower.includes("form")) return "Website inquiry first reply";
    if (lower.includes("shopify") || lower.includes("ecommerce")) return "Order / checkout recovery reply";
    if (lower.includes("event")) return "Event follow-up reply";
    if (lower.includes("referral")) return "Referral thank-you reply";
    if (lower.includes("email")) return "Email inquiry follow-up";
    return "Manual inquiry follow-up";
  }

  function buildSourceReadinessRows(baseInquiries: Inquiry[]): InquirySourceReadiness[] {
    const profileSourceNames = uniqueLocalStrings((workspaceProfile.salesChannels ?? []).map(normalizeInquirySourceName));
    const inquirySourceNames = uniqueLocalStrings(baseInquiries.map((inquiry) => normalizeInquirySourceName(inquiry.inquirySource)));
    const configuredSetupNames = uniqueLocalStrings(sourceSetupRecords.map((source) => normalizeInquirySourceName(source.sourceName)));
    const allNames = uniqueLocalStrings([...profileSourceNames, ...inquirySourceNames, ...configuredSetupNames]);

    return allNames.map((displayName, index) => {
      const setupSource = sourceSetupRecords.find((source) => sourceKey(source.sourceName) === sourceKey(displayName));
      const sourceInquiries = baseInquiries.filter((inquiry) => sourceKey(inquiry.inquirySource) === sourceKey(displayName));
      const profileConfigured = profileSourceNames.some((name) => sourceKey(name) === sourceKey(displayName));
      const hasInquiries = sourceInquiries.length > 0;
      const sourceStatus = setupSource ? mapSetupStatus(setupSource.sourceStatus) : profileConfigured ? "Manual source" : "Needs review";
      const defaultOwnerName = setupSource?.defaultOwner ?? (profileConfigured ? workspaceProfile.followUpOwner || "Owner" : "Unassigned Queue");
      const requiredFieldsReadiness = setupSource?.missingFieldWarning && setupSource.missingFieldWarning !== "None"
        ? setupSource.missingFieldWarning
        : "Required source, context, value, first reply, and owner routing fields ready";
      const lastCaptured = sourceInquiries[0]
        ? `${sourceInquiries[0].customer} · ${sourceInquiries[0].timeSinceInquiry} ago`
        : "No inquiries captured yet";
      const active = profileConfigured || hasInquiries || setupSource?.sourceStatus === "Configured";
      const needsFirstReply = sourceInquiries.filter((inquiry) => inquiry.firstReplyStatus !== "Replied").length;
      const needsReview = sourceStatus !== "Ready" || sourceInquiries.some((inquiry) => inquiry.firstReplyStatus === "Needs human review");

      return {
        id: `source-${sourceKey(displayName) || index}`,
        displayName,
        channelType: getChannelType(displayName),
        active,
        sourceStatus,
        defaultOwnerName,
        defaultOwnerRole: getTeamRoleForOwner(defaultOwnerName),
        fallbackOwnerRole: "Operations",
        firstReplyTarget: needsFirstReply > 0 ? "2 hours for high-intent inquiries" : "4 hours standard target",
        requiredFieldsReadiness,
        defaultRecoveryRule: setupSource?.recoveryRule ?? `Create an inquiry recovery case when ${displayName} captures high-intent interest.`,
        defaultTemplate: getDefaultTemplateForSource(displayName),
        queueReadyRule: "Source ready + owner routed + approved template + recovery case created + reviewed.",
        lastCapturedInquiry: lastCaptured,
        sourceHealthNote: hasInquiries
          ? `${sourceInquiries.length} captured · ${needsFirstReply} need first reply · ${needsReview ? "needs review" : "routing ready"}`
          : active
            ? "Connected channel with no captured inquiries yet."
            : "Inactive source. Enable it only if this channel should feed Inquiry Inbox.",
        tone: setupSource?.tone ?? getSourceTone(index, setupSource?.sourceStatus),
      };
    });
  }

  const [inquiryRecords, setInquiryRecords] = useState<Inquiry[]>(inquiries);
  const [sourceConfigs, setSourceConfigs] = useState<InquirySourceReadiness[]>(() => buildSourceReadinessRows(inquiries));
  const [activeSourceTab, setActiveSourceTab] = useState("All");
  const [selectedInquiryId, setSelectedInquiryId] = useState(inquiries[0]?.id ?? "");
  const [inquiryMode, setInquiryMode] = useState<"list" | "detail">("list");
  const [detailNotice, setDetailNotice] = useState("Ready to triage captured interest.");
  const [toastMessage, setToastMessage] = useState("");
  const [showAllInquiries, setShowAllInquiries] = useState(false);
  const [activeCaptureDetail, setActiveCaptureDetail] = useState<CaptureDetailRecord | null>(null);
  const [captureDetailMode, setCaptureDetailMode] = useState<"drawer" | "full" | null>(null);

  const [isInternalNoteOpen, setIsInternalNoteOpen] = useState(false);
  const [internalNoteDraft, setInternalNoteDraft] = useState("");
  const [isAuditOpen, setIsAuditOpen] = useState(false);
  const [isEditTemplateOpen, setIsEditTemplateOpen] = useState(false);
  const [isTemplateSaveChoiceOpen, setIsTemplateSaveChoiceOpen] = useState(false);
  const [isCreateTemplateOpen, setIsCreateTemplateOpen] = useState(false);
  const [isTemplateLibraryOpen, setIsTemplateLibraryOpen] = useState(false);

  const [localInquiryNotes, setLocalInquiryNotes] = useState<Record<string, string[]>>({});
  const [localAuditTrail, setLocalAuditTrail] = useState<Record<string, string[]>>({});
  const [localRecoveryLog, setLocalRecoveryLog] = useState<Record<string, string[]>>({});
  const [messageDrafts, setMessageDrafts] = useState<Record<string, string>>({});
  const [templateUsedIds, setTemplateUsedIds] = useState<Record<string, boolean>>({});
  const [copiedTemplateIds, setCopiedTemplateIds] = useState<Record<string, boolean>>({});
  const [replySentIds, setReplySentIds] = useState<Record<string, boolean>>({});
  const [caseCreatedIds, setCaseCreatedIds] = useState<Record<string, boolean>>({});
  const [reviewedCaseIds, setReviewedCaseIds] = useState<Record<string, boolean>>({});
  const [queueReadyIds, setQueueReadyIds] = useState<Record<string, boolean>>({});

  const [editTemplateName, setEditTemplateName] = useState("");
  const [editTemplateType, setEditTemplateType] = useState("");
  const [editTemplateChannel, setEditTemplateChannel] = useState("");
  const [editTemplateBody, setEditTemplateBody] = useState("");
  const [editTemplateNote, setEditTemplateNote] = useState("");
  const [newTemplateName, setNewTemplateName] = useState("");
  const [newTemplateType, setNewTemplateType] = useState("");
  const [newTemplateChannel, setNewTemplateChannel] = useState("");
  const [newTemplateBody, setNewTemplateBody] = useState("");
  const [newTemplateUseCase, setNewTemplateUseCase] = useState("");

  useEffect(() => {
    setInquiryRecords(inquiries);
    setSourceConfigs(buildSourceReadinessRows(inquiries));
    setSelectedInquiryId((current) => current && inquiries.some((inquiry) => inquiry.id === current) ? current : inquiries[0]?.id ?? "");
    setActiveSourceTab("All");
    setInquiryMode("list");
    setShowAllInquiries(false);
  }, [inquiries]);

  function getSourceConfigForName(sourceName: string) {
    return sourceConfigs.find((source) => sourceKey(source.displayName) === sourceKey(sourceName));
  }

  function getSourceConfigForInquiry(inquiry: Inquiry) {
    return getSourceConfigForName(inquiry.inquirySource);
  }

  function getOwnerRoutingState(inquiry: Inquiry) {
    const sourceConfig = getSourceConfigForInquiry(inquiry);
    const normalizedOwner = inquiry.owner.trim();
    const sourceMissing = !sourceConfig || !sourceConfig.active || sourceConfig.sourceStatus === "Required fields missing";
    const sourceRuleMissing = sourceConfig?.sourceStatus === "Needs review" || sourceConfig?.sourceStatus === "Manual source";
    const ownerMissing = !normalizedOwner || normalizedOwner === "Unassigned" || normalizedOwner === "Unassigned Queue";
    const defaultOwnerMissing = !sourceConfig?.defaultOwnerName || sourceConfig.defaultOwnerName === "Unassigned Queue" || sourceConfig.defaultOwnerRole === "Unassigned";

    if (sourceMissing || sourceRuleMissing) {
      return {
        kind: "source-rule-gap" as const,
        label: "Routing needs attention",
        owner: sourceConfig?.defaultOwnerName ?? "Not routed",
        helper: "This inquiry needs a simple source or routing check before the team acts.",
        tone: "amber" as Tone,
      };
    }

    if (ownerMissing && defaultOwnerMissing) {
      return {
        kind: "team-rule-gap" as const,
        label: "Needs assigned owner",
        owner: "Not routed",
        helper: "Assign an owner so this inquiry has a clear next action.",
        tone: "rose" as Tone,
      };
    }

    return {
      kind: "routed" as const,
      label: "Routed owner",
      owner: ownerMissing ? sourceConfig?.defaultOwnerName ?? "Operations" : normalizedOwner,
      helper: ownerMissing ? "Owner routed from the source rule." : "Owner already routed on the inquiry.",
      tone: "emerald" as Tone,
    };
  }

  function getQueueReadyState(inquiry: Inquiry) {
    const routing = getOwnerRoutingState(inquiry);
    const sourceConfig = getSourceConfigForInquiry(inquiry);
    const sourceReady = Boolean(sourceConfig?.active && sourceConfig.sourceStatus === "Ready");
    const ownerReady = routing.kind === "routed";
    const templateReady = Boolean(templateUsedIds[inquiry.id] || inquiry.templateStatus === "Template applied" || inquiry.templateStatus === "Custom message ready");
    const caseReady = Boolean(caseCreatedIds[inquiry.id] || inquiry.recoveryCaseCreated);
    const reviewedReady = Boolean(reviewedCaseIds[inquiry.id] || inquiry.reviewed);
    return sourceReady && ownerReady && templateReady && caseReady && reviewedReady;
  }

  function sourceTabCount(tab: string) {
    return inquiryRecords.filter((inquiry) => matchesSourceTab(inquiry, tab)).length;
  }

  const sourceTabs = useMemo(() => {
    const activeSourceNames = sourceConfigs
      .filter((source) => source.active)
      .map((source) => source.displayName);
    const systemTabs = ["Needs Review", "Owner Routing Gap", "First Reply Needed"];
    return ["All", ...uniqueLocalStrings(activeSourceNames), ...systemTabs];
  }, [sourceConfigs, inquiryRecords]);

  function matchesSourceTab(inquiry: Inquiry, tab: string) {
    if (tab === "All") return true;
    if (tab === "Needs Review") {
      const sourceConfig = getSourceConfigForInquiry(inquiry);
      return inquiry.firstReplyStatus === "Needs human review" || sourceConfig?.sourceStatus === "Needs review" || sourceConfig?.sourceStatus === "Required fields missing";
    }
    if (tab === "Owner Routing Gap") return getOwnerRoutingState(inquiry).kind !== "routed";
    if (tab === "First Reply Needed") return inquiry.firstReplyStatus !== "Replied";
    return sourceKey(inquiry.inquirySource) === sourceKey(tab);
  }


  function openInquiryCaptureDetail(inquiry: Inquiry) {
    const record = inquiry as unknown as Record<string, unknown>;
    const detail = isCaptureServiceContext(inquiry) ? buildCaptureServiceDetail(record) : buildCaptureProductDetail(record);
    setActiveCaptureDetail(detail);
    setCaptureDetailMode("drawer");
  }

  const filteredInquiries = inquiryRecords.filter((inquiry) => matchesSourceTab(inquiry, activeSourceTab));

  const selectedInquiry =
    inquiryRecords.find((inquiry) => inquiry.id === selectedInquiryId) ??
    filteredInquiries[0] ??
    inquiryRecords[0];

  const visibleInquiries = showAllInquiries ? filteredInquiries : filteredInquiries.slice(0, 25);
  const hiddenInquiryCount = Math.max(filteredInquiries.length - visibleInquiries.length, 0);

  const selectedMessage = selectedInquiry ? messageDrafts[selectedInquiry.id] ?? selectedInquiry.templatePreview : "";
  const selectedNotes = selectedInquiry ? localInquiryNotes[selectedInquiry.id] ?? [] : [];
  const selectedAudit = selectedInquiry ? [
    ...(localAuditTrail[selectedInquiry.id] ?? []),
    ...(selectedInquiry.auditTrail ?? []),
    `Inquiry captured from ${selectedInquiry.inquirySource}.`,
  ] : [];
  const selectedRecoveryLog = selectedInquiry ? [
    ...(localRecoveryLog[selectedInquiry.id] ?? []),
    ...(selectedInquiry.recoveryLog ?? []),
    selectedInquiry.automationStatus,
  ] : [];
  const selectedIsService = Boolean(selectedInquiry?.recordKind === "service" || selectedInquiry?.appointmentDate || selectedInquiry?.calendarRisk);
  const selectedPersonLabel = selectedIsService ? "Client" : personLabel;
  const selectedRoutingState = selectedInquiry ? getOwnerRoutingState(selectedInquiry) : null;
  const selectedSourceConfig = selectedInquiry ? getSourceConfigForInquiry(selectedInquiry) : null;
  const selectedQueueReady = selectedInquiry ? getQueueReadyState(selectedInquiry) || Boolean(queueReadyIds[selectedInquiry.id] && selectedSourceConfig?.sourceStatus === "Ready" && selectedRoutingState?.kind === "routed") : false;

  const inquirySummary = useMemo(() => {
    const firstReplyNeeded = inquiryRecords.filter((item) => item.firstReplyStatus !== "Replied").length;
    const ownerMissing = inquiryRecords.filter((item) => getOwnerRoutingState(item).kind !== "routed").length;
    const reviewed = inquiryRecords.filter((item) => reviewedCaseIds[item.id] || item.reviewed).length;
    const queueReady = inquiryRecords.filter((item) => getQueueReadyState(item)).length;
    const totalValue = inquiryRecords.reduce((total, inquiry) => total + moneyToNumber(inquiry.estimatedValue), 0);
    return { firstReplyNeeded, ownerMissing, reviewed, queueReady, totalValue };
  }, [inquiryRecords, sourceConfigs, queueReadyIds, reviewedCaseIds, templateUsedIds, caseCreatedIds]);

  const sourceHealthRows = sourceConfigs.filter((source) => source.active).slice(0, 6);

  function addInquiryAudit(inquiry: Inquiry, message: string) {
    const line = `${message} — Now`;
    setLocalAuditTrail((current) => ({
      ...current,
      [inquiry.id]: [line, ...(current[inquiry.id] ?? [])],
    }));
    setLocalRecoveryLog((current) => ({
      ...current,
      [inquiry.id]: [message, ...(current[inquiry.id] ?? [])],
    }));
  }

  function updateInquiryRecord(inquiryId: string, updater: (inquiry: Inquiry) => Inquiry) {
    setInquiryRecords((records) => records.map((record) => record.id === inquiryId ? updater(record) : record));
  }

  function recordInquiryActivity(
    inquiry: Inquiry,
    title: string,
    status: string,
    nextAction = inquiry.recommendedAction,
    owner = getOwnerRoutingState(inquiry).owner,
  ) {
    onActivity({
      category: "Inquiries",
      title,
      description: `${inquiry.customer}'s ${inquiry.productInterest.toLowerCase()} was updated from ${normalizeInquirySourceName(inquiry.inquirySource)}.`,
      impactBadge: `${inquiry.estimatedValue} at risk`,
      relatedRecord: `${normalizeInquirySourceName(inquiry.inquirySource)} - ${inquiry.id}`,
      owner: owner === "Not routed" || owner === "Unassigned" ? undefined : owner,
      status,
      nextAction,
      tone: inquiry.tone,
    });
    addInquiryAudit(inquiry, title);
  }

  function openInquiryDetails(inquiry: Inquiry) {
    setSelectedInquiryId(inquiry.id);
    setInquiryMode("detail");
    setIsInternalNoteOpen(false);
    setIsAuditOpen(false);
    setDetailNotice("Detail view opened. Review the buyer context, reply status, recommended action, owner, message, recovery case, and audit trail.");
    addInquiryAudit(inquiry, "Detail view opened");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function backToInquiryList() {
    setInquiryMode("list");
    setIsInternalNoteOpen(false);
    setIsAuditOpen(false);
    setDetailNotice("Ready to triage captured interest.");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function markFirstReplySent(inquiry = selectedInquiry) {
    if (!inquiry) return;
    updateInquiryRecord(inquiry.id, (record) => ({ ...record, firstReplyStatus: "Replied", lastAction: "First reply marked sent" }));
    setReplySentIds((current) => ({ ...current, [inquiry.id]: true }));
    setDetailNotice(`First reply marked sent for ${inquiry.customer}.`);
    setToastMessage("First reply status updated.");
    recordInquiryActivity(inquiry, "First reply marked sent", "First reply sent", "Watch for response and conversion signal.");
  }

  function createRecoveryCase(inquiry = selectedInquiry) {
    if (!inquiry) return;
    updateInquiryRecord(inquiry.id, (record) => ({
      ...record,
      recoveryCaseCreated: true,
      relatedCase: record.relatedCase ?? `CASE-${record.id}`,
      lastAction: "Recovery case created",
    }));
    setCaseCreatedIds((current) => ({ ...current, [inquiry.id]: true }));
    setDetailNotice(`Recovery case created for ${inquiry.customer}.`);
    setToastMessage("Recovery case created and attached to this inquiry.");
    recordInquiryActivity(inquiry, "Recovery case created", "Recovery case created");
  }

  function useApprovedTemplate(inquiry = selectedInquiry) {
    if (!inquiry) return;
    setMessageDrafts((current) => ({ ...current, [inquiry.id]: inquiry.templatePreview }));
    setTemplateUsedIds((current) => ({ ...current, [inquiry.id]: true }));
    updateInquiryRecord(inquiry.id, (record) => ({ ...record, templateStatus: "Template applied", lastAction: "Approved template used" }));
    setDetailNotice(`Approved template applied for ${inquiry.customer}. Create a recovery case and mark reviewed to make it queue-ready.`);
    setToastMessage("Approved template selected for this inquiry.");
    recordInquiryActivity(inquiry, "Approved template applied", "Template applied");
  }

  async function copyInquiryMessage(inquiry = selectedInquiry) {
    if (!inquiry) return;
    const messageToCopy = messageDrafts[inquiry.id] ?? inquiry.templatePreview;
    try {
      await navigator.clipboard.writeText(messageToCopy);
      setCopiedTemplateIds((current) => ({ ...current, [inquiry.id]: true }));
      updateInquiryRecord(inquiry.id, (record) => ({ ...record, templateCopied: true, lastAction: "Message copied" }));
      setToastMessage("Manual copy logged. Send the message from the selected channel and keep the inquiry trail updated.");
      setDetailNotice("Message copied and logged without covering the action buttons.");
      recordInquiryActivity(inquiry, "Message copied for manual follow-up", "Message copied");
    } catch {
      setToastMessage("Copy failed. Please copy the message manually.");
    }
  }

  function openEditTemplate() {
    if (!selectedInquiry) return;
    setEditTemplateName(`${selectedInquiry.intentLevel} inquiry follow-up`);
    setEditTemplateType(selectedIsService ? "Appointment / service inquiry" : "Product / order inquiry");
    setEditTemplateChannel(normalizeInquirySourceName(selectedInquiry.inquirySource));
    setEditTemplateBody(selectedMessage);
    setEditTemplateNote("Use when this inquiry type needs an owner-reviewed first reply before queue review.");
    setIsEditTemplateOpen(true);
  }

  function requestTemplateSaveChoice() {
    if (!editTemplateBody.trim()) {
      setDetailNotice("Template body cannot be empty.");
      return;
    }
    setIsEditTemplateOpen(false);
    setIsTemplateSaveChoiceOpen(true);
  }

  function saveTemplateChange(scope: "permanent" | "single") {
    if (!selectedInquiry) return;
    setMessageDrafts((current) => ({ ...current, [selectedInquiry.id]: editTemplateBody }));
    setTemplateUsedIds((current) => ({ ...current, [selectedInquiry.id]: true }));
    updateInquiryRecord(selectedInquiry.id, (record) => ({
      ...record,
      templateStatus: "Custom message ready",
      templatePreview: editTemplateBody,
      lastAction: scope === "permanent" ? "Template updated permanently" : "Template customized for this inquiry",
    }));
    setIsTemplateSaveChoiceOpen(false);
    setDetailNotice(scope === "permanent" ? "Saved template updated in Setup > Templates." : "This inquiry message was customized without changing the saved team template.");
    setToastMessage(scope === "permanent" ? "Template saved to the library." : "Template customized for this inquiry.");
    recordInquiryActivity(selectedInquiry, scope === "permanent" ? "Template updated permanently" : "Template customized for this inquiry only", "Template updated");
  }

  function openCreateTemplate() {
    if (!selectedInquiry) return;
    setNewTemplateName(`${selectedInquiry.intentLevel} ${selectedIsService ? "client" : "buyer"} inquiry template`);
    setNewTemplateType(selectedIsService ? "Appointment / service inquiry" : "Product / order inquiry");
    setNewTemplateChannel(normalizeInquirySourceName(selectedInquiry.inquirySource));
    setNewTemplateBody(selectedMessage || selectedInquiry.templatePreview);
    setNewTemplateUseCase(`Use for ${selectedInquiry.productInterest.toLowerCase()} from ${normalizeInquirySourceName(selectedInquiry.inquirySource)}.`);
    setIsCreateTemplateOpen(true);
  }

  function createInquiryTemplate(attachToCurrent: boolean) {
    if (!selectedInquiry) return;
    if (!newTemplateName.trim() || !newTemplateBody.trim()) {
      setDetailNotice("Template name and message body are required.");
      return;
    }
    if (attachToCurrent) {
      setMessageDrafts((current) => ({ ...current, [selectedInquiry.id]: newTemplateBody }));
      setTemplateUsedIds((current) => ({ ...current, [selectedInquiry.id]: true }));
      updateInquiryRecord(selectedInquiry.id, (record) => ({ ...record, templateStatus: "Template applied", templatePreview: newTemplateBody, lastAction: "New template created and used" }));
    }
    setIsCreateTemplateOpen(false);
    setDetailNotice(attachToCurrent ? "New template created and attached to this inquiry." : "New template saved to Setup > Templates.");
    setToastMessage(attachToCurrent ? "New template created and used for this inquiry." : "New template saved to Templates.");
    recordInquiryActivity(selectedInquiry, attachToCurrent ? "New template created and used" : "New template saved to library", "Template created");
  }

  function markReviewed(inquiry = selectedInquiry) {
    if (!inquiry) return;
    const currentlyReviewed = Boolean(reviewedCaseIds[inquiry.id] || inquiry.reviewed);
    setReviewedCaseIds((current) => ({ ...current, [inquiry.id]: !currentlyReviewed }));
    updateInquiryRecord(inquiry.id, (record) => ({ ...record, reviewed: !currentlyReviewed, lastAction: currentlyReviewed ? "Review reopened" : "Marked reviewed" }));
    setDetailNotice(currentlyReviewed ? "Inquiry reopened for review." : "Inquiry marked reviewed. It becomes queue-ready when the owner, template, and recovery case are ready.");
    setToastMessage(currentlyReviewed ? "Review reopened." : "Inquiry marked reviewed.");
    recordInquiryActivity(inquiry, currentlyReviewed ? "Inquiry review reopened" : "Inquiry marked reviewed", currentlyReviewed ? "Reopened" : "Reviewed");
  }

  function addInternalNote() {
    if (!selectedInquiry) return;
    const note = internalNoteDraft.trim();
    if (!note) {
      setDetailNotice("Write an Team note before saving.");
      return;
    }
    setLocalInquiryNotes((current) => ({ ...current, [selectedInquiry.id]: [`${note} — Now`, ...(current[selectedInquiry.id] ?? [])] }));
    updateInquiryRecord(selectedInquiry.id, (record) => ({ ...record, internalNotes: record.internalNotes + 1, lastAction: "Team note added" }));
    setInternalNoteDraft("");
    setIsInternalNoteOpen(false);
    setDetailNotice(`Team note added for ${selectedInquiry.customer}.`);
    setToastMessage("Team note added to the recovery trail.");
    recordInquiryActivity(selectedInquiry, "Team note added", "Team note");
  }

  function addCalendarAction(action: string) {
    if (!selectedInquiry) return;
    updateInquiryRecord(selectedInquiry.id, (record) => ({
      ...record,
      appointmentStatus: action.includes("Confirm") ? "Confirmed" : action.includes("Rebook") ? "Needs rebooking" : record.appointmentStatus,
      depositStatus: action.includes("paid") ? "Paid" : action.includes("Deposit") ? "Pending" : record.depositStatus,
      calendarRisk: action.includes("Confirm") ? undefined : record.calendarRisk,
      lastAction: action,
    }));
    setDetailNotice(`${action} added to the inquiry recovery log.`);
    setToastMessage(`${action} logged for this inquiry.`);
    recordInquiryActivity(selectedInquiry, action, "Calendar recovery action");
  }

  function getInquiryRiskReason(inquiry: Inquiry) {
    const routing = getOwnerRoutingState(inquiry);
    if (routing.kind !== "routed") return `${inquiry.estimatedValue} is at risk because ${routing.label.toLowerCase()}. This inquiry needs a clear owner before the next recovery action moves forward.`;
    if (inquiry.firstReplyStatus === "Not replied") return `${inquiry.estimatedValue} is at risk because this inquiry has not received a first reply yet. Source: ${normalizeInquirySourceName(inquiry.inquirySource)}. Recommended action: ${inquiry.recommendedAction}`;
    if (inquiry.firstReplyStatus === "Needs human review") return `${inquiry.estimatedValue} needs human review because the captured source, message, or payment context needs confirmation.`;
    if (inquiry.calendarRisk) return `${inquiry.estimatedValue} is at risk because the appointment or deposit status needs attention: ${inquiry.calendarRisk}.`;
    return `${inquiry.estimatedValue} is attached to this inquiry. Keep the reply, owner, template, recovery case, and review status current until it is resolved.`;
  }

  const templateLibraryOptions = selectedInquiry
    ? [
        { name: "Approved first reply", body: selectedInquiry.templatePreview },
        {
          name: selectedIsService ? "Appointment options reply" : variant === "retail" ? "Order inquiry reply" : "Product guidance reply",
          body: selectedIsService
            ? `Hi ${selectedInquiry.customer.split(" ")[0]}, I can send the next available appointment options and confirm the deposit details for you.`
            : `Hi ${selectedInquiry.customer.split(" ")[0]}, I can help with ${selectedInquiry.productInterest.toLowerCase()} and send the best next step.`,
        },
        {
          name: selectedIsService ? "Deposit follow-up" : "Payment follow-up",
          body: selectedIsService
            ? `Hi ${selectedInquiry.customer.split(" ")[0]}, your appointment is almost confirmed. I can send the deposit details to hold the slot.`
            : `Hi ${selectedInquiry.customer.split(" ")[0]}, your payment is still open. I can resend the link or help with checkout.`,
        },
      ]
    : [];

  function renderTemplateModals() {
    return (
      <>
        {isEditTemplateOpen ? (
          <ModalShell title="Edit Template" onClose={() => setIsEditTemplateOpen(false)} wide>
            <div className="inquiry-template-form-grid">
              <label>Template name<input value={editTemplateName} onChange={(event) => setEditTemplateName(event.target.value)} /></label>
              <label>Template type<input value={editTemplateType} onChange={(event) => setEditTemplateType(event.target.value)} /></label>
              <label>Channel/source<input value={editTemplateChannel} onChange={(event) => setEditTemplateChannel(event.target.value)} /></label>
              <label>Use case<input value={editTemplateNote} onChange={(event) => setEditTemplateNote(event.target.value)} /></label>
              <label className="template-editor-full">Message body<textarea rows={7} value={editTemplateBody} onChange={(event) => setEditTemplateBody(event.target.value)} /></label>
            </div>
            <div className="inquiry-modal-actions"><button type="button" className="primary-btn" onClick={requestTemplateSaveChoice}>Save</button><button type="button" className="secondary-btn" onClick={() => setIsEditTemplateOpen(false)}>Cancel</button></div>
          </ModalShell>
        ) : null}

        {isTemplateSaveChoiceOpen ? (
          <ModalShell title="Apply template change?" onClose={() => setIsTemplateSaveChoiceOpen(false)}>
            <div className="choice-card-grid inquiry-choice-grid">
              <button type="button" onClick={() => saveTemplateChange("permanent")}><strong>Update template permanently</strong><span>This updates Setup &gt; Templates so future matching inquiries can use this version.</span></button>
              <button type="button" onClick={() => saveTemplateChange("single")}><strong>Use only for this inquiry</strong><span>This changes the message only for this buyer/client. The saved team template stays unchanged.</span></button>
            </div>
          </ModalShell>
        ) : null}

        {isCreateTemplateOpen ? (
          <ModalShell title="Create new template" onClose={() => setIsCreateTemplateOpen(false)} wide>
            <div className="inquiry-template-form-grid">
              <label>Template name<input value={newTemplateName} onChange={(event) => setNewTemplateName(event.target.value)} /></label>
              <label>Template type<input value={newTemplateType} onChange={(event) => setNewTemplateType(event.target.value)} /></label>
              <label>Channel/source<input value={newTemplateChannel} onChange={(event) => setNewTemplateChannel(event.target.value)} /></label>
              <label>Use case<input value={newTemplateUseCase} onChange={(event) => setNewTemplateUseCase(event.target.value)} /></label>
              <label className="template-editor-full">Message body<textarea rows={8} value={newTemplateBody} onChange={(event) => setNewTemplateBody(event.target.value)} /></label>
            </div>
            <div className="inquiry-modal-actions">
              <button type="button" className="primary-btn" onClick={() => createInquiryTemplate(true)}>Create and Use Template</button>
              <button type="button" className="secondary-btn" onClick={() => createInquiryTemplate(false)}>Save to Templates</button>
              <button type="button" className="secondary-btn" onClick={() => setIsCreateTemplateOpen(false)}>Cancel</button>
            </div>
          </ModalShell>
        ) : null}

        {isTemplateLibraryOpen ? (
          <ModalShell title="Template Library" onClose={() => setIsTemplateLibraryOpen(false)} wide>
            <div className="template-library-list inquiry-template-library-list">
              {templateLibraryOptions.map((template) => (
                <button key={template.name} type="button" onClick={() => { if (!selectedInquiry) return; setMessageDrafts((current) => ({ ...current, [selectedInquiry.id]: template.body })); setTemplateUsedIds((current) => ({ ...current, [selectedInquiry.id]: true })); setIsTemplateLibraryOpen(false); setDetailNotice(`${template.name} selected for this inquiry.`); setToastMessage("Template selected from the library."); recordInquiryActivity(selectedInquiry, `Template selected from library: ${template.name}`, "Template selected"); }}>
                  <strong>{template.name}</strong><span>{template.body}</span>
                </button>
              ))}
            </div>
          </ModalShell>
        ) : null}

        {isAuditOpen ? (
          <ModalShell title="Inquiry Audit Trail" onClose={() => setIsAuditOpen(false)} wide>
            <div className="inquiry-audit-modal-list">
              {selectedAudit.map((entry, index) => (
                <div className="inquiry-audit-timeline-card" key={`audit-modal-${index}`}>
                  <span>{index === 0 ? "Latest" : `Step ${index + 1}`}</span>
                  <p>{entry}</p>
                </div>
              ))}
            </div>
          </ModalShell>
        ) : null}
      </>
    );
  }

  if (!selectedInquiry) {
    return (
      <div className="recovery-page inquiry-workspace-page">
        <section className="glass-card panel-card inquiry-empty-state">
          <span className="section-eyebrow">Inquiry recovery triage</span>
          <h2>Inquiry Inbox</h2>
          <p>No inquiries have been captured for this workspace yet.</p>
        </section>
      </div>
    );
  }

  if (captureDetailMode === "full" && activeCaptureDetail) {
    return (
      <div className="recovery-page inquiry-workspace-page capture-detail-route-page">
        <CaptureDetailPage
          detail={activeCaptureDetail}
          sectionLabel="Inquiry Inbox"
          onBack={() => setCaptureDetailMode("drawer")}
          onClose={() => {
            setActiveCaptureDetail(null);
            setCaptureDetailMode(null);
          }}
        />
      </div>
    );
  }

  if (inquiryMode === "detail") {
    return (
      <div className="recovery-page inquiry-workspace-page inquiry-detail-workspace">
        {toastMessage ? (
          <div className="inquiry-toast-notice">
            <span>{toastMessage}</span>
            <button type="button" onClick={() => setToastMessage("")} aria-label="Close notice">×</button>
          </div>
        ) : null}

        <section className="inquiry-detail-page">
          <div className="inquiry-detail-topbar">
            <button className="secondary-btn" onClick={backToInquiryList} type="button">← Back to Inquiry Inbox</button>
            <div className="inquiry-status-row">
              {selectedRoutingState ? <span className={`queue-status-pill ${selectedRoutingState.kind === "routed" ? "reviewed" : "muted"}`}>{selectedRoutingState.label}</span> : null}
              {(selectedInquiry.recoveryCaseCreated || caseCreatedIds[selectedInquiry.id]) ? <span className="queue-status-pill reviewed">Recovery case created</span> : null}
              {(replySentIds[selectedInquiry.id] || selectedInquiry.firstReplyStatus === "Replied") ? <span className="queue-status-pill reviewed">First reply sent</span> : null}
              {templateUsedIds[selectedInquiry.id] ? <span className="queue-status-pill queue-ready">Template applied</span> : null}
              {(reviewedCaseIds[selectedInquiry.id] || selectedInquiry.reviewed) ? <span className="queue-status-pill reviewed">Reviewed</span> : <span className="queue-status-pill muted">Unreviewed</span>}
              {selectedQueueReady ? <span className="queue-status-pill queue-ready">Queue-ready</span> : null}
            </div>
          </div>

          <article className="glass-card panel-card inquiry-detail-card">
            <div className="inquiry-detail-hero">
              <div>
                <span className="section-eyebrow">Inquiry Recovery Detail</span>
                <h2>{selectedInquiry.customer}</h2>
                <p>{getInquiryRiskReason(selectedInquiry)}</p>
              </div>
              <div className="inquiry-detail-value-card">
                <span>Money still open</span>
                <strong>{selectedInquiry.estimatedValue}</strong>
                <small>{selectedInquiry.intentLevel} intent · {normalizeInquirySourceName(selectedInquiry.inquirySource)}</small>
              </div>
            </div>

            <div className="inquiry-detail-section-grid">
              <section className="inquiry-detail-section">
                <div className="inquiry-section-head"><span>Inquiry summary</span><strong>{selectedInquiry.timeSinceInquiry} ago</strong></div>
                <DetailField label={selectedPersonLabel} value={selectedInquiry.customer} />
                <DetailField label="Inquiry source" value={normalizeInquirySourceName(selectedInquiry.inquirySource)} />
                <DetailField label="Intent level" value={selectedInquiry.intentLevel} />
                <DetailField label="First reply status" value={selectedInquiry.firstReplyStatus} />
              </section>

              <section className="inquiry-detail-section">
                <div className="inquiry-section-head"><span>Source status</span><strong>{selectedSourceConfig?.sourceStatus ?? "Needs review"}</strong></div>
                <DetailField label="Capture source" value={selectedSourceConfig?.displayName ?? normalizeInquirySourceName(selectedInquiry.inquirySource)} />
                <DetailField label="First reply target" value={selectedSourceConfig?.firstReplyTarget ?? "2 hours"} />
                <DetailField label="Capture readiness" value={selectedSourceConfig?.requiredFieldsReadiness ?? "Needs review"} />
                <DetailField label="Review checklist" value={selectedSourceConfig?.queueReadyRule ?? "Review source readiness first."} />
              </section>

              <section className="inquiry-detail-section">
                <div className="inquiry-section-head"><span>Buyer/client context</span><strong>{selectedInquiry.recordKind ?? "product"}</strong></div>
                <DetailField label={contextLabel} value={selectedInquiry.productInterest} />
                <DetailField label="Recommended next action" value={selectedInquiry.recommendedAction} />
                <DetailField label="Last action" value={selectedInquiry.lastAction ?? "No manual update yet"} />
                <DetailField label="Team notes" value={selectedInquiry.internalNotes + selectedNotes.length} />
              </section>

              <section className="inquiry-detail-section">
                <div className="inquiry-section-head"><span>Owner / next action</span><strong>{selectedRoutingState?.label}</strong></div>
                <DetailField label="Routed owner" value={selectedRoutingState?.owner} />
                <DetailField label="Suggested owner" value={selectedSourceConfig?.defaultOwnerName ?? "Needs review"} />
                <DetailField label="Fallback owner" value={selectedSourceConfig?.fallbackOwnerRole ?? "Operations"} />
                <p className={`inquiry-routing-note ${selectedRoutingState?.kind ?? "routed"}`}>{selectedRoutingState?.helper}</p>
              </section>
            </div>

            {selectedIsService ? (
              <div className="inquiry-calendar-strip">
                <span>Appointment/deposit context</span>
                <strong>{selectedInquiry.appointmentStatus ?? "Needs confirmation"}</strong>
                <p>{selectedInquiry.appointmentDate ?? "Next available"} · {selectedInquiry.appointmentTime ?? "Time pending"} · Deposit: {selectedInquiry.depositStatus ?? "Not required"}</p>
              </div>
            ) : null}

            <div className="detail-callout inquiry-next-action-card">
              <span>Recommended next action</span>
              <p>{selectedInquiry.recommendedAction}</p>
            </div>

            <div className="template-box inquiry-template-section">
              <div className="template-section-head">
                <div>
                  <span>Message Template</span>
                  <strong>{selectedInquiry.templateStatus ?? (templateUsedIds[selectedInquiry.id] ? "Template applied" : "Needs review")}</strong>
                </div>
                {templateUsedIds[selectedInquiry.id] ? <span className="queue-status-pill queue-ready">Approved template used</span> : null}
              </div>

              <div className="template-match-grid inquiry-template-match-grid">
                <div><span>Template type</span><strong>{selectedIsService ? "Service inquiry follow-up" : "Inquiry first reply"}</strong></div>
                <div><span>Channel/source</span><strong>{normalizeInquirySourceName(selectedInquiry.inquirySource)}</strong></div>
                <div><span>Template status</span><strong>{selectedInquiry.templateStatus ?? "Needs review"}</strong></div>
                <div className="template-match-full"><span>Why this template</span><p>This template is selected from the workspace type, capture source, first-reply status, inquiry context, and current recovery risk.</p></div>
              </div>

              <div className="recommended-message-preview inquiry-message-preview">
                <span>Selected message preview</span>
                <p>{selectedMessage}</p>
              </div>

              <div className="inquiry-template-actions">
                <button type="button" onClick={() => useApprovedTemplate()}>Use Approved Template</button>
                <button type="button" onClick={openEditTemplate}>Edit Template</button>
                <button type="button" onClick={() => copyInquiryMessage()}>{copiedTemplateIds[selectedInquiry.id] ? "Message copied" : "Copy Message"}</button>
                <button type="button" onClick={openCreateTemplate}>Create new template</button>
                <button type="button" onClick={() => setIsTemplateLibraryOpen(true)}>View Templates</button>
              </div>
            </div>

            <div className="inquiry-log-grid">
              <section className="thread-panel inquiry-thread-panel">
                <div className="thread-header"><div><h3>Inquiry Recovery Log</h3><p>Source message, first reply, owner, template, recovery case, and review updates.</p></div><span>{selectedInquiry.lastAction ?? "No manual update yet"}</span></div>
                {selectedRecoveryLog.map((log, index) => (
                  <div className="thread-message" key={`${selectedInquiry.id}-recovery-log-${index}`}><div><strong>{index === 0 ? "Latest update" : "Recovery log"}</strong><span>Inquiry</span></div><p>{log}</p></div>
                ))}
                {selectedNotes.map((note, index) => (
                  <div className="thread-message internal-note-message" key={`${selectedInquiry.id}-note-${index}`}><div><strong>Team note</strong><span>Team</span></div><p>{note}</p></div>
                ))}
              </section>

              <section className="thread-panel inquiry-thread-panel audit-trail-panel">
                <div className="thread-header"><div><h3>Audit Trail</h3><p>Proof of the recovery work completed around this inquiry.</p></div><button className="secondary-btn" type="button" onClick={() => setIsAuditOpen(true)}>View Audit</button></div>
                {selectedAudit.slice(0, 5).map((entry, index) => (
                  <div className="thread-message" key={`${selectedInquiry.id}-audit-${index}`}><div><strong>{index === 0 ? "Latest" : "Audit"}</strong><span>Proof</span></div><p>{entry}</p></div>
                ))}
              </section>
            </div>

            {isInternalNoteOpen ? (
              <div className="inline-action-panel inquiry-inline-note-panel">
                <div><span>Add team note</span><p>Use this for owner context, buyer/client preferences, source issues, or handoff notes.</p></div>
                <textarea className="internal-note-textarea" value={internalNoteDraft} onChange={(event) => setInternalNoteDraft(event.target.value)} placeholder={selectedIsService ? "Example: Client asked for Saturday options and deposit link." : "Example: Buyer asked for size guidance before payment."} />
                <div className="template-action-row"><button type="button" onClick={addInternalNote}>Save Note</button><button type="button" onClick={() => setIsInternalNoteOpen(false)}>Cancel</button></div>
              </div>
            ) : null}

            {selectedIsService ? (
              <div className="calendar-action-panel inquiry-calendar-actions">
                <div><span>Calendar / appointment recovery</span><p>Use these actions when appointments, deposits, rebooking, or next-session follow-up affect recoverable revenue.</p></div>
                <div className="template-action-row wrap-actions">
                  <button type="button" onClick={() => addCalendarAction("Send appointment options")}>Send Appointment Options</button>
                  <button type="button" onClick={() => addCalendarAction("Confirm appointment")}>Confirm Appointment</button>
                  <button type="button" onClick={() => addCalendarAction("Request Deposit")}>Request Deposit</button>
                  <button type="button" onClick={() => addCalendarAction("Mark deposit paid")}>Mark Deposit Paid</button>
                  <button type="button" onClick={() => addCalendarAction("Rebook appointment")}>Rebook Appointment</button>
                  <button type="button" onClick={() => addCalendarAction("Add calendar note")}>Add Calendar Note</button>
                </div>
              </div>
            ) : null}

            <p className="detail-notice inquiry-detail-notice">{detailNotice}</p>

            <div className="detail-actions sticky-inquiry-actions">
              <button type="button" className="secondary-btn" onClick={() => markFirstReplySent()}>Mark First Reply Sent</button>
              <button type="button" className="secondary-btn" onClick={() => createRecoveryCase()}>{selectedInquiry.recoveryCaseCreated || caseCreatedIds[selectedInquiry.id] ? "Open Recovery Case" : "Create Recovery Case"}</button>
              <button type="button" className="secondary-btn" onClick={() => setIsInternalNoteOpen(true)}>Add team note</button>
              <button type="button" className="secondary-btn" onClick={() => markReviewed()}>{reviewedCaseIds[selectedInquiry.id] || selectedInquiry.reviewed ? "Reopen Review" : "Mark Reviewed"}</button>
              <button type="button" className="secondary-btn" onClick={() => setIsAuditOpen(true)}>View Audit</button>
              <button type="button" className="secondary-btn" onClick={() => onNavigate("Revenue Pipeline")}>Open Revenue Pipeline</button>
            </div>
          </article>
        </section>

        <CaptureDetailDrawer
        detail={activeCaptureDetail}
        mode={captureDetailMode}
        onClose={() => { setActiveCaptureDetail(null); setCaptureDetailMode(null); }}
        onOpenFull={() => setCaptureDetailMode("full")}
      />

      {renderTemplateModals()}
      </div>
    );
  }

  return (
    <div className="recovery-page inquiry-workspace-page">
      {toastMessage ? (
        <div className="inquiry-toast-notice">
          <span>{toastMessage}</span>
          <button type="button" onClick={() => setToastMessage("")} aria-label="Close notice">×</button>
        </div>
      ) : null}

      <section className="glass-card panel-card inquiry-hero-card">
        <div className="inquiry-hero-copy">
          <div>
            <span className="section-eyebrow">Inquiry recovery triage</span>
            <h2>Inquiry Inbox</h2>
            <p>{pageSubtitle}</p>
          </div>
          <div className="inquiry-header-pills">
            <Badge tone="amber">First reply watch</Badge>
            <Badge tone="cyan">Inquiry recovery intake</Badge>
          </div>
        </div>

        <div className="inquiry-kpi-grid capture-kpi-icon-grid">
          <article><CaptureIcon name="inbox" /><span>Total inquiries</span><strong>{inquiryRecords.length}</strong><small>{formatCompactMoney(inquirySummary.totalValue)} open value</small></article>
          <article><CaptureIcon name="reply" /><span>Need first reply</span><strong>{inquirySummary.firstReplyNeeded}</strong><small>Captured but not replied</small></article>
          <article><CaptureIcon name="owner" /><span>Need owner</span><strong>{inquirySummary.ownerMissing}</strong><small>Owner assignment review</small></article>
          <article><CaptureIcon name="check" /><span>Reviewed</span><strong>{inquirySummary.reviewed}</strong><small>Human checked</small></article>
          <article><CaptureIcon name="list" /><span>Queue-ready</span><strong>{inquirySummary.queueReady}</strong><small>Owner + case ready</small></article>
        </div>
      </section>

      <section className="capture-hero-banner inquiry-capture-banner">
        <div className="capture-hero-icon"><CaptureIcon name="message" /></div>
        <div>
          <span>Capture triage</span>
          <h3>Prioritize aging inquiries before they turn into missed revenue.</h3>
          <p>First reply, owner routing, source status, and queue readiness stay visible without changing the current workflow.</p>
        </div>
        <div className="capture-mini-metric-row">
          <span><strong>{inquirySummary.firstReplyNeeded}</strong> need first reply</span>
          <span><strong>{inquirySummary.ownerMissing}</strong> need owner</span>
          <span><strong>{inquirySummary.queueReady}</strong> queue-ready</span>
        </div>
      </section>

      <UnifiedFilterBar
        activeValue={activeSourceTab}
        ariaLabel="Inquiry source filters"
        className="capture-unified-filter inquiry-unified-filter"
        onChange={(tab) => {
          setActiveSourceTab(tab);
          setShowAllInquiries(false);
        }}
        options={sourceTabs.map((tab) => ({
          label: tab,
          count: sourceTabCount(tab),
          icon: getCaptureSourceIconName(tab),
        }))}
        totalLabel={`${filteredInquiries.length} inquiries`}
      />

      <section className="glass-card panel-card inquiry-list-page">
        <div className="panel-header inquiry-list-header">
          <div>
            <span className="section-eyebrow">Capture layer</span>
            <h2>{activeSourceTab === "All" ? "All captured inquiries" : activeSourceTab}</h2>
            <p>{filteredInquiries.length} visible inquiries in this source view.</p>
          </div>
          <span className="inquiry-list-count">{visibleInquiries.length} shown</span>
        </div>

        {visibleInquiries.length === 0 ? (
          <div className="inquiry-empty-state compact">
            <h3>No inquiries in this source view yet.</h3>
            <p>New buyer/client interest will appear here when captured.</p>
          </div>
        ) : (
          <div className="inquiry-card-list">
            {visibleInquiries.map((inquiry) => {
              const rowReviewed = Boolean(reviewedCaseIds[inquiry.id] || inquiry.reviewed);
              const rowReady = getQueueReadyState(inquiry);
              const rowIsService = Boolean(inquiry.recordKind === "service" || inquiry.appointmentDate || inquiry.calendarRisk);
              const routing = getOwnerRoutingState(inquiry);
              const sourceConfig = getSourceConfigForInquiry(inquiry);
              return (
                <article className={`inquiry-intake-card ${inquiry.tone}`} key={inquiry.id}>
                  <div className="inquiry-card-main">
                    <div className="inquiry-card-person">
                      <span className="field-label">{rowIsService ? "Client" : personLabel}</span>
                      <strong>{inquiry.customer}</strong>
                      <div className="queue-badge-row">
                        {(inquiry.inquiryBadges ?? [rowIsService ? "Service" : "Product", inquiry.intentLevel]).slice(0, 4).map((badge) => <span className="queue-mini-badge" key={`${inquiry.id}-${badge}`}>{badge}</span>)}
                      </div>
                    </div>

                    <div className="inquiry-card-source">
                      <span className="field-label">Source/channel</span>
                      <strong>{normalizeInquirySourceName(inquiry.inquirySource)}</strong>
                      <p>{inquiry.timeSinceInquiry} ago · {sourceConfig?.sourceStatus ?? "Needs review"}</p>
                    </div>

                    <div className="inquiry-card-context capture-context-cell">
                      <button type="button" className="capture-clickable-context" onClick={(event) => { event.stopPropagation(); openInquiryCaptureDetail(inquiry); }}>
                        {rowIsService ? (
                          <CaptureServiceVisual detail={buildCaptureServiceDetail(inquiry as unknown as Record<string, unknown>)} compact />
                        ) : (
                          <CaptureProductVisual detail={buildCaptureProductDetail(inquiry as unknown as Record<string, unknown>)} compact />
                        )}
                      </button>
                      <div>
                        <span className="field-label">{contextLabel}</span>
                        <button type="button" className="capture-entity-link" onClick={(event) => { event.stopPropagation(); openInquiryCaptureDetail(inquiry); }}>{inquiry.productInterest}</button>
                        <p>{inquiry.recommendedAction}</p>
                      </div>
                    </div>

                    <div className="inquiry-card-value">
                      <span className="field-label">Money still open</span>
                      <strong>{inquiry.estimatedValue}</strong>
                      <p>{inquiry.intentLevel} intent</p>
                    </div>

                    <div className="inquiry-card-status">
                      <span className={`routing-status ${routing.kind}`}>{routing.label}</span>
                      <p>{routing.owner}</p>
                      <div className="queue-action-status">
                        <span className={`queue-status-pill ${inquiry.firstReplyStatus === "Replied" || replySentIds[inquiry.id] ? "reviewed" : "muted"}`}>{replySentIds[inquiry.id] || inquiry.firstReplyStatus === "Replied" ? "First reply sent" : inquiry.firstReplyStatus}</span>
                        {rowReviewed ? <span className="queue-status-pill reviewed">Reviewed</span> : <span className="queue-status-pill muted">Unreviewed</span>}
                        {(caseCreatedIds[inquiry.id] || inquiry.recoveryCaseCreated) ? <span className="queue-status-pill reviewed">Case created</span> : null}
                        {rowReady ? <span className="queue-status-pill queue-ready">Queue-ready</span> : null}
                      </div>
                    </div>
                  </div>

                  <div className="inquiry-card-actions">
                    <button type="button" className="row-action primary-row-action" onClick={() => openInquiryDetails(inquiry)}>Show Details</button>
                    <button type="button" className="row-action" onClick={() => markFirstReplySent(inquiry)}>Mark First Reply Sent</button>
                    <button type="button" className="row-action" onClick={() => copyInquiryMessage(inquiry)}>{copiedTemplateIds[inquiry.id] ? "Message copied" : "Use / Copy message"}</button>
                    <button type="button" className="row-action" onClick={() => createRecoveryCase(inquiry)}>{caseCreatedIds[inquiry.id] || inquiry.recoveryCaseCreated ? "Open Case" : "Create Recovery Case"}</button>
                    <button type="button" className="row-action" onClick={() => markReviewed(inquiry)}>{rowReviewed ? "Reopen Review" : "Mark Reviewed"}</button>
                  </div>
                </article>
              );
            })}
          </div>
        )}

        {hiddenInquiryCount > 0 ? (
          <button type="button" className="secondary-btn load-more-btn" onClick={() => setShowAllInquiries(true)}>
            Show {hiddenInquiryCount} more inquiries
          </button>
        ) : null}
      </section>

      <CaptureDetailDrawer
        detail={activeCaptureDetail}
        mode={captureDetailMode}
        onClose={() => { setActiveCaptureDetail(null); setCaptureDetailMode(null); }}
        onOpenFull={() => setCaptureDetailMode("full")}
      />

      {renderTemplateModals()}
    </div>
  );
}

function ProductDemand({
  onActivity,
  onNavigate,
}: {
  onActivity: (activity: NewRecoveryActivity) => void;
  onNavigate: (page: string) => void;
}) {
  const workspaceProfile = useMemo(() => getWorkspaceProfile(), []);
  const demandConfig = useMemo(() => getDemandPageConfig(workspaceProfile), [workspaceProfile]);
  const baseDemandRecords = useMemo(() => getDemandRecords(workspaceProfile), [workspaceProfile]);
  const [demandSignals, setDemandSignals] = useState<ProductDemandSignal[]>(baseDemandRecords);
  const [activeDemandFilter, setActiveDemandFilter] = useState("All");
  const [currentDemandPage, setCurrentDemandPage] = useState(1);
  const [notice, setNotice] = useState(`${demandConfig.title} is ready for recovery review.`);
  const [activeDemandDetailId, setActiveDemandDetailId] = useState<string | null>(null);
  const [activeDemandInsight, setActiveDemandInsight] = useState<"signals" | "actions" | null>(null);
  const [activeCaptureDetail, setActiveCaptureDetail] = useState<CaptureDetailRecord | null>(null);
  const [captureDetailMode, setCaptureDetailMode] = useState<"drawer" | "full" | null>(null);

  useEffect(() => {
    setDemandSignals(baseDemandRecords);
    setActiveDemandFilter("All");
    setCurrentDemandPage(1);
    setNotice(`${demandConfig.title} is ready for recovery review.`);
    setActiveDemandDetailId(null);
    setActiveDemandInsight(null);
  }, [baseDemandRecords, demandConfig.title]);

  useEffect(() => {
    function handleGuideClosePanels() {
      setActiveDemandDetailId(null);
      setActiveDemandInsight(null);
    }

    window.addEventListener("altynx:product-demand-guide-close-panels", handleGuideClosePanels);

    return () => {
      window.removeEventListener("altynx:product-demand-guide-close-panels", handleGuideClosePanels);
    };
  }, []);

  const demandFilters = demandConfig.filters;
  const entriesPerPage = 25;

  const filteredDemand = useMemo(
    () => demandSignals.filter((signal) => demandMatchesFilter(signal, activeDemandFilter)),
    [activeDemandFilter, demandSignals],
  );

  const demandKpis = useMemo(() => getDemandKpis(demandConfig, demandSignals), [demandConfig, demandSignals]);
  const totalDemandPages = Math.max(1, Math.ceil(filteredDemand.length / entriesPerPage));
  const paginatedDemand = filteredDemand.slice((currentDemandPage - 1) * entriesPerPage, currentDemandPage * entriesPerPage);
  const activeDemandDetail = demandSignals.find((signal) => signal.id === activeDemandDetailId) ?? null;

  function resetFilter(filter: string) {
    setActiveDemandFilter(filter);
    setCurrentDemandPage(1);
    setActiveDemandDetailId(null);
    setActiveDemandInsight(null);
  }

  function isServiceDemand(signal: ProductDemandSignal) {
    return (
      signal.recordKind === "service" ||
      Boolean(signal.serviceType) ||
      Boolean(signal.appointmentStatus) ||
      Boolean(signal.depositStatus) ||
      Boolean(signal.calendarRisk) ||
      Boolean(signal.nextCalendarAction)
    );
  }

  function appendDemandAudit(signalId: string, entry: string, changes: Partial<ProductDemandSignal> = {}) {
    setDemandSignals((signals) =>
      signals.map((signal) =>
        signal.id === signalId
          ? {
              ...signal,
              ...changes,
              auditTrail: [entry, ...(signal.auditTrail ?? [])],
            }
          : signal,
      ),
    );
  }

  function recordDemandActivity(signal: ProductDemandSignal, title: string, status: string, nextAction = signal.recommendedNextAction) {
    onActivity({
      category: isServiceDemand(signal)
        ? "Team Actions"
        : signal.demandType === "Restock" || signal.demandType === "Reorder" || signal.demandType === "Refill"
          ? "Repeat Revenue"
          : "Inquiries",
      title,
      description: `${signal.demandName} was updated with ${signal.totalSignals} captured demand signals.`,
      impactBadge: `${signal.estimatedDemandValue} demand value`,
      relatedRecord: `${demandConfig.title} - ${signal.id}`,
      owner: signal.owner === "Unassigned" ? undefined : signal.owner,
      status,
      nextAction,
      tone: signal.tone,
    });
  }

  function openDemandDetail(signal: ProductDemandSignal) {
    setActiveDemandDetailId(signal.id);
    setActiveDemandInsight(null);
  }

  function createDemandTasks(signal: ProductDemandSignal) {
    appendDemandAudit(signal.id, "Recovery tasks prepared from captured demand signals.", {
      recoveryTasksCreated: true,
      openRecoveryActions: Math.max(signal.openRecoveryActions, 1),
      lastAction: "Recovery tasks prepared",
      queueReady: Boolean(signal.queueReady || (signal.reviewed && signal.owner !== "Unassigned")),
    });

    setNotice(`${signal.demandName}: recovery tasks prepared.`);
    recordDemandActivity(signal, "Recovery tasks prepared", "Prepared", signal.recommendedNextAction);
  }

  function addDemandToQueue(signal: ProductDemandSignal) {
    const serviceDemand = isServiceDemand(signal);

    appendDemandAudit(
      signal.id,
      serviceDemand
        ? "Calendar follow-up prepared from service demand signals."
        : "Restock/reorder queue prepared from product demand signals.",
      serviceDemand
        ? {
            queueReady: Boolean(signal.reviewed || signal.owner !== "Unassigned"),
            nextCalendarAction: signal.nextCalendarAction ?? "Calendar follow-up prepared.",
            lastAction: "Calendar follow-up prepared",
          }
        : {
            restockQueue: true,
            queueReady: Boolean(signal.reviewed || signal.owner !== "Unassigned"),
            lastAction: "Added to restock/reorder queue",
          },
    );

    setNotice(
      serviceDemand
        ? `${signal.demandName}: calendar follow-up prepared.`
        : `${signal.demandName}: added to restock/reorder queue.`,
    );

    recordDemandActivity(
      signal,
      serviceDemand ? "Calendar follow-up prepared" : "Restock/reorder queue prepared",
      serviceDemand ? "Calendar follow-up" : "Queued",
      serviceDemand ? signal.nextCalendarAction ?? signal.recommendedNextAction : signal.recommendedNextAction,
    );
  }

  function markDemandReviewed(signal: ProductDemandSignal) {
    const nextReviewed = !signal.reviewed;

    appendDemandAudit(signal.id, nextReviewed ? "Demand group reviewed for recovery action." : "Demand review reopened.", {
      reviewed: nextReviewed,
      lastAction: nextReviewed ? "Reviewed" : "Review reopened",
      queueReady: nextReviewed && signal.owner !== "Unassigned" && Boolean(signal.recommendedNextAction),
    });

    setNotice(nextReviewed ? `${signal.demandName}: reviewed for recovery action.` : `${signal.demandName}: review reopened.`);
    recordDemandActivity(signal, nextReviewed ? "Demand group reviewed" : "Demand review reopened", nextReviewed ? "Reviewed" : "Open");
  }

  function demandStatusText(signal: ProductDemandSignal) {
    if (signal.queueReady) return "Queue-ready";
    if (signal.restockQueue) return "Restock/reorder queued";
    if (signal.reviewed) return "Reviewed";
    if (signal.recoveryTasksCreated) return "Tasks prepared";
    if (!signal.owner || signal.owner === "Unassigned") return "Needs setup review";
    return isServiceDemand(signal) ? "Calendar follow-up needed" : "Needs follow-up";
  }

  function cardQueueLabel(signal: ProductDemandSignal) {
    if (isServiceDemand(signal)) return signal.queueReady ? "Calendar follow-up ready" : "Add to Calendar Follow-up";
    return signal.restockQueue || signal.queueReady ? "Restock/reorder queued" : "Add to Restock/Reorder Queue";
  }

  function getDemandExampleName(signal: ProductDemandSignal, index: number) {
    const productNames = ["Avery Brooks", "Chloe Hayes", "Nadia Brooks", "Maya Chen", "Priya Nair", "Imani Wallace"];
    const serviceNames = ["Sophia Bennett", "Talia Monroe", "Camila Torres", "Jasmine Reed", "Elena Rodriguez", "Arielle Stone"];
    const names = isServiceDemand(signal) ? serviceNames : productNames;
    return names[index % names.length];
  }

  function getDemandSignalRows(signal: ProductDemandSignal) {
    const sources = signal.sourceMix.length > 0 ? signal.sourceMix : ["Captured source"];
    const totalSignals = Math.max(signal.totalSignals, sources.length);
    const totalValue = moneyToNumber(signal.estimatedDemandValue);
    const baseCount = Math.floor(totalSignals / sources.length);
    const remainder = totalSignals % sources.length;

    return sources.map((source, index) => {
      const signalCount = Math.max(1, baseCount + (index < remainder ? 1 : 0));
      const valueShare = totalSignals > 0 ? Math.round((totalValue / totalSignals) * signalCount) : 0;
      const highIntent = index < Math.min(signal.highIntentCount, sources.length);
      const productContext =
        signal.demandType === "Restock" || signal.demandType === "Reorder" || signal.demandType === "Refill"
          ? "Restock or reorder interest captured"
          : signal.demandType === "Payment"
            ? "Payment or checkout follow-up signal"
            : signal.demandType === "Appointment" || signal.demandType === "Deposit" || signal.demandType === "Rebooking"
              ? signal.serviceType ?? "Appointment or client follow-up signal"
              : signal.stockStatus;

      return {
        id: `${signal.id}-signal-${index}`,
        source,
        signalCount,
        buyerName: getDemandExampleName(signal, index),
        signalType: signal.demandType,
        context: productContext,
        value: valueShare > 0 ? formatCompactMoney(valueShare) : signal.estimatedDemandValue,
        intent: highIntent ? "High intent" : "Needs review",
        captured: index === 0 ? "Latest capture" : index === 1 ? "Today" : "This week",
        status: signal.reviewed ? "Reviewed" : signal.recoveryTasksCreated ? "Tasks prepared" : "Needs follow-up",
      };
    });
  }

  function getDemandActionRows(signal: ProductDemandSignal) {
    const actionCount = Math.max(1, signal.openRecoveryActions);
    const totalValue = moneyToNumber(signal.estimatedDemandValue);
    const serviceDemand = isServiceDemand(signal);
    const actionTemplates = serviceDemand
      ? [
          { title: "Confirm appointment or deposit", destination: "Today’s Recovery Queue", status: signal.queueReady ? "Queue-ready" : "Needs review" },
          { title: "Prepare calendar follow-up", destination: "Calendar Follow-up", status: signal.nextCalendarAction ? "Prepared" : "Open" },
          { title: "Send rebooking or package follow-up", destination: "Follow-up Recovery", status: signal.reviewed ? "Reviewed" : "Open" },
          { title: "Review client follow-up risk", destination: "Revenue Pipeline", status: signal.owner === "Unassigned" ? "Needs setup review" : "Open" },
        ]
      : [
          { title: "Send product guidance", destination: "Today’s Recovery Queue", status: signal.recoveryTasksCreated ? "Prepared" : "Open" },
          { title: "Prepare restock/reorder follow-up", destination: "Restock Waitlist", status: signal.restockQueue ? "Queued" : "Open" },
          { title: "Create payment or checkout follow-up", destination: "Revenue Pipeline", status: signal.queueReady ? "Queue-ready" : "Needs review" },
          { title: "Review high-intent demand group", destination: "Today’s Recovery Queue", status: signal.reviewed ? "Reviewed" : "Open" },
        ];

    const visibleTemplates = actionTemplates.slice(0, Math.min(actionTemplates.length, Math.max(1, actionCount)));
    const baseCount = Math.floor(actionCount / visibleTemplates.length);
    const remainder = actionCount % visibleTemplates.length;

    return visibleTemplates.map((action, index) => {
      const groupedActions = Math.max(1, baseCount + (index < remainder ? 1 : 0));
      const valueShare = actionCount > 0 ? Math.round((totalValue / actionCount) * groupedActions) : 0;

      return {
        id: `${signal.id}-action-${index}`,
        title: action.title,
        destination: action.destination,
        groupedActions,
        owner: signal.owner === "Unassigned" ? "Needs setup review" : signal.owner,
        due: index === 0 ? "Due today" : index === 1 ? "Due soon" : "Monitoring",
        status: action.status,
        value: valueShare > 0 ? formatCompactMoney(valueShare) : signal.estimatedDemandValue,
        relatedSignal: `${signal.demandType} · ${signal.sourceMix[index % Math.max(1, signal.sourceMix.length)] ?? "Captured source"}`,
      };
    });
  }

  function openPreparedQueue(signal: ProductDemandSignal) {
    onNavigate(isServiceDemand(signal) ? "Today's Recovery Queue" : "Restock Waitlist");
  }

  function openDemandCaptureDetail(signal: ProductDemandSignal) {
    const detail = isServiceDemand(signal)
      ? buildCaptureServiceDetail(signal as unknown as Record<string, unknown>)
      : buildCaptureProductDetail(signal as unknown as Record<string, unknown>);
    setActiveCaptureDetail(detail);
    setCaptureDetailMode("drawer");
  }


  if (captureDetailMode === "full" && activeCaptureDetail) {
    return (
      <div className="recovery-page demand-intelligence-page capture-detail-route-page">
        <CaptureDetailPage
          detail={activeCaptureDetail}
          sectionLabel="Product & Drop Demand"
          onBack={() => setCaptureDetailMode("drawer")}
          onClose={() => {
            setActiveCaptureDetail(null);
            setCaptureDetailMode(null);
          }}
        />
      </div>
    );
  }

  return (
    <div className="recovery-page demand-intelligence-page">
      <section className="recovery-kpi-grid capture-kpi-grid">
        {demandKpis.map((item) => (
          <KpiCard key={item.label} item={item} />
        ))}
      </section>

      <section className="capture-hero-banner demand-capture-banner">
        <div className="capture-hero-icon"><CaptureIcon name="package" /></div>
        <div>
          <span>{demandConfig.badge}</span>
          <h3>See demand signals before they turn into missed revenue.</h3>
          <p>Size/fit, drops, restock, custom orders, appointments, and payment signals stay grouped for owner review.</p>
        </div>
        <div className="capture-mini-metric-row">
          <span><strong>{filteredDemand.length}</strong> groups</span>
          <span><strong>{demandSignals.reduce((total, signal) => total + signal.highIntentCount, 0)}</strong> high-intent</span>
          <span><strong>{demandSignals.reduce((total, signal) => total + signal.openRecoveryActions, 0)}</strong> open actions</span>
        </div>
      </section>

      <UnifiedFilterBar
        activeValue={activeDemandFilter}
        ariaLabel={`${demandConfig.title} filters`}
        className="capture-unified-filter demand-unified-filter"
        onChange={(filter) => resetFilter(filter)}
        options={demandFilters.map((filter) => ({
          label: filter,
          count: demandSignals.filter((signal) => demandMatchesFilter(signal, filter)).length,
          icon: getDemandTypeIconName(filter),
        }))}
        totalLabel={`${filteredDemand.length} ${demandConfig.countLabel}`}
      />

      <section className="glass-card panel-card demand-page-panel">
        <div className="panel-header demand-panel-header">
          <div>
            <span className="section-eyebrow">{demandConfig.badge}</span>
            <h2>{demandConfig.title}</h2>
            <p>{demandConfig.subtitle}</p>
          </div>
          <Badge tone={demandConfig.mode === "service" ? "amber" : demandConfig.mode === "hybrid" ? "indigo" : "emerald"}>
            {filteredDemand.length} {demandConfig.countLabel}
          </Badge>
        </div>

        {paginatedDemand.length ? (
          <div className="capture-card-list demand-card-list">
            {paginatedDemand.map((signal) => {
              const serviceDemand = isServiceDemand(signal);
              return (
                <article className={`demand-card ${signal.tone}`} key={signal.id}>
                  <div className="capture-card-main demand-card-main capture-card-main-visual">
                    <button type="button" className="capture-clickable-context demand-visual-trigger" onClick={(event) => { event.stopPropagation(); openDemandCaptureDetail(signal); }}>
                      {serviceDemand ? (
                        <CaptureServiceVisual detail={buildCaptureServiceDetail(signal as unknown as Record<string, unknown>)} compact />
                      ) : (
                        <CaptureProductVisual detail={buildCaptureProductDetail(signal as unknown as Record<string, unknown>)} compact />
                      )}
                    </button>
                    <div>
                      <div className="recovery-row-title demand-title-row">
                        <CaptureIcon name={getDemandTypeIconName(signal.demandType)} className="capture-title-icon" />
                        <button type="button" className="capture-entity-link" onClick={(event) => { event.stopPropagation(); openDemandCaptureDetail(signal); }}>{signal.demandName}</button>
                        <span className={`queue-status-pill ${serviceDemand ? "calendar" : ""}`}>
                          {serviceDemand ? "Service" : signal.recordKind === "hybrid" ? "Hybrid" : "Product"}
                        </span>
                        {(signal.demandBadges ?? [signal.demandType]).slice(0, 3).map((badge) => (
                          <span className="queue-status-pill" key={`${signal.id}-${badge}`}>{badge}</span>
                        ))}
                        {signal.recoveryTasksCreated ? <span className="queue-status-pill">Tasks prepared</span> : null}
                        {signal.restockQueue ? <span className="queue-status-pill queue-ready">Queued</span> : null}
                        {signal.reviewed ? <span className="queue-status-pill reviewed">Reviewed</span> : null}
                        {signal.queueReady ? <span className="queue-status-pill queue-ready">Queue-ready</span> : null}
                      </div>
                      <p>{signal.recommendedNextAction}</p>
                      <div className="recovery-meta demand-meta">
                        <span>{signal.sourceMix.join(" + ")}</span>
                        <span>{signal.estimatedDemandValue}</span>
                        <span>{signal.owner === "Unassigned" ? "Needs setup review" : signal.owner}</span>
                      </div>
                    </div>
                  </div>

                  <div className="capture-stat-grid demand-stat-grid">
                    <div><span>Total signals</span><strong>{signal.totalSignals}</strong></div>
                    <div><span>High intent</span><strong>{signal.highIntentCount}</strong></div>
                    <div><span>Open actions</span><strong>{signal.openRecoveryActions}</strong></div>
                    <div><span>Status</span><strong>{demandStatusText(signal)}</strong></div>
                    {serviceDemand ? <div><span>Appointment</span><strong>{signal.appointmentStatus ?? "Follow-up due"}</strong></div> : null}
                    {serviceDemand ? <div><span>Deposit</span><strong>{signal.depositStatus ?? "Not required"}</strong></div> : null}
                    {serviceDemand ? <div><span>Calendar risk</span><strong>{signal.calendarRisk ?? "Follow-up due"}</strong></div> : null}
                    {serviceDemand ? <div><span>Next slot</span><strong>{signal.nextAvailableSlot ?? "To confirm"}</strong></div> : null}
                  </div>

                  <div className="demand-next-action-box">
                    <span>{serviceDemand ? "Next appointment / revenue action" : "Next demand recovery action"}</span>
                    <p>{serviceDemand ? signal.nextCalendarAction ?? signal.recommendedNextAction : signal.recommendedNextAction}</p>
                  </div>

                  <div className="capture-actions demand-actions-row">
                    <button
                      type="button"
                      className="primary-btn"

                      onClick={() => openDemandDetail(signal)}
                    >
                      View More
                    </button>
                    <button
                      type="button"
                      className="secondary-btn"

                      onClick={() => createDemandTasks(signal)}
                    >
                      {signal.recoveryTasksCreated ? "Tasks prepared" : "Create Follow-up Drafts"}
                    </button>
                    <button
                      type="button"
                      className="secondary-btn"

                      onClick={() => addDemandToQueue(signal)}
                    >
                      {cardQueueLabel(signal)}
                    </button>
                    <button
                      type="button"
                      className="secondary-btn"

                      onClick={() => markDemandReviewed(signal)}
                    >
                      {signal.reviewed ? "Reviewed ✓" : "Mark Reviewed"}
                    </button>
                  </div>

                  <div className="audit-mini-list">
                    {(signal.auditTrail ?? [`${signal.demandName} captured as demand recovery signal.`]).slice(0, 2).map((entry, index) => (
                      <p key={`${signal.id}-audit-${index}`}>
                        <strong>{index === 0 ? "Latest audit" : "Audit"}:</strong> {entry}
                      </p>
                    ))}
                  </div>
                </article>
              );
            })}
          </div>
        ) : (
          <div className="empty-state-card">
            <h3>No demand groups match this filter.</h3>
            <p>Switch back to All or review the workspace demand fallback records.</p>
          </div>
        )}

        {filteredDemand.length > entriesPerPage ? (
          <div className="pagination-row demand-pagination">
            <button type="button" className="secondary-btn" disabled={currentDemandPage <= 1} onClick={() => setCurrentDemandPage((page) => Math.max(1, page - 1))}>Previous</button>
            <span>Page {currentDemandPage} of {totalDemandPages}</span>
            <button type="button" className="secondary-btn" disabled={currentDemandPage >= totalDemandPages} onClick={() => setCurrentDemandPage((page) => Math.min(totalDemandPages, page + 1))}>Next</button>
          </div>
        ) : null}

        <p className="detail-notice capture-page-notice">{notice}</p>
      </section>

      <CaptureDetailDrawer
        detail={activeCaptureDetail}
        mode={captureDetailMode}
        onClose={() => { setActiveCaptureDetail(null); setCaptureDetailMode(null); }}
        onOpenFull={() => setCaptureDetailMode("full")}
      />

      {activeDemandDetail ? (
        <ModalShell title="Demand Details" onClose={() => { setActiveDemandDetailId(null); setActiveDemandInsight(null); }} wide>
          <div className="demand-detail-modal">
            <div className="customer-summary-box demand-detail-summary capture-modal-summary">
              <div className="capture-modal-summary-icon"><CaptureIcon name={getDemandTypeIconName(activeDemandDetail.demandType)} /></div>
              <div>
                <span>{isServiceDemand(activeDemandDetail) ? "Service demand" : "Product demand"}</span>
                <h3>{activeDemandDetail.demandName}</h3>
                <p>{activeDemandDetail.recommendedNextAction}</p>
              </div>
              <button type="button" className="secondary-btn" onClick={(event) => { event.stopPropagation(); openDemandCaptureDetail(activeDemandDetail); }}>
                Open {isServiceDemand(activeDemandDetail) ? "Service Detail" : "Product Detail"}
              </button>
            </div>

            <button type="button" className="capture-detail-entry-card" onClick={(event) => { event.stopPropagation(); openDemandCaptureDetail(activeDemandDetail); }}>
              {isServiceDemand(activeDemandDetail) ? (
                <CaptureServiceVisual detail={buildCaptureServiceDetail(activeDemandDetail as unknown as Record<string, unknown>)} />
              ) : (
                <CaptureProductVisual detail={buildCaptureProductDetail(activeDemandDetail as unknown as Record<string, unknown>)} />
              )}
              <span>Open {isServiceDemand(activeDemandDetail) ? "Service Detail" : "Product Detail"}</span>
            </button>

            <div className="detail-grid demand-detail-grid">
              <div><span>Demand type</span><strong>{activeDemandDetail.demandType}</strong></div>
              <div><span>Source mix</span><strong>{activeDemandDetail.sourceMix.join(" + ")}</strong></div>
              <div className="demand-insight-metric">
                <span>Total signals</span>
                <strong>{activeDemandDetail.totalSignals}</strong>
                <button type="button" onClick={() => setActiveDemandInsight(activeDemandInsight === "signals" ? null : "signals")}>
                  {activeDemandInsight === "signals" ? "Hide signals" : "See signals"}
                </button>
              </div>
              <div className="demand-insight-metric">
                <span>High-intent signals</span>
                <strong>{activeDemandDetail.highIntentCount}</strong>
                <button type="button" onClick={() => setActiveDemandInsight(activeDemandInsight === "signals" ? null : "signals")}>
                  {activeDemandInsight === "signals" ? "Hide signals" : "See signals"}
                </button>
              </div>
              <div><span>Estimated value</span><strong>{activeDemandDetail.estimatedDemandValue}</strong></div>
              <div><span>Owner / routing</span><strong>{activeDemandDetail.owner === "Unassigned" ? "Needs setup review" : activeDemandDetail.owner}</strong></div>
              <div><span>Status</span><strong>{demandStatusText(activeDemandDetail)}</strong></div>
              <div className="demand-insight-metric">
                <span>Open recovery actions</span>
                <strong>{activeDemandDetail.openRecoveryActions}</strong>
                <button type="button" onClick={() => setActiveDemandInsight(activeDemandInsight === "actions" ? null : "actions")}>
                  {activeDemandInsight === "actions" ? "Hide actions" : "See actions"}
                </button>
              </div>
            </div>

            {activeDemandInsight === "signals" ? (
              <div className="demand-insight-panel">
                <div className="thread-header">
                  <div>
                    <h3>Captured demand signals</h3>
                    <p>Grouped source signals behind the total count, so the owner can see where the demand came from.</p>
                  </div>
                  <span className="queue-status-pill queue-ready">{activeDemandDetail.totalSignals} total</span>
                </div>

                <div className="demand-insight-list">
                  {getDemandSignalRows(activeDemandDetail).map((row) => (
                    <article className="demand-insight-row" key={row.id}>
                      <div>
                        <span>Source</span>
                        <strong>{row.source}</strong>
                        <small>{row.signalCount} signals · {row.captured}</small>
                      </div>
                      <div>
                        <span>Buyer / context</span>
                        <strong>{row.buyerName}</strong>
                        <small>{row.context}</small>
                      </div>
                      <div>
                        <span>Signal type</span>
                        <strong>{row.signalType}</strong>
                        <small>{row.intent}</small>
                      </div>
                      <div>
                        <span>Value / status</span>
                        <strong>{row.value}</strong>
                        <small>{row.status}</small>
                      </div>
                    </article>
                  ))}
                </div>
              </div>
            ) : null}

            {activeDemandInsight === "actions" ? (
              <div className="demand-insight-panel">
                <div className="thread-header">
                  <div>
                    <h3>Open recovery actions</h3>
                    <p>Prepared work connected to this demand group. These actions are not sent automatically.</p>
                  </div>
                  <span className="queue-status-pill queue-ready">{activeDemandDetail.openRecoveryActions} open</span>
                </div>

                <div className="demand-insight-list action-insight-list">
                  {getDemandActionRows(activeDemandDetail).map((row) => (
                    <article className="demand-insight-row action-insight-row" key={row.id}>
                      <div>
                        <span>Action</span>
                        <strong>{row.title}</strong>
                        <small>{row.groupedActions} grouped action{row.groupedActions === 1 ? "" : "s"}</small>
                      </div>
                      <div>
                        <span>Destination</span>
                        <strong>{row.destination}</strong>
                        <small>{row.relatedSignal}</small>
                      </div>
                      <div>
                        <span>Owner / due</span>
                        <strong>{row.owner}</strong>
                        <small>{row.due}</small>
                      </div>
                      <div>
                        <span>Value / status</span>
                        <strong>{row.value}</strong>
                        <small>{row.status}</small>
                      </div>
                    </article>
                  ))}
                </div>
              </div>
            ) : null}

            <div className="demand-context-grid">
              <div className="thread-panel">
                <div className="thread-header">
                  <div>
                    <h3>{isServiceDemand(activeDemandDetail) ? "Appointment / service context" : "Product / demand context"}</h3>
                    <p>
                      {isServiceDemand(activeDemandDetail)
                        ? "Service demand details used for appointment, deposit, rebooking, or calendar follow-up."
                        : "Product demand details used for restock, reorder, product question, or payment follow-up."}
                    </p>
                  </div>
                </div>

                <div className="detail-grid">
                  {isServiceDemand(activeDemandDetail) ? (
                    <>
                      <div><span>Service type</span><strong>{activeDemandDetail.serviceType ?? "Service follow-up"}</strong></div>
                      <div><span>Appointment status</span><strong>{activeDemandDetail.appointmentStatus ?? "Follow-up due"}</strong></div>
                      <div><span>Deposit status</span><strong>{activeDemandDetail.depositStatus ?? "Not required"}</strong></div>
                      <div><span>Next available slot</span><strong>{activeDemandDetail.nextAvailableSlot ?? "To confirm"}</strong></div>
                      <div><span>Calendar risk</span><strong>{activeDemandDetail.calendarRisk ?? "Follow-up due"}</strong></div>
                      <div><span>Next calendar action</span><strong>{activeDemandDetail.nextCalendarAction ?? activeDemandDetail.recommendedNextAction}</strong></div>
                    </>
                  ) : (
                    <>
                      <div><span>Product context</span><strong>{activeDemandDetail.industryType}</strong></div>
                      <div><span>Stock / recovery status</span><strong>{activeDemandDetail.stockStatus}</strong></div>
                      <div><span>Demand badges</span><strong>{(activeDemandDetail.demandBadges ?? [activeDemandDetail.demandType]).join(", ")}</strong></div>
                      <div><span>Queue status</span><strong>{activeDemandDetail.restockQueue ? "Restock/reorder queued" : "Not queued yet"}</strong></div>
                    </>
                  )}
                </div>
              </div>

              <div className="thread-panel audit-trail-panel">
                <div className="thread-header">
                  <div>
                    <h3>Source capture / audit log</h3>
                    <p>Proof of the demand recovery work prepared from this group.</p>
                  </div>
                </div>

                {(activeDemandDetail.auditTrail ?? [`${activeDemandDetail.demandName} captured as demand recovery signal.`]).map((entry, index) => (
                  <div className="thread-message" key={`${activeDemandDetail.id}-detail-audit-${index}`}>
                    <div>
                      <strong>{index === 0 ? "Latest" : `Step ${index + 1}`}</strong>
                      <span>Audit</span>
                    </div>
                    <p>{entry}</p>
                  </div>
                ))}
              </div>
            </div>

            <div className="template-action-row demand-detail-actions">
              <button type="button" onClick={() => createDemandTasks(activeDemandDetail)}>
                {activeDemandDetail.recoveryTasksCreated ? "Tasks prepared" : "Create Follow-up Drafts"}
              </button>
              <button type="button" onClick={() => addDemandToQueue(activeDemandDetail)}>
                {isServiceDemand(activeDemandDetail) ? "Add to Calendar Follow-up" : "Add to Restock/Reorder Queue"}
              </button>
              <button type="button" onClick={() => markDemandReviewed(activeDemandDetail)}>
                {activeDemandDetail.reviewed ? "Reviewed ✓" : "Mark Reviewed"}
              </button>
              <button type="button" onClick={() => openPreparedQueue(activeDemandDetail)}>
                Open Prepared Queue
              </button>
              <button type="button" onClick={() => { setActiveDemandDetailId(null); setActiveDemandInsight(null); }}>
                Close
              </button>
            </div>
          </div>
        </ModalShell>
      ) : null}
    </div>
  );
}

