function makeSourceLeakDetailEntry(
  id: string,
  entryType: SourceLeakDetailEntry["entryType"],
  buyerName: string,
  productContext: string,
  value: string,
  owner: string,
  status: string,
  lastSignal: string,
  nextAction: string,
  tone: Tone,
  extra: Partial<SourceLeakDetailEntry> = {},
): SourceLeakDetailEntry {
  return {
    id,
    entryType,
    buyerName,
    productContext,
    value,
    owner,
    status,
    lastSignal,
    nextAction,
    confidence: extra.confidence ?? "High",
    tone,
    ...extra,
  };
}

function makeSourceLeakRecord(
  record: SourceLeakRecord,
  entries: SourceLeakDetailEntry[],
): SourceLeakRecord {
  const actionableSignalCount =
    record.actionableSignalCount ??
    record.highIntentInquiries + record.firstRepliesMissing + record.unassignedRecords + record.overdueFollowUps;

  const sourceHealthStatus =
    record.sourceHealthStatus ??
    (record.unassignedRecords > 0
      ? "Owner gap"
      : record.syncIssues > 0
        ? "Source review needed"
        : record.firstRepliesMissing > 0 || moneyToNumber(record.paymentPendingValue) > 0
          ? "Needs action"
          : "Strong source");

  return {
    sourceHealthStatus,
    sourceHealthReason: record.sourceHealthReason ?? record.sourceQuality,
    routingStatus: record.routingStatus ?? (record.unassignedRecords > 0 ? "Missing owner" : "Healthy"),
    recoverableValue: record.recoverableValue ?? record.paymentPendingValue,
    preparedQueueStatus: record.preparedQueueStatus ?? "Not prepared",
    reviewStatus: record.reviewStatus ?? (record.reviewed ? "Reviewed" : "Open"),
    auditTrail: record.auditTrail ?? ["Source captured and classified for recovery review."],
    actionableSignalCount,
    detailEntries: entries,
    ...record,
  };
}

