    <button type="button" className={`revenue-filter-chip ${active ? "is-active" : ""}`} onClick={onClick}>
      <CaptureIcon name={getRevenueFilterIconName(label)} />
      <span>{label}</span>
      <strong>{count}</strong>
    </button>
