function ReportsValueCard({ label, value, caption, tone = "cyan" }: { label: string; value: string; caption: string; tone?: Tone }) {
  return (
    <article className={`automation-value-card ${tone}`}>
      <span>{label}</span>
      <strong>{value}</strong>
      <small>{caption}</small>
    </article>
  );
}

function ReportsStatusBanner({ eyebrow, title, children }: { eyebrow: string; title: string; children: ReactNode }) {
  return (
    <section className="automation-status-banner">
      <div>
        <span>{eyebrow}</span>
        <h3>{title}</h3>
        <p>{children}</p>
      </div>
      <i />
    </section>
  );
}

function ReportsFilterRow({ filters, active, onChange, countLabel }: { filters: string[]; active: string; onChange: (filter: string) => void; countLabel: string }) {
  return (
    <section className="reports-filter-card" data-workflow-ignore="true">
      <div className="reports-filter-pills">
        {filters.map((filter) => (
          <button
            key={filter}
            type="button"
            className={active === filter ? "active" : ""}
            onClick={() => onChange(filter)}
          >
            {filter}
          </button>
        ))}
      </div>
      <span className="reports-count-pill">{countLabel}</span>
    </section>
  );
}

function ReportsPagination({ total, label = "records" }: { total: number; label?: string }) {
  return (
    <div className="reports-pagination">
      <span>Showing {total > 0 ? 1 : 0}–{Math.min(25, total)} of {total} {label}</span>
      <strong>25 per page</strong>
      <div>
        <button className="secondary-btn" type="button" disabled>Previous</button>
        <em>Page 1 / 1</em>
        <button className="secondary-btn" type="button" disabled>Next</button>
      </div>
    </div>
  );
}

function AutomationKanbanCard({ card, onOpen, onMove }: { card: ReportsAutomationCard; onOpen: (card: ReportsAutomationCard) => void; onMove?: (card: ReportsAutomationCard) => void }) {
  return (
    <article className={`automation-kanban-card ${card.tone}`}>
      <div className="automation-kanban-card-top">
        <span className={`reports-line-icon ${card.tone}`} />
        <div>
          <strong>{card.title}</strong>
          <small>{card.source} · {card.channel}</small>
        </div>
        <Badge tone={reportPriorityTone[card.priority]}>{card.priority}</Badge>
      </div>
      <p>{card.context ?? card.sourceType}</p>
      <div className="reports-chip-row">
        <span>{card.status}</span>
        <span>{card.owner}</span>
        <span>{card.relatedPage}</span>
        {card.signalCount ? <span>{card.signalCount}</span> : null}
      </div>
      <div className="automation-kanban-card-value">
        <span>Money still open</span>
        <strong>{card.moneyOpen}</strong>
        <small>{card.recovered ? `Recovered ${card.recovered}` : card.n8nStatus ?? "Frontend-ready"}</small>
      </div>
      <div className="reports-next-action">
        <span>Next step</span>
        <p>{card.nextStep}</p>
      </div>
      <div className="reports-card-actions">
        <button className="primary-btn" type="button" onClick={() => onOpen(card)}>Open details</button>
        {onMove ? <button className="secondary-btn" type="button" onClick={() => onMove(card)}>Move stage</button> : null}
      </div>
    </article>
  );
}

function AutomationKanbanBoard({
  stages,
  cards,
  onOpen,
  onMove,
}: {
  stages: ReportsAutomationStage[];
  cards: ReportsAutomationCard[];
  onOpen: (card: ReportsAutomationCard) => void;
  onMove?: (card: ReportsAutomationCard) => void;
}) {
  return (
    <section className="automation-kanban">
      {stages.map((stage) => {
        const stageCards = cards.filter((card) => card.stage === stage.id);
        return (
          <div className="automation-kanban-column" key={stage.id}>
            <div className="automation-kanban-column-head">
              <div>
                <h3>{stage.title}</h3>
                <p>{stage.description}</p>
              </div>
              <span>{stageCards.length}</span>
            </div>
            <div className="automation-kanban-stack">
              {stageCards.length > 0 ? stageCards.map((card) => (
                <AutomationKanbanCard key={card.id} card={card} onOpen={onOpen} onMove={onMove} />
              )) : <div className="automation-empty-column">No cards yet</div>}
            </div>
          </div>
        );
      })}
    </section>
  );
}

function AutomationDetailModal({ modal, onClose }: { modal: ReportsModalState; onClose: () => void }) {
  if (!modal) return null;

  return (
    <div className="reports-modal-overlay altynx-modal-overlay" role="presentation">
      <article aria-modal="true" className="automation-detail-modal" role="dialog">
        <header className="reports-modal-header">
          <div>
            <span>Details</span>
            <h2>{modal.title}</h2>
            <p>{modal.subtitle}</p>
          </div>
          {modal.amount ? <strong>{modal.amount}</strong> : null}
        </header>

        <div className="reports-modal-grid">
          {modal.items.map((item) => (
            <DetailField key={`${item.label}-${item.value}`} label={item.label} value={item.value} />
          ))}
        </div>

        <div className="reports-modal-note">
          <span>Recommended next action</span>
          <p>{modal.note}</p>
        </div>

        <footer className="reports-modal-footer">
          {modal.actions.map((action, index) => (
            <button key={action} className={index === 0 ? "primary-btn" : "secondary-btn"} type="button">
              {action}
            </button>
          ))}
          <button className="secondary-btn" type="button" onClick={onClose}>Close details</button>
        </footer>
      </article>
    </div>
  );
}

