function SupportQueue({ onNavigate }: { onNavigate?: (page: string) => void }) {
  const stages: ReportsAutomationStage[] = [
    { id: "new-message", title: "New Message", description: "Fresh support messages" },
    { id: "needs-reply", title: "Needs Reply", description: "Reply should be prepared" },
    { id: "waiting-customer", title: "Waiting Customer", description: "Waiting for buyer response" },
    { id: "needs-owner", title: "Needs Owner", description: "Owner missing" },
    { id: "escalated", title: "Escalated", description: "Needs team review" },
    { id: "recovery-created", title: "Recovery Action Created", description: "Moved to recovery" },
    { id: "resolved", title: "Resolved", description: "Closed or reviewed" },
  ];
  const [cards, setCards] = useState<ReportsAutomationCard[]>(supportQueueSeedCards);
  const [modal, setModal] = useState<ReportsModalState>(null);
  const [activeFilter, setActiveFilter] = useState("All");
  const filters = ["All", "Instagram", "WhatsApp", "Email", "Order Issue", "Payment Issue", "Service Booking", "Escalated", "Resolved"];
  const visibleCards = cards.filter((card) => {
    if (activeFilter === "All") return true;
    const text = `${card.source} ${card.sourceType} ${card.status} ${card.relatedPage}`.toLowerCase();
    return text.includes(activeFilter.toLowerCase().replace(" issue", ""));
  });

  function openSupport(card: ReportsAutomationCard) {
    setModal({
      title: card.title,
      subtitle: `${card.source} · ${card.sourceType}`,
      amount: card.moneyOpen,
      items: [
        { label: "Source", value: card.source },
        { label: "Issue type", value: card.sourceType },
        { label: "Priority", value: card.priority },
        { label: "Owner", value: card.owner },
        { label: "Linked recovery value", value: card.moneyOpen },
        { label: "Related page", value: card.relatedPage },
      ],
      note: card.nextStep,
      actions: ["Prepare reply", "Assign owner", "Create recovery action", "Add team note", "Mark resolved"],
    });
  }

  function moveSupport(card: ReportsAutomationCard) {
    const index = stages.findIndex((stage) => stage.id === card.stage);
    const nextStage = stages[(index + 1) % stages.length]?.id ?? "resolved";
    setCards((current) => current.map((item) => item.id === card.id ? { ...item, stage: nextStage, status: stages.find((stage) => stage.id === nextStage)?.title ?? item.status } : item));
  }

  return (
    <div className="reports-automation-page support-queue-page">
      <section className="reports-hero-card">
        <div>
          <span>Recovery-focused support</span>
          <h2>Support Queue</h2>
          <p>Turn support messages into recovery actions without making Altynx a full support desk.</p>
        </div>
        <button className="primary-btn" type="button" onClick={() => onNavigate?.("Order Issues")}>Open Order Issues</button>
      </section>

      <section className="reports-kpi-grid">
        <ReportsValueCard label="Messages" value={`${cards.length}`} caption="Support items visible" tone="cyan" />
        <ReportsValueCard label="Needs reply" value={`${cards.filter((card) => card.stage === "needs-reply").length}`} caption="Prepare response" tone="amber" />
        <ReportsValueCard label="Escalated" value={`${cards.filter((card) => card.stage === "escalated").length}`} caption="Needs operations" tone="rose" />
        <ReportsValueCard label="Open recovery value" value="$1.8K" caption="Potential recovery" tone="emerald" />
      </section>

      <ReportsFilterRow filters={filters} active={activeFilter} onChange={setActiveFilter} countLabel={`${visibleCards.length} support items · 25 per page`} />
      <ReportsStatusBanner eyebrow="Support status" title="Support messages can become recovery actions">Prepare replies, assign owners, create recovery actions, move to order/payment recovery, or mark resolved.</ReportsStatusBanner>
      <AutomationKanbanBoard stages={stages} cards={visibleCards} onOpen={openSupport} onMove={moveSupport} />
      <ReportsPagination total={visibleCards.length} label="support items" />
      <AutomationDetailModal modal={modal} onClose={() => setModal(null)} />
    </div>
  );
}

type WorkflowChannel =
  | "Manual Copy"
  | "WhatsApp"
  | "Instagram DM"
  | "Meta Inbox"
  | "Facebook Messenger"
  | "Email"
  | "SMS"
  | "Team note"
  | "Action Status Update";

type WorkflowEventKind =
  | "message_update"
  | "template_created"
  | "template_copied"
  | "note_added"
  | "teammate_notified"
  | "workflow_update_requested"
  | "status_marked"
  | "recovery_action_created"
  | "manual_record_added"
  | "queue_movement"
  | "owner_update"
  | "snoozed"
  | "thread_closed"
  | "record_reopened"
  | "related_case_opened";

type WorkflowEventStatus =
  | "Pending action sync"
  | "Ready for action sync"
  | "Internal notification queued"
  | "Manual copy logged";

type WorkflowEventRecord = {
  id: string;
  eventType: WorkflowEventKind;
  actionLabel: string;
  sourcePage: string;
  relatedRecord: string;
  channel: WorkflowChannel;
  status: WorkflowEventStatus;
  note: string;
  createdAt: string;
};

type PendingWorkflowPrompt = {
  eventType: WorkflowEventKind;
  actionLabel: string;
  sourcePage: string;
  relatedRecord: string;
  defaultChannel: WorkflowChannel;
  needsChannel: boolean;
};

const workflowChannels: WorkflowChannel[] = [
  "Manual Copy",
  "WhatsApp",
  "Instagram DM",
  "Meta Inbox",
  "Facebook Messenger",
  "Email",
  "SMS",
  "Team note",
  "Action Status Update",
];

const workflowEventStorageKey = "altynx_workflow_events";

function normalizeWorkflowText(value: string) {
  return value.replace(/\s+/g, " ").trim();
}

function getWorkflowEventKind(actionText: string): WorkflowEventKind | null {
  const text = actionText.toLowerCase();

  if (!text || ["close", "cancel", "done", "previous", "next", "stay here"].includes(text)) {
    return null;
  }

  if (text.startsWith("view ") || text === "view more" || text === "view details") {
    return null;
  }

  if (text.includes("open recovery queue") || text.includes("open queue")) {
    return null;
  }

  if (text.includes("copy template")) return "template_copied";
  if (text.includes("create new template") || text.includes("create template")) return "template_created";
  if (text.includes("mention teammate") || text.includes("notify teammate")) return "teammate_notified";
  if (text.includes("Team note") || text.includes("management note") || text.includes("save note")) return "note_added";
  if (text.includes("request re-sync") || text.includes("request resync") || text.includes("send update to workflow") || text.includes("sync action") || text.includes("sync manual")) return "workflow_update_requested";
  if (text.includes("open related")) return "related_case_opened";
  if (text.includes("Add to today’s follow-up list") || text.includes("move to") || text.includes("Add priority buyers to today’s follow-up list") || text.includes("queue")) return "queue_movement";
  if (text.includes("assign") || text.includes("reassign")) return "owner_update";
  if (text.includes("snooze")) return "snoozed";
  if (text.includes("close thread")) return "thread_closed";
  if (text.includes("reopen")) return "record_reopened";
  if (text.includes("create assigned action") || text.includes("create recovery action") || text.includes("create recovery case") || text.includes("create case") || text.includes("create payment recovery")) return "recovery_action_created";
  if (text.includes("add manual") || text.includes("add buyer") || text.includes("add waitlist") || text.includes("add refill") || text.includes("add inactive") || text.includes("capture inquiry") || text.includes("add opportunity") || text.includes("add record")) return "manual_record_added";
  if (text.includes("mark ") || text.includes("resolve") || text.includes("recover") || text.includes("reviewed") || text.includes("sent")) return "status_marked";
  if (text.includes("send") || text.includes("email") || text.includes("whatsapp") || text.includes("instagram") || text.includes("dm") || text.includes("message") || text.includes("notify")) return "message_update";

  return null;
}

function getDefaultWorkflowChannel(actionText: string): WorkflowChannel {
  const text = actionText.toLowerCase();

  if (text.includes("whatsapp")) return "WhatsApp";
  if (text.includes("facebook") || text.includes("messenger")) return "Facebook Messenger";
  if (text.includes("meta")) return "Meta Inbox";
  if (text.includes("instagram") || text.includes(" dm")) return "Instagram DM";
  if (text.includes("email")) return "Email";
  if (text.includes("sms")) return "SMS";
  if (text.includes("note") || text.includes("teammate") || text.includes("mention")) return "Team note";
  if (text.includes("workflow") || text.includes("sync") || text.includes("re-sync")) return "Action Status Update";

  return "Manual Copy";
}

function workflowActionNeedsChannel(actionText: string, eventType: WorkflowEventKind) {
  const text = actionText.toLowerCase();

  if (["message_update", "teammate_notified"].includes(eventType)) return true;

  if (
    eventType === "status_marked" &&
    (text.includes("sent") || text.includes("reminder") || text.includes("notice") || text.includes("follow-up") || text.includes("winback"))
  ) {
    return true;
  }

  if (eventType === "template_copied") return true;

  return false;
}

function getWorkflowStatusForChannel(channel: WorkflowChannel): WorkflowEventStatus {
  if (channel === "Manual Copy") return "Manual copy logged";
  if (channel === "Team note") return "Internal notification queued";
  return "Pending action sync";
}

function getWorkflowContextFromElement(element: HTMLElement, sourcePage: string) {
  const container = element.closest("article, .panel-card, .glass-card, .recovery-row, .product-card, .rt-card, .tl-card, .ra-card, .rw-card, .ib-card, .rr-card");
  const heading = container?.querySelector("h1, h2, h3, strong");
  const text = normalizeWorkflowText(heading?.textContent ?? "");

  return text || sourcePage;
}

function saveWorkflowEventToStorage(event: WorkflowEventRecord) {
  if (typeof window === "undefined") return;

  try {
    const existing = JSON.parse(window.localStorage.getItem(workflowEventStorageKey) ?? "[]") as WorkflowEventRecord[];
    const nextEvents = [event, ...existing].slice(0, 100);
    window.localStorage.setItem(workflowEventStorageKey, JSON.stringify(nextEvents));
    window.dispatchEvent(new CustomEvent("altynx-workflow-event", { detail: event }));
  } catch {
    window.localStorage.setItem(workflowEventStorageKey, JSON.stringify([event]));
  }
}


