function WorkspaceSearchBox({
  activePage,
  pages,
  onNavigate,
  onToast,
}: {
  activePage: string;
  pages: string[];
  onNavigate: (page: string) => void;
  onToast: (message: string) => void;
}) {
  const [query, setQuery] = useState("");
  const [modalOpen, setModalOpen] = useState(false);
  const normalizedQuery = query.trim().toLowerCase();

  useEffect(() => {
    if (typeof document === "undefined") return;

    const modalSelector = '[aria-modal="true"], .buyer-modal-backdrop, .segment-modal-backdrop, .action-history-modal, .action-history-popup';
    const updateModalState = () => {
      const hasOpenModal = Boolean(document.querySelector(modalSelector)) || document.body.classList.contains("search-hidden-when-modal-open");
      setModalOpen(hasOpenModal);
      if (hasOpenModal) setQuery("");
    };

    updateModalState();
    const observer = new MutationObserver(updateModalState);
    observer.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ["class"] });

    window.addEventListener("altynx:modal-open-state", updateModalState);
    return () => {
      observer.disconnect();
      window.removeEventListener("altynx:modal-open-state", updateModalState);
    };
  }, []);

  const visibleResults = useMemo(() => {
    if (!normalizedQuery) return [];

    return workspaceSearchIndex
      .filter((item) => pages.includes(item.page))
      .map((item) => {
        const haystack = [
          item.page,
          item.title,
          item.description,
          item.tag,
          ...item.keywords,
        ]
          .join(" ")
          .toLowerCase();

        const score =
          (item.page === activePage ? 2 : 0) +
          (haystack.includes(normalizedQuery) ? 4 : 0) +
          item.keywords.filter((keyword) => keyword.includes(normalizedQuery)).length;

        return { ...item, score };
      })
      .filter((item) => item.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, 8);
  }, [activePage, normalizedQuery, pages]);

  function goToResult(page: string, title: string) {
    onNavigate(page);
    onToast(`Opened ${title}. Use the page filters or View more buttons to continue the search.`);
    setQuery("");
  }

  if (modalOpen) {
    return null;
  }

  return (
    <div className="workspace-search-shell">
      <label htmlFor="workspace-page-search" className="sr-only">
        Search pages and recovery records
      </label>
      <input
        id="workspace-page-search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        placeholder="Search pages, buyers, channels, queues..."
      />
      {query ? (
        <button aria-label="Clear search" className="workspace-search-clear" type="button" onClick={() => setQuery("")}>
          ×
        </button>
      ) : null}
      {visibleResults.length > 0 ? (
        <div className="workspace-search-results">
          {visibleResults.map((result) => (
            <button key={result.page} type="button" onClick={() => goToResult(result.page, result.title)}>
              <span>{result.tag}</span>
              <strong>{result.title}</strong>
              <p>{result.description}</p>
            </button>
          ))}
        </div>
      ) : normalizedQuery ? (
        <div className="workspace-search-results empty">
          <p>No direct match. Try buyer, payment, Meta, Facebook, restock, review, or source.</p>
        </div>
      ) : null}
    </div>
  );
}


