function handleSharedRunQueueComplete(result: RunQueueResult) {
  window.dispatchEvent(
    new CustomEvent("altynx-run-recovery-queue", {
      detail: {
        page: result.pageKey,
        scope: result.scopeId,
        area: result.areaId,
        timing: result.timing,
        includedChanges: result.includedChangeIds,
        channels: result.selectedChannels,
        scheduledFor: result.scheduledLabel,
      },
    }),
  );

  const timingMessage = result.timing === "review-only"
    ? "Review set prepared. Nothing has been sent or run yet."
    : result.timing === "schedule-later"
      ? `Selected queue scheduled for ${result.scheduledLabel}.`
      : "Selected queue started. Connected workflows can now pick up the approved recovery work.";
  setQuickToast(timingMessage);

  addRecoveryActivity({
    category: result.timing === "review-only" ? "Team Actions" : "Automation",
    title: result.timing === "review-only"
      ? "Review set prepared"
      : result.timing === "schedule-later"
        ? "Recovery queue scheduled"
        : "Recovery queue started",
    description: result.timing === "review-only"
      ? `${result.scopeLabel} from ${result.areaLabel} was prepared for review only through ${result.selectedChannels.join(", ")}.`
      : result.timing === "schedule-later"
        ? `${result.scopeLabel} from ${result.areaLabel} is scheduled for ${result.scheduledLabel} through ${result.selectedChannels.join(", ")}.`
        : `${result.scopeLabel} from ${result.areaLabel} was sent into connected workflows through ${result.selectedChannels.join(", ")}.`,
    impactBadge: result.timing === "review-only" ? "Prepared" : result.timing === "schedule-later" ? "Scheduled" : "Queue started",
    relatedRecord: result.areaLabel,
    owner: "Recovery Lead",
    status: result.timing === "review-only" ? "Prepared" : result.timing === "schedule-later" ? "Scheduled" : "Started",
    nextAction: result.timing === "review-only"
      ? "Review the prepared actions before running them."
      : result.timing === "schedule-later"
        ? "Review scheduled queue activity when the chosen run time arrives."
        : "Connected workflows can now pick up the approved recovery work.",
    tone: result.timing === "review-only" ? "amber" : "emerald",
  });
}

